CREATE TEMP TABLE editorial_rollback ON COMMIT DROP AS SELECT value AS p FROM jsonb_array_elements($editorial_payload$[{"id":"c075a8d8-ff58-4335-8b35-62c482492865","slug":"prepmeal-batch3-04","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"7ed436a297e3d779ea658452fca8dcbdd61c018e1965f9db64416e78f165d89b","cooking_tips":["麵餅先壓入煮汁，開始變軟才輕拆，避免外層已爛、中心仍硬。","這道菜棄用公仔麵調味包；醬汁已含海鮮醬及老抽，不要再倒入粉包。"],"pairing_suggestions":["本餐已包含主食，可配「清炒芥蘭」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"ba76a284-8dca-4002-bede-39fb698983b2","slug":"shanghai-stir-fried-rice-cakes","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"0fc78d7afbb0393153edd42ca05dd940d80eef287bf530261c9cd7b1054ac7c7","cooking_tips":["年糕黏成一團時先按包裝處理並鬆開，不要靠大力翻鏟硬拆。","清水分次加至年糕軟身便足夠，並非每次都要用盡選配40毫升。"],"pairing_suggestions":["本餐已包含主食，可配「蒜蓉西蘭花」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"30aaa4c4-48d3-4e2b-8d43-82e48087965b","slug":"poached-baby-napa","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"8867e526e34bd04828f07a7a83a06238d87e6da0419f9bf924b61dd965190cf4","cooking_tips":["娃娃菜厚梗向下接觸湯汁，讓菜梗與較薄菜葉較接近同時煮軟。","先試煮好的湯再決定是否加鹽，盒裝雞湯的鹹度會因品牌而異。"],"pairing_suggestions":["可配「蒸水蛋」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"793ba258-c35b-4c26-a7cc-e08b64541dcf","slug":"poached-spinach-broth","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"33494ae30d8b9da495bb7f0cac1293c437f8b49125d86aee92565cab922f9e7e","cooking_tips":["菠菜入湯後輕壓浸入熱湯，菜葉軟化便檢查，避免一直煮到葉爛。","洗菠菜時把葉柄間的泥沙沖淨並瀝水，才不會把多餘洗菜水帶入湯內。"],"pairing_suggestions":["可配「蒸水蛋」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"b43272f4-41a7-49b9-92cd-a273435cbf92","slug":"beef-chow-fun","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"04bc4c4f1582e89b1962edb37fd8c2dfe4379fd8b2a0dd85fb0c055ebcdbb8d4","cooking_tips":["濕河粉先輕輕鬆開，入鑊後用推拌代替不停鏟碎。","牛肉先盛起是分段炒的安排；最後回鑊仍須炒至全熟，不停在表面轉色。"],"pairing_suggestions":["本餐已包含主食，可配「清炒菜心」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"aa83c327-b63c-4e3e-bcf5-1e99469c0ddf","slug":"dry-fried-green-beans","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"697bebac64cf486351ad3dcd2bc96e37b6c9245b89516771de80f72dfe7cec58","cooking_tips":["四季豆表面起皺仍可能未熟，須把內外徹底煮熟後才食用。","蒜蓉按步驟後下，避免陪四季豆炒十多分鐘而先變黑發苦。"],"pairing_suggestions":["可配「孜然香辣烤豆腐」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[{"title":"食物安全中心：未煮熟豆類中的天然毒素","url":"https://www.cfs.gov.hk/tc_chi/multimedia/multimedia_pub/multimedia_pub_fsf_139_04.html"}]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"5d0e5bd3-3573-4df1-8257-6b5c555feb0b","slug":"peking-pork-ribs","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"ca0aff7c19b9dcea8412fac725595c62b4809886279d59e9591290f3af41b591","cooking_tips":["京都汁留待排骨已熟才加入，糖與茄汁否則容易在肉熟前煎焦。","排骨最厚肉部應達75°C並維持至少30秒；量度時避開骨頭，不只看金黃外皮。"],"pairing_suggestions":["可配「清炒菜心」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}]},"changed_steps":[{"step_no":1,"old":"排骨沖洗後瀝乾，加生抽拌勻醃 10 分鐘，再沾上生粉。","text":"排骨檢查並去除可見骨碎，用廚紙抹乾，加生抽拌勻冷藏醃10分鐘，再薄沾材料表的生粉。"}],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":[{"text":"排骨檢查並去除可見骨碎，用廚紙抹乾，加生抽拌勻冷藏醃10分鐘，再薄沾材料表的生粉。","step_no":1},{"text":"平底鑊加入食油，中火煎排骨至金黃。","step_no":2},{"text":"轉小火，加蓋煮 6 至 8 分鐘至熟透。","step_no":3},{"text":"喼汁、茄汁、糖及白醋拌勻成京都汁，倒入鑊中。","step_no":4},{"text":"中火煮至醬汁濃稠並包住排骨。","step_no":5},{"text":"醬汁亮身、排骨熟透即可。","step_no":6}]},{"id":"751e3d89-9f5f-4089-8288-374831d4b8c5","slug":"winter-melon-shrimp-tofu-glass-noodle-pot","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"b6382ccfe873c20fb471e8a2ac32c78aa8d7f34c037d2ae0ce997f0fbd732069","cooking_tips":["粉絲會繼續吸湯，按包裝煮透後保留湯汁，不要刻意收成乾煲。","嫩豆腐加入後輕推入湯，蝦仁最後煮熟，避免大力翻炒把豆腐攪碎。"],"pairing_suggestions":["本餐已包含主食，可配「清炒椰菜」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"8f02080a-b2a9-4700-b00b-d0f486ae0c29","slug":"winter-melon-dried-shrimp-soup-xhs","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"349e4d277681451b0a1893b938bf87ae1ecb70c5ee46d46cd7178d67c1de2fea","cooking_tips":["冬瓜切成厚薄相若的小件，煮至半透明並軟身，較不會有幾件仍硬。","蝦米已有鹹鮮味，鹽留到冬瓜煮好後試味再加。"],"pairing_suggestions":["可配「肉碎豆腐」與「蒜蓉生菜」，再按需要配主食；本頁的湯不是另外的飯量。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"37e9e8b3-9ec8-4236-bfb9-189ec0cc5c66","slug":"prepmeal-batch4-12","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"c47b2f4d529fd47057b4fd139302399bd9d2824d65066c0f64f62078f4fd785b","cooking_tips":["冬瓜先略煎再回鍋炆，最後以瓜件可輕易刺入判斷軟度，不只看十五分鐘。","15毫升勾芡水與生粉先拌勻，加入前再攪一次，薄芡煮滾便可收火。"],"pairing_suggestions":["可配「蒜蓉生菜」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"f6c30911-7e95-4286-8511-5d431aa06c2e","slug":"prepmeal-batch3-12","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"2becfdcaa392835babb971a8f1a21539f225495475d4666aca3da97b23170539","cooking_tips":["勝瓜的硬稜削淨，瓜件切成相若厚度，避免軟瓜肉中仍夾硬皮。","炒蛋先盛起，等瓜煮軟才回鑊；需要補水時逐少加入，不把整碟炒成湯。"],"pairing_suggestions":["可配「清炒椰菜」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"c987684d-6054-4a8e-8157-7634cbdda1e1","slug":"luncheon-meat-scrambled-egg","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"428f55a0b5134863b535bc90d0a57a9fc660837dc80862013b4891d0d8a23eae","cooking_tips":["午餐肉先煎香再轉小火下蛋，蛋液較容易形成柔軟蛋塊。","午餐肉已有鹹味，本版不另加鹽；雞蛋須完全凝固後才上碟。"],"pairing_suggestions":["可配「清炒椰菜」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"e7afd2fb-eb3f-4f9e-babe-5c3c20c089c2","slug":"prepmeal-batch3-22","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"9a1bca562cddb2b6def77487cbfd0cb87a650aefb92e647d6cfb2b0d910d3354","cooking_tips":["薯仔粒按步驟切至不大於8毫米，太大會出現表面上色但中心仍硬。","確認薯仔可輕易刺穿才加入午餐肉及紅椒，避免其他材料陪未熟薯仔久炒。"],"pairing_suggestions":["這道菜已有薯仔，可配「清炒芥蘭」；其他主食按整餐份量安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"c33d2e50-6191-4830-8c20-368b188396e3","slug":"pumpkin-soup","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"c39ff6755c4219b9d7fe75b787b2491c85c4ed59ea7cdb74a035241f8d22b9a3","cooking_tips":["南瓜煮至可壓散才打蓉，湯的細滑度不只取決於攪拌時間。","如用攪拌機處理熱湯，先依機器的熱食安全指示操作，勿密封不適用熱液的容器。"],"pairing_suggestions":["可配「肉碎豆腐」與「蒜蓉生菜」，再按需要配主食；本頁的湯不是另外的飯量。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"07ae992e-ee0a-4002-b7b9-a8ec848d13da","slug":"prepmeal-batch4-22","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"38f2329f869431205af4a84a73084b329246f396b9c62eefc32ae34203728d32","cooking_tips":["浸米水要瀝走，與入鍋的150毫升雞湯分開計，不能把浸米水一併當煮飯水。","雞絲鋪飯後仍須煮至全熟；若米硬而鍋已乾，按步驟逐次補熱水，勿繼續乾燒。"],"pairing_suggestions":["本餐已包含主食，可配「蒜蓉西蘭花」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"ae8896a9-a3c5-4bfa-b886-fbf25fa3192e","slug":"carbonara-pasta","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"5ae489511f809a7b6c073f7639f07377ab832b3735e4a389dd8fd85ff7653437","cooking_tips":["必須用巴士德消毒全蛋；離火拌醬並不能保證普通生蛋已徹底煮熟。","預留45毫升煮麵水逐少加入，並非全倒；鑊先離火才拌蛋芝士液，避免結成炒蛋。"],"pairing_suggestions":["本餐已包含主食，可配「清炒椰菜」；飯麵不必重複加一份。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"b8cd10e9-6682-4291-a138-8affc8d46aa0","slug":"prepmeal-batch2-24","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"742b7437349e6323c917fed77e628dad1f6d69bec01d7cbc4d69319193c396ef","cooking_tips":["叉燒蜜汁受熱容易變焦，用中火炒熱叉燒後才加入蛋液。","牛奶與清水是兩個版本，按選用材料擇一；不要把替代用水再加在牛奶之上。"],"pairing_suggestions":["可配「清炒芥蘭」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"f9b874d8-62a2-430c-abe3-a12376fe94b9","slug":"prepmeal-batch2-05","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"86d09884bb438198546b6b6c0ed09e9f560386595947d9407ead1e6dfa072903","cooking_tips":["麻油用中小火炒薑蒜，不用把油燒至冒煙才放雞件。","九層塔留到收尾才拌入；雞件先量度最厚近骨肉部，須達75°C至少30秒。"],"pairing_suggestions":["可配「清炒椰菜」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"8bb606da-1fa9-4a7b-b7c9-77a8c7286bce","slug":"tuna-corn-baked-potato","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"63b6e064a228879acc51b367292d34f090854c24f552efcd9dcfe45a3d43f826","cooking_tips":["先確認整個薯仔中心軟熟，再切開填餡，最後數分鐘只用來把餡熱透及融芝士。","罐頭吞拿魚瀝乾再拌粟米，避免餡料把薯肉浸得太濕。"],"pairing_suggestions":["本餐已包含主食，可配「清炒菜心」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"26321be2-7fa8-47cf-9fcb-4a865bfbe7f3","slug":"prepmeal-batch3-17","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"e3c4c47a0839d2d3cde88d91f8ce0a1a0a06fb0a753d80d5b2a8800a4b0800c4","cooking_tips":["100毫升水只是參考，要按電飯煲半合白米刻度調整，不在刻度水之外再加一次。","先確認機器可煮75克米；粟米與牛油在飯熟後拌入，再蓋回讓粟米熱透。"],"pairing_suggestions":["本餐已包含主食，可配「清炒菜心」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"7bbaa915-bc87-4c6e-863c-206245a94af9","slug":"tuna-tofu-egg-pancake","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"53ca12ead49d0fdb1c13217f861c8f18985725773df879b67d4b430de8ca53d9","cooking_tips":["吞拿魚與豆腐先瀝乾，餅糊才較容易定形，不必為吸水而隨意加大量生粉。","小餅壓薄並用中小火煎，中心蛋液須熟透；表面金黃不等於內部已熟。"],"pairing_suggestions":["可配「蒜蓉生菜」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[{"step_no":6,"old":"每面煎 2 至 3 分鐘，煎至定型金黃即可。","text":"每面先煎約2至3分鐘，按厚度續煎至中心蛋糊完全熟透；中心達75°C並維持至少30秒，不能只看兩面金黃。"}],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":[{"text":"吞拿魚瀝乾水份，豆腐用廚紙吸走多餘水份後壓碎。","step_no":1},{"text":"雞蛋打散，與吞拿魚和豆腐放入同一碗中。","step_no":2},{"text":"加入生粉1茶匙、鹽1/8茶匙和白胡椒1/4茶匙，拌成可成形的濕潤餅糊。","step_no":3},{"text":"平底鑊加入少量油，中小火加熱。","step_no":4},{"text":"將餅糊分成 2 至 3 小份放入鑊中，壓平成小餅。","step_no":5},{"text":"每面先煎約2至3分鐘，按厚度續煎至中心蛋糊完全熟透；中心達75°C並維持至少30秒，不能只看兩面金黃。","step_no":6}]},{"id":"baa7c100-632b-4d95-8268-13ffcea570d5","slug":"miso-salmon","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"36a213aa7b2f78f878cd2b772f958951a89ed9e7eaf3b7faa1817ef4c99055e6","cooking_tips":["味噌醬含糖，表面過快變深色便留意火力，勿以醬色當魚肉熟度。","魚柳厚度會改變所需時間；量度最厚處中心達75°C並維持至少30秒，未熟須續焗。"],"pairing_suggestions":["可配「清炒菜心」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"dd1ee9ab-c33b-49e7-8fb0-769c6c908a69","slug":"miso-baked-fish-fillet","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"bdcbf1677e214228535e9dfeeb9fedc518cca8c0abc1969d818f477e2b00fe2f","cooking_tips":["焗盤先抹材料表的食油，魚柳抹乾後再塗味噌醬，避免醬汁過稀滑落。","味噌與糖容易先上色，檢查魚柳中心是否熟透，不能只看表面焦香。"],"pairing_suggestions":["可配「蒜蓉生菜」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"bcb63ab3-caa1-4f2b-bef8-e1c4fe846fba","slug":"miso-simmered-mackerel","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"3008203ba7e5a53e7ce839cb7ffda37851435cb3f86c670d15e7f54bdde4f0f4","cooking_tips":["味噌先用少量煮汁調開再回鑊，分兩次加入，比整坨放下去更容易均勻。","魚皮朝上後少翻動，以匙淋煮汁；原料須為未鹽漬鯖魚，鹽鯖魚不能直接當同一配方。"],"pairing_suggestions":["可配「蒜蓉西蘭花」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"9b57f597-db0f-4876-a085-d8c05f054ff7","slug":"miso-tofu-soup-xhs","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"c3f85fdbd503e8945b79ae502daae02a69fafc3662b233746d558a2115d103a8","cooking_tips":["味噌在小火下用湯匙調開，避免有鹹味集中的味噌團。","豆腐先煮熱才加味噌與紫菜，不必為加熱豆腐而把調好味的湯長時間大滾。"],"pairing_suggestions":["可配「孜然香辣烤豆腐」與「蒜蓉西蘭花」，再按需要配主食；本頁的湯不是另外的飯量。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"356789a4-fb3a-415a-b0d0-43c123f6e4c0","slug":"sweet-and-sour-pork","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"b92d3e1f6581feea6cd9ec7a8d0ebeca6f6abf6a995356ba4aae797468a8bda2","cooking_tips":["豬肉先煎至熟透才回鍋裹汁，酸甜汁含糖，不適合用來長時間把生肉煮熟。","豬肉回鍋後迅速拌至掛汁便盛起，避免煎好的外層長時間浸在汁中變軟。"],"pairing_suggestions":["可配「清炒椰菜」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"de2d96d1-3f46-4009-bde3-496a5c591e12","slug":"curry-beef-brisket-rice","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"f15d83d6a47d460ef867defb4105bafe0303a86e3a8ba4931abacebf5a0a2078","cooking_tips":["牛腩先炆、薯仔後下，才不會等牛腩軟腍時薯仔已煮散。","炆煮時間只是參考，牛腩須熟透並達到想要的軟度；鍋太乾按步驟少量補水。"],"pairing_suggestions":["本餐已包含主食，可配「清炒椰菜」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"c8307f45-9b0c-47e9-b540-67ba64c4a239","slug":"curry-chicken","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"d95566067a4c31c6fec19dd83f39ac113a6d51dbdc9f487b5d0212fe345c92e6","cooking_tips":["雞件表面轉色只是前段炒香，仍要在咖哩汁中繼續煮至中心熟透。","薯仔切成相若大小；先試煮好的咖哩汁再決定是否用選配鹽。"],"pairing_suggestions":["這道菜已有薯仔，可配「清炒芥蘭」；其他主食按整餐份量安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"b5bcb5a0-0726-44e1-ba3a-2d3f9a867bcb","slug":"prepmeal-25-16-chickpea-salad","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"33903a60b76678975f4c91a1c4185b1d9ff07da186140556b69bb7a6d4cae5d9","cooking_tips":["使用可即食的熟鷹嘴豆並瀝水；乾鷹嘴豆不能直接拌入當作同一材料。","雞肉、吞拿魚與Feta屬選配，按實際選用加入；加雞肉時須確認已熟，拌好保持冷藏。"],"pairing_suggestions":["可配「孜然香辣烤豆腐」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}],"served_cold":true},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"7a38108c-faf6-422c-b353-67581d940fb4","slug":"omelette","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"2e6284d75d5fb700efa237830572285b293e8f7a4af9aa12cf6ed44a3db80266","cooking_tips":["牛油只用小火煮溶，不待燒至深啡或冒煙才倒蛋。","對摺後中心也須煮至凝固；沒有用巴士德消毒蛋時，不把流動蛋液當成完成標準。"],"pairing_suggestions":["可配「清炒椰菜」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}]},"changed_steps":[{"step_no":5,"old":"用鑊鏟將蛋對摺，關火後靜置 30 秒。","text":"用鑊鏟將蛋對摺，繼續用小火煎至中心蛋液完全凝固，才關火稍靜置。"},{"step_no":6,"old":"滑到碟上即可，中心保持微嫩會更好食。","text":"確認中心沒有流動生蛋液後，用乾淨鑊鏟滑到碟上。"}],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":[{"text":"雞蛋打入碗中，加入牛奶、鹽少許和黑椒少許，打至蛋白蛋黃完全混合。","step_no":1},{"text":"平底鑊加入牛油，小火煮溶並搖勻鍋底。","step_no":2},{"text":"倒入蛋液，用小火煎，邊緣凝固時輕輕把蛋推向中間。","step_no":3},{"text":"蛋面仍微濕時停止攪動，讓底部定型。","step_no":4},{"text":"用鑊鏟將蛋對摺，繼續用小火煎至中心蛋液完全凝固，才關火稍靜置。","step_no":5},{"text":"確認中心沒有流動生蛋液後，用乾淨鑊鏟滑到碟上。","step_no":6}]},{"id":"78e61036-69dc-4e9e-af32-da9a2f526031","slug":"steamed-beef-tofu-baby-napa-rice","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"3465609881a46c5773f93942082f7955683437ab0b39225c9b0b07af9a139fbf","cooking_tips":["牛肉攤開不摺成厚團，娃娃菜鬆鋪，避免蒸盤中出現熱力難到的厚層。","150克熟飯已列入本餐；冷藏剩飯須另行徹底翻熱，不能把冷飯視作已加熱。"],"pairing_suggestions":["本餐已包含主食，可配「蒜蓉西蘭花」；飯麵不必重複加一份。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"8c5a7274-16a5-492f-a7f3-1877c7ed9017","slug":"cumin-spicy-baked-tofu","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"25587eb47ef595d5a93ff9ebb9b7e11397f9597093e99a9416f171bc747b6f3b","cooking_tips":["豆腐吸走表面水分再切厚塊，刷醬後平鋪，讓每塊較均勻受熱。","翻面才刷第二份醬；芝麻太早變深色便留意火力，不追求燶黑或油炸硬殼。"],"pairing_suggestions":["可配「蒜蓉生菜」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"5ac57672-0c3c-4eec-8976-2f219e4c54ae","slug":"prepmeal-batch3-11","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"5bd06ab72a0d3b82e7d605520beab47bb6b815bf69d1332e32c40b8f36f94c36","cooking_tips":["用合適的深焗盤單層排雞件與薯仔，水約到雞件半高，不用過大盤把汁攤乾。","揭錫紙時小心熱蒸氣；雞件中心須熟透，薯仔也須可輕易刺穿，兩者分別檢查。"],"pairing_suggestions":["這道菜已有薯仔，可配「蒜蓉生菜」；其他主食按整餐份量安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"ed42a6a1-78ad-47b1-bc86-4ac2200af9bf","slug":"prepmeal-batch2-23","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"536e7bf8d8bdf47ecf984ee07a669babdab6e9b1fc147b433f4ced7e0deb3178","cooking_tips":["薯仔烚至可刺入便瀝水切片，趁仍溫暖拌汁，避免反覆翻拌成薯蓉。","本版用普通美式黃芥末醬，不把芥末籽醬或辣芥末直接當同一份量替代。"],"pairing_suggestions":["這道菜已有薯仔，可配「蒜蓉生菜」；其他主食按整餐份量安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"730703aa-438f-416a-b775-c7eb1e4c5892","slug":"creamy-spinach-mushroom-chicken-rice","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"4dc6c73a0bfe7154a436e19c43969b735324705d681453f4454b246e4822d611","cooking_tips":["雞胸先煎熟盛起，待菇、菠菜與奶汁煮好才回鍋，避免一路久煮變韌。","白米90克是生米份量，要煮成飯才盛汁；不要直接把生米拌進忌廉汁。"],"pairing_suggestions":["本餐已包含主食，可配「蒜蓉西蘭花」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"fbe26ff9-0b29-480c-926f-e82e3f51123d","slug":"cream-of-mushroom-soup","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"9dfb970630009ec5de0f657c034fb06f9b03434c60bc820f7e843e13a6564996","cooking_tips":["蘑菇先炒軟出香味才加湯，不把生菇全部直接丟進奶湯久煮。","打滑熱湯時依攪拌機的熱液指示操作；加入忌廉後攪勻加熱，避免猛烈翻滾濺出。"],"pairing_suggestions":["可配「肉碎豆腐」與「清炒芥蘭」，再按需要配主食；本頁的湯不是另外的飯量。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"3ccd1f69-85cc-4dd6-bdc4-6f3ff2de9016","slug":"prepmeal-batch4-16","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"64bec10f1c99e2e2eccd137c9113a009a5a82b99eccbc58c6252845a824f5369","cooking_tips":["雞湯先煮減才加忌廉，不能靠把忌廉長時間大滾來收汁。","檸檬汁在熄火後才拌入；豬扒回鍋熱透即可，不陪忌廉汁一直煮到變韌。"],"pairing_suggestions":["可配「清炒菜心」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"d2027e11-d8b0-4af3-a459-774c7ad25bf5","slug":"prepmeal-batch2-19","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"cd405a0871d65db5ae64ab2473f89fc7217f0fdf427b65ca51aea89598c3a4e7","cooking_tips":["意粉先煮到接近熟才加急凍雜菜，避免雜菜跟整段煮粉時間一起煮爛。","青醬、橄欖油與芝士是全份總量，盛一人份時不要再重複淋一次。"],"pairing_suggestions":["這道菜已有意粉，可配「清炒菜心」；其他主食按整餐份量安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"ee639829-6ec3-4852-b036-1d0e58d66a45","slug":"prepmeal-batch2-09","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"41343218fc0d9ba819ce86597ad207a57388c4ce1adf69c599c87d34a20dddcb","cooking_tips":["蒜與辣椒只先略炒香，蒜片已深啡會令番茄醬帶苦味。","醬汁煮好才拌已熟長通粉；煮粉水按本版不另加鹽，不沿用外站的加鹽份量。"],"pairing_suggestions":["本餐已包含主食，可配「蒜蓉西蘭花」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"963283b2-68b2-441f-8aa1-b1d49494b32b","slug":"thai-basil-minced-pork-rice","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"f546977f2391d5d8932365b0c03fed9c67b6e9e92588712066f94629c7e3d086","cooking_tips":["豬肉碎下鑊後先炒散，並繼續煮至全熟，不把剛轉色當成安全終點。","九層塔最後短時間拌入；白飯180克已包括在材料內，不需再另配一碗飯。"],"pairing_suggestions":["本餐已包含主食，可配「蒜蓉西蘭花」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"51ffdd9a-22d7-43ca-8d54-96e877eee53c","slug":"prepmeal-batch2-01","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"079cbeca3cc0de1d87a577e3c61a81e79c75a0a7d6e2e93f1d7215a2a373b1b8","cooking_tips":["白胡椒粒與蒜先乾炒至香，再裝入食品用香料袋，方便食用前完整取走。","長時間煮湯要留意蒸發量，按步驟逐少補熱水；排骨軟腍與熟透都要確認。"],"pairing_suggestions":["可配「肉碎豆腐」與「蒜蓉生菜」，再按需要配主食；本頁的湯不是另外的飯量。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"3cc5efb4-ec35-4db7-b6e6-f6b555d2676c","slug":"prepmeal-batch3-01","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"fd58b35465b8422640cffc21e12b86f425a3c2e2ca16abdc39c2d642d163874e","cooking_tips":["三文魚先焗熟、去骨再拆碎，勿把未熟魚碎直接混進快炒的飯內。","冷藏飯須妥善保存並徹底翻熱；炒至飯、魚及蛋整體熱透才盛起。"],"pairing_suggestions":["本餐已包含主食，可配「清炒芥蘭」；飯麵不必重複加一份。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"2f8f2164-7cc7-40a7-b557-d6ea455dfa15","slug":"prepmeal-25-23-zaru-soba","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"9b5f595ed0e03556fabbd7c7517b06355b8be2abf6c8d388386035e834c62e9d","cooking_tips":["濃縮麵汁按實際品牌的稀釋比例調，不把材料表的水再加在已調好的麵汁之上。","冷麵煮熟後用可飲用冷水處理並瀝乾，拌好盡快吃，不能長放室溫。"],"pairing_suggestions":["本餐已包含主食，可配「蒜蓉生菜」；飯麵不必重複加一份。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}],"served_cold":true},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"ce9915f3-8cf3-4422-8721-d34216cfccb4","slug":"prepmeal-25-03-chicken-nanban","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"faebd06b906748e88f0f2421ed06da0a3a406612cc97bc29aad18250a0b24644","cooking_tips":["他他醬的熟蛋與裹雞的生蛋液分開準備，不把接觸生雞的蛋液拌進即食醬。","雞肉先煎熟再加南蠻汁；含糖醋汁容易先上色，不以外皮顏色判熟。"],"pairing_suggestions":["可配「清炒菜心」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"eb11805c-e2fc-4196-a890-40244bca9f74","slug":"prepmeal-25-21-miso-butter-mushrooms","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"c75cb0f39a9251ac8a7da3da4d5275071464815da011dd326e781a19b8466e71","cooking_tips":["菇炒出水後先略收乾才拌味噌汁，才不會把濃淡調整全留到最後。","兩份牛油分段用，收尾的一份熄火後拌入；選配雞肉或蝦要先煮熟。"],"pairing_suggestions":["可配「蒸水蛋」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"063799e5-790a-4a53-93bd-39775b3fcd00","slug":"prepmeal-batch2-18","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"6ad7355520f2d050463acf01e56e885bb50ae70b8c6f0e815e2ea6ee321adf26","cooking_tips":["平底鑊與焗爐只選一種，兩段時間不是相加；茄子先煮軟才淋田樂醬。","味噌醬以低火攪至有光澤，調醬水逐少加至可淋流，不在大火中煮焦糖味。"],"pairing_suggestions":["可配「孜然香辣烤豆腐」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"ae81d0bc-8f63-44c4-aca6-eed5c48b6706","slug":"japanese-curry-vegetable-rice","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"459357a362a469eeec7048b9a30e55e25fdcd60e1091bf4e77b84cb45921dc88","cooking_tips":["薯仔與甘筍先煮軟才下咖哩磚，避免濃汁先黏底而根菜仍硬。","咖哩磚用小火慢慢調散，攪勻鍋底；白飯180克已是本餐主食。"],"pairing_suggestions":["本餐已包含主食，可配「清炒菜心」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"ce02296b-8cd3-47ac-86df-154188604f6e","slug":"prepmeal-batch2-21","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"8dd269685fb196013d84a3f82bbc97ad4d211c73f661bc57ea60dc570fefcd88","cooking_tips":["咖哩粉與薯仔澱粉先用15毫升冷水拌勻，入湯前再攪一次，避免結粉團。","烏冬另按包裝煮熱瀝乾，再淋咖哩湯，不把麵的包裝水全部倒入湯內。"],"pairing_suggestions":["本餐已包含主食，可配「蒜蓉西蘭花」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"00aab1ac-1d4d-4434-8132-8787c4672d44","slug":"prepmeal-batch2-04","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"3768353de66279d5f64fe85ca52b7648b796011a817395788fde3250e30236d9","cooking_tips":["薄牛肉與蔬菜、豆腐切成易熟小件，煮至肉菜熟透才鋪飯。","本版白飯已列材料，不加原方可能出現的生蛋蘸汁或其他未列配料。"],"pairing_suggestions":["本餐已包含主食，可配「蒜蓉西蘭花」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"ffd3fc62-4335-4f2f-8de6-e66f8fdb4df1","slug":"prepmeal-25-17-okonomiyaki","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"490b24c16a7ae405d8c7a3e9dd7271c260f0c95071c2741dbec0b7bebabe8e2b","cooking_tips":["餅厚約2厘米，翻面時托住整塊，不能只煎到兩面金黃而中心蛋糊仍生。","選配豬肉或蝦先煮熟再拌糊；表面的醬、沙律醬與木魚花按全份量使用。"],"pairing_suggestions":["可配「清炒菜心」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"a4165f61-26cc-417b-b5f7-39ca17f365f9","slug":"prepmeal-batch4-23","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"c81d3a1394c4624564c6e00066cbb50fd29a0dfe47e5aa2b1f4175207d378d02","cooking_tips":["鮮濕炒麵按包裝處理，不能用相同重量的乾麵直接代替，吸水量與成品份量不同。","海鮮先炒熟盛起，待蔬菜與麵拌好才回鍋，避免一路炒到變韌。"],"pairing_suggestions":["本餐已包含主食，可配「蒜蓉生菜」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"afc398ca-ac87-43d5-8ced-2fb3e1a48507","slug":"prepmeal-batch3-06","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"23f05dfba6622208d258728d9d566dfa866102ce6082ccc5d055b2cebf069b39","cooking_tips":["鑊底的100毫升水在錫紙包外，不是倒入魚包的調味汁，煮時避免鑊底燒乾。","開包時讓蒸氣朝遠離面部的一側逸出，再檢查魚中心；未熟要封回續煮。"],"pairing_suggestions":["可配「蒜蓉西蘭花」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"616ed72f-1f0b-47bf-8888-dba8d79ef7b0","slug":"prepmeal-25-01-nikujaga","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"490960f9fea5afe190d8cdb61ad45907b0c0aa9afbfaa2ef5cc2b0b819f978a3","cooking_tips":["薯仔切成大小相若的塊，炆至可刺入後離火靜置吸汁，不用一直大火收乾。","荷蘭豆先汆熟留起，食前翻熱時才加入，避免整段炆煮後失去口感。"],"pairing_suggestions":["這道菜已有薯仔，可配「清炒菜心」；其他主食按整餐份量安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"6a61b440-2996-4f74-bb3f-a116c25ffa6c","slug":"prepmeal-25-05-tamagoyaki","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"bcb14de98d0ddb8b6dc2c294e5276227f416198ebab4979b57b5493676d0c0c9","cooking_tips":["每次倒薄層蛋液，讓新蛋液流到原蛋卷下面再卷起，避免外熟內生的厚夾層。","蛋卷內層也須完全熟透；雞肉、菠菜或鰻魚若選用，須先煮熟才加。"],"pairing_suggestions":["可配「清炒菜心」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"971115e3-ed72-40e3-86bf-054e3f9741c1","slug":"prepmeal-25-04-kinpira-gobo","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"6a7aec3c7205a542b4e6619655fcea8cecf96fcdb59a17a56023373b8077581e","cooking_tips":["牛蒡與甘筍切幼絲，粗細相若才較容易同時炒軟。","乾辣椒只在選用時加入；麻油不燒至冒煙，調味汁收乾便停火，避免糖汁焦苦。"],"pairing_suggestions":["可配「孜然香辣烤豆腐」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"24103b87-1d26-4d15-a0be-873823ff7081","slug":"prepmeal-batch2-14","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"35f5ffb15d3fc39d70b474add3e402e5f70ad54481ec83467fef3d468b05282e","cooking_tips":["豬肉薄片夾入每層白菜時盡量攤開，勿在中心堆成厚肉團。","鍋內排得整齊仍須檢查內層肉熟度；柚子豉油是另附蘸醬，不再煮成一鍋鹹湯。"],"pairing_suggestions":["可配「清炒椰菜」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"bba95d20-058e-4e69-840c-ab438aed6574","slug":"prepmeal-batch2-12","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"4d0c332574741cedff2b56370e6ab237a6e0e948930bad3f4c6c9a1bb2753279","cooking_tips":["灼熟菠菜後以可飲用冷水降溫，再擠走水分，芝麻醬才不會被菜水沖淡。","芝麻稍涼再磨碎拌汁；這是配菜，不能只因有芝麻便當成完整一餐。"],"pairing_suggestions":["可配「蒸水蛋」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[],"served_cold":true},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"238c2401-2eb8-43a4-9849-4c4623c97518","slug":"japanese-sweet-vinegar-chicken-lotus-root","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"1a12f71f68bd37683a1cdd22e07a55e247dda8168b5979c1ce1b04c4d13554e2","cooking_tips":["雞肉與蓮藕薄薄裹上全份生粉，不為追求厚脆皮再添粉。","雞肉熟透才加甘醋汁短時間掛面；汁收得快便先調低火力，別煮成焦糖硬殼。"],"pairing_suggestions":["可配「蒜蓉生菜」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"60e2dba0-1c51-45d1-96bd-66296651dec7","slug":"prepmeal-batch2-02","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"485e3437ba869fa8fca33c4f225d1d23d5cd54c84d3f8812f83bb7a7fcd4e079","cooking_tips":["薑汁調味先另拌留起，豬肉攤開煎後才加，避免一開始便把含糖醬煎焦。","薄片表面轉色後仍要煮至全熟；醬汁稍濃便盛起，避免反覆久煎變韌。"],"pairing_suggestions":["可配「蒜蓉生菜」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"f6c5bc7b-f5ce-4da4-bdff-14bbc9beaaef","slug":"ginger-teriyaki-chicken-meatballs","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"f3a375c34b37dcdf0d168dd82167422bf29475ea4742e4014611981181a0b743","cooking_tips":["蛋液打散後秤25克，不把材料表的半份蛋直接當成一整隻。","五塊肉丸合共一人份，每塊壓至約1.5厘米厚，最厚中心也須達75°C至少30秒。"],"pairing_suggestions":["可配「清炒菜心」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"29f64d43-dd17-4428-8708-445c8ecf6cd3","slug":"oyakodon","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"481c6b67ab389958d0295a37f0630b101e15fd671022065809138197ac042e45","cooking_tips":["用太大的鑊，少量湯汁容易很快蒸乾；以較小、有蓋的鍋具較容易控制。","白飯已列在一人份材料內；配餐時可加蔬菜或清湯，不必再加一碗飯。"],"pairing_suggestions":["可配蒜蓉西蘭花；如想加湯，可選不重複雞蛋的蔬菜清湯。"],"references":[{"title":"Kikkoman：Oyakodon","url":"https://www.kikkoman.com/en/cookbook/washoku/oyakodon.html"},{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"},{"title":"食物安全中心：清潔、消毒與衞生","url":"https://www.cfs.gov.hk/tc_chi/consumer_zone/safefood_all/clean_hygiene.html"}]},"changed_steps":[{"step_no":1,"old":"雞肉切件，洋蔥切絲，雞蛋輕輕打散。","text":"雞肉120克切成大小相若、約2厘米的小件；洋蔥60克切幼絲，兩隻雞蛋輕輕打散。生雞肉與熟食器具分開。"},{"step_no":2,"old":"平底鍋加入照燒汁約 1 湯匙和 2 湯匙水，放入洋蔥煮 2 分鐘。","text":"用有蓋的小平底鍋，加入照燒汁1湯匙及30毫升水，煮滾後加入洋蔥，中小火煮約2分鐘。"},{"step_no":3,"old":"加入雞肉，蓋上煮 4 至 5 分鐘至熟透。","text":"雞肉平鋪加入，煮滾後轉小火加蓋，煮約4至5分鐘；用食物溫度計確認最厚雞肉中心達75°C並維持至少30秒，未達標便繼續煮。"},{"step_no":4,"old":"倒入一半蛋液，煮至邊緣開始凝固。","text":"確認雞肉已熟後，倒入一半蛋液，保持小火，讓蛋液逐漸凝固，不要像炒蛋般大力翻動。"},{"step_no":5,"old":"再倒入餘下蛋液，蛋面微凝固時熄火。","text":"加入餘下蛋液，加蓋煮至雞蛋完全凝固、沒有流動的生蛋液；本版不以半熟蛋作完成標準。"},{"step_no":6,"old":"將雞肉滑蛋鋪在 180 克白飯上即可。","text":"把雞肉、洋蔥、熟蛋及鍋內餘汁鋪在180克熱白飯上，趁熱食用。"}],"ingredient_changes":[{"old":null,"new":{"id":"4d32e561-50ac-4bb4-be6e-43c12a72e397","name":"水","quantity":30,"unit":"ml","note":"起始煮食用水；鍋具蒸發較多時按需要少量補水，不增加油或醬料","optional":false}}],"old_recipe":{"description":"日式親子丼以雞肉、洋蔥和雞蛋煮成滑嫩蛋汁，鋪在白飯上，鹹甜溫和又飽肚。"},"new_recipe":{"description":"這個家常簡化版用現成照燒汁煮雞肉和洋蔥，再分兩次加入蛋液，鋪在180克白飯上。保留少量汁拌飯，本版雞肉和雞蛋均煮熟。"},"target_steps":[{"text":"雞肉120克切成大小相若、約2厘米的小件；洋蔥60克切幼絲，兩隻雞蛋輕輕打散。生雞肉與熟食器具分開。","step_no":1},{"text":"用有蓋的小平底鍋，加入照燒汁1湯匙及30毫升水，煮滾後加入洋蔥，中小火煮約2分鐘。","step_no":2},{"text":"雞肉平鋪加入，煮滾後轉小火加蓋，煮約4至5分鐘；用食物溫度計確認最厚雞肉中心達75°C並維持至少30秒，未達標便繼續煮。","step_no":3},{"text":"確認雞肉已熟後，倒入一半蛋液，保持小火，讓蛋液逐漸凝固，不要像炒蛋般大力翻動。","step_no":4},{"text":"加入餘下蛋液，加蓋煮至雞蛋完全凝固、沒有流動的生蛋液；本版不以半熟蛋作完成標準。","step_no":5},{"text":"把雞肉、洋蔥、熟蛋及鍋內餘汁鋪在180克熱白飯上，趁熱食用。","step_no":6}]},{"id":"c015cd96-b723-40e4-a74b-cb9b4c1b4a8e","slug":"prepmeal-batch3-25","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"eabff88e71982edc08ca17c9d63f44980d8798cd360b69a3b4688acfea79e53b","cooking_tips":["南瓜皮向下排成單層，炆煮時少翻動，避免軟化後攪散。","落蓋用可煮食的烘焙紙並留孔；汁近乾而南瓜未軟時按步驟少量補熱水。"],"pairing_suggestions":["可配「孜然香辣烤豆腐」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"c61074fb-2c0a-44d5-b4be-abe417b8e8ac","slug":"pork-vegetable-miso-soup","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"b951884be00cbf23255d51390e0c2e87c58e811ae4a066b768b5865027a1531f","cooking_tips":["根菜先煮，豬肉逐片撥散再加入，避免薄肉黏成一團而中心未熟。","味噌在根菜及肉已熟後用熱湯調開，倒回鍋後不長時間猛烈滾。"],"pairing_suggestions":["這道菜已有薯仔，可配「蒜蓉西蘭花」；其他主食按整餐份量安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"43383349-c72f-4752-954d-03e1e86c6eaa","slug":"prepmeal-batch4-24","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"fdba8f245f06a2398e23f3acb5d248653e3bdb0e9d6902ba8e88c513c56e4b75","cooking_tips":["生菜先充分瀝水，豬肉薄片包卷時不在內層重疊太厚。","肉卷收口先朝下定形，再逐面轉動；探針要檢查靠菜的內層肉，不只看外皮。"],"pairing_suggestions":["可配「清炒椰菜」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"4ce07cf9-9224-4764-897d-7b138aedcc3b","slug":"prepmeal-batch4-11","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"0e85d312bbb2f920369dd4c94f9a6ea2c4e95d75c2740c7a3baf3e41fa5b6fa3","cooking_tips":["白蘿蔔按步驟切約1厘米厚，太厚會在雞肉已熟時仍未軟。","味醂分兩次加入，不把兩份都在開始用掉；落蓋及小火有助保留煮汁。"],"pairing_suggestions":["可配「蒜蓉西蘭花」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"a9bc8a27-62d6-4696-b497-4ee843500560","slug":"prepmeal-batch4-20","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"136438bb6a7f32ad5b290322ebf8d2c921c162f84ac2b9f23377e983473a93ea","cooking_tips":["豬肉先炒熟，再下青瓜短炒，避免青瓜陪肉久炒而大量出水。","青瓜拍裂後切塊，紅甜椒先炒至稍軟；本版不另加芝麻或辣椒。"],"pairing_suggestions":["可配「蒜蓉西蘭花」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"38a689fc-9ecf-4719-accf-2d1a17a91672","slug":"tofu-hamburg-mixed-mushroom-sauce","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"f7fb726e19b52c41f13e76e5c7f4e55de8679915eb67d0c8121fd752e697f8ff","cooking_tips":["豆腐、洋蔥及蓮藕先按步驟瀝水放涼再拌蛋，太濕太熱都不利成形。","兩塊漢堡合共一人份，翻面用闊鏟托穩；菇汁的生粉水另調並煮滾成薄芡。"],"pairing_suggestions":["可配「蒜蓉西蘭花」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"53530b41-1a27-41ec-8ead-cf87ae1aaa59","slug":"prepmeal-25-02-soboro-don","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"671910dbb9a0e7f6167a1a0c88346bf902d3ade1aa3cb49f098244d118fc5de5","cooking_tips":["雞肉碎與蛋碎分鍋煮熟，糖也是兩份分開用，不能全部倒進同一鍋。","白飯、雞肉、蛋及青豆合共一份丼飯，增加人數時按總量放大後再平分。"],"pairing_suggestions":["本餐已包含主食，可配「清炒菜心」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"4a3c756d-a472-47b6-b0f2-0245dbbe4c70","slug":"prepmeal-batch4-02","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"4eba8ff231e747fbf1f63cf7b5ebb3e5fd53830be26267ef7f9a97148c2acd52","cooking_tips":["原料須用未調味鯖魚，鹽漬魚不能直接沿用這份撒鹽量。","醃後印走滲水再焗，皮朝上；魚厚度不同要檢查最厚中心，不只照計時取出。"],"pairing_suggestions":["可配「清炒芥蘭」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"af9625e5-46dd-4952-bb4b-2cfe34771927","slug":"singapore-fried-rice-vermicelli","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"60a3ae684c8b5827cdb9c07b8294f647767dc8ef65be23e24677a4dba015e565","cooking_tips":["米粉依包裝浸至可鬆開並瀝水，用筷子配鑊鏟提鬆，避免結團或鏟碎。","雞肉先炒至熟透再加米粉；全份油分兩段用，不為每次回鍋另加一次油。"],"pairing_suggestions":["本餐已包含主食，可配「清炒菜心」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"cfeeeff6-edcb-41f1-9fb1-8ae55a3bbf1d","slug":"steamed-pork-patty-with-preserved-mustard","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"d835579121b7a67503b9cd9c3416e89436f4f972a9165ab879a3825f4080ff96","cooking_tips":["梅菜先沖浸、擠乾再切碎，不能把浸菜鹽水一併加入肉餅。","肉餅攤至約1.5厘米厚，中心須達75°C至少30秒，蒸十二分鐘不是所有厚度都適用。"],"pairing_suggestions":["可配「清炒椰菜」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"bedaefbc-1601-411d-8aba-dc8ef234e96b","slug":"salt-pepper-tofu","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"f48f45f8b2cab6686bbf07c659ecad59c0f56cebe958b29659e30a4f138a91b3","cooking_tips":["豆腐吸乾表面水分才薄沾生粉，避免濕粉黏成厚厚一層。","蒜蓉在豆腐煎香後用小火加入，椒鹽留到收尾，避免長煎焦苦。"],"pairing_suggestions":["可配「蒜蓉生菜」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"1ab360fe-b0de-4652-aada-c4fbcb13077b","slug":"prepmeal-batch3-02","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"295cf75bb65e6449c883fec403b71b0656fe44fe9a45bee8bd2156f370ffd778","cooking_tips":["咖哩粉跟蒜以細火短炒出香，不把粉炒至深色焦苦。","椰奶微滾後才放蝦煮熟，最後拌檸檬汁，不讓蝦陪整段煮醬時間久煮。"],"pairing_suggestions":["可配「蒜蓉生菜」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"8df34ca9-b92d-4c71-b79a-7c8f2ad455ac","slug":"prepmeal-batch4-18","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"36c389e29fff573f7069106e99cf61ebcb8b90d61c01d87862aa00e13a96ca43","cooking_tips":["榨菜浸水後必須瀝乾，浸菜水不加進蒸碟，避免額外帶入鹹味。","肉片攤薄不厚疊；糖只能調整味道，不能把加入糖當成減少鈉含量。"],"pairing_suggestions":["可配「蒜蓉生菜」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"fe923544-02da-4eba-a61e-436366cf0d59","slug":"lemon-butter-fish-fillet","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"f3f0863896828c43d1cc893ef8a887a7a8691e5c9375b70e3f18177d95435ede","cooking_tips":["魚柳抹乾再入鑊，牛油不先燒焦；蒜頭只在實際選用時加入。","翻魚時托住整片，檸檬汁加入後轉小火；熟度看最厚魚肉，不只看外面金黃。"],"pairing_suggestions":["可配「清炒菜心」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"d5537271-e1a5-4a4a-9104-912066557bc8","slug":"prepmeal-batch3-07","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"1f11722a144676dcdcec41672cd718b2f13824bd36fcb83eccb76ddb96f30146","cooking_tips":["檸檬只刨黃色外皮，避免把白色部分一起刨入而帶苦味。","芝士離火才拌，預留麵水逐少補至順滑，不把所有麵水一次倒入。"],"pairing_suggestions":["本餐已包含主食，可配「蒜蓉生菜」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"9e92a54f-e6e2-4437-bed8-5cb31a9143c4","slug":"prepmeal-batch3-15","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"18813225457ea5a9bb0824999c8d3bc4fe72c79855a57942177ed3e4331f0385","cooking_tips":["花生醬與沙茶先用定量水拌開，避免熱鑊內留下幾團濃醬。","菜心先瀝乾上碟；牛肉回醬汁後仍須煮熟，不能停在前段表面轉色。"],"pairing_suggestions":["可配「清炒椰菜」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"79688204-3b31-4951-bdc4-59c695eabb01","slug":"prepmeal-batch2-07","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"97df958477fd3508155ee4a9fad5f8378ef7bf03400c36d3995a27412a24970f","cooking_tips":["烹調前剔走破殼及敲後不閉合的青口，煮後仍不開殼者也不要食用。","牛油麵粉先拌成團再逐少調入煮汁；白酒經煮食後不保證已完全無酒精。"],"pairing_suggestions":["可配「清炒椰菜」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}]},"changed_steps":[{"step_no":2,"old":"有蓋鍋放青口、乾蔥、約4克牛油及白酒，加蓋煮至青口自然開殼且熟透；煮後不開殼者丟棄。","text":"有蓋鍋放入青口、乾蔥、約4克牛油及白酒，加蓋煮至重新沸騰，保持滾煮至少5分鐘並確認青口熟透；煮後不開殼者丟棄。"}],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":[{"text":"青口刷洗去鬚，剔走破殼及敲後不閉合的活青口；乾蔥切碎。","step_no":1},{"text":"有蓋鍋放入青口、乾蔥、約4克牛油及白酒，加蓋煮至重新沸騰，保持滾煮至少5分鐘並確認青口熟透；煮後不開殼者丟棄。","step_no":2},{"text":"盛起青口留汁；餘下約4克軟牛油與麵粉拌勻，逐少加入湯汁攪煮至略稠。","step_no":3},{"text":"加鹽胡椒，醬汁回淋青口，撒番茜。酒不保證完全揮發。","step_no":4}]},{"id":"371093a9-4250-4990-8626-79b4be10dd38","slug":"prepmeal-batch3-13","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"977db543bc191e8ebc8191d7af2d1ed23b7615bf4f7c986776bb29d7f7d8e2fe","cooking_tips":["薄豬肉先攤散炒熟才加入泡菜與大蔥，避免肉片黏成厚團。","泡菜、生抽及味醂已提供調味，本版不額外加鹽，芝麻只在收尾拌入。"],"pairing_suggestions":["可配「清炒椰菜」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"f008e174-99f2-49f7-b32b-ea58e6f2b23d","slug":"prepmeal-25-12-tom-kha-gai","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"8fdeb77e1e558c00db025f017c697a1107c21540dbcd9b9ba596df9a5b07e758","cooking_tips":["香茅拍裂、南薑切片與青檸葉揉破是用來煮香湯，不當成可直接大口吃的配料。","雞肉先煮熟，青檸汁離火才加；食用前撈走香茅、南薑及葉片。"],"pairing_suggestions":["可配「豉汁蒸排骨」與「清炒椰菜」，再按需要配主食；本頁的湯不是另外的飯量。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"28cf0aee-c708-481c-8533-7b03ae9d0fb4","slug":"thai-lime-steamed-fish","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"5cb5fbb207c0334cb1da1eb84479a3d9adfa05cbe597b71b27eecb094d105934","cooking_tips":["蒜蓉與辣椒鋪勻，魚柳厚薄差異大時以最厚處熟度決定是否續蒸。","青檸汁在出鍋後才淋，檢查熟度仍須以魚肉中心為準，不能只看表面變白。"],"pairing_suggestions":["可配「清炒菜心」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"c8e34269-c73a-498b-a63d-8596faeddbe8","slug":"prepmeal-25-15-chicken-satay","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"1bdd9fccf12012517425fb2bc0b6a89c2faba523c153dba9e6654068d10f8917","cooking_tips":["醃雞用的椰奶與花生醬用的椰奶分開量好，不把接觸生雞的醃汁混入即食醬。","雞扒完全熟透才切件，花生醬另鍋以小火攪至幼滑，不在煎雞的高溫鑊內燒焦。"],"pairing_suggestions":["可配「清炒椰菜」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"8bfb5fc7-6031-400c-805a-ed19a70fc5c3","slug":"thai-pad-see-ew-chicken","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"2645a341ad37b399e0c1ba9bb241577ebb48bb8e9b3dbd21147b23732ea5c5ff","cooking_tips":["本版先炒蛋再炒雞，原鑊的油分兩次用，不因材料分開炒而重複加全份油。","雞肉前段只接近熟，回鑊後須煮至全熟；河粉用輕推拌開，避免鏟成碎條。"],"pairing_suggestions":["本餐已包含主食，可配「清炒芥蘭」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"17e8f091-aba8-4375-9327-64e0d82a3f99","slug":"thai-pineapple-fried-rice","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"630e22abb4c1e319a8d72110b03b84a1fb923927e520dcfe2967bf4a6b30031b","cooking_tips":["雞肉先煮熟、飯先炒散，菠蘿留後短炒，避免菠蘿陪長時間炒至大量出汁。","魚露按材料表總量分次拌入；冷藏飯須妥善保存，炒至整份熱透才吃。"],"pairing_suggestions":["本餐已包含主食，可配「蒜蓉西蘭花」；飯麵不必重複加一份。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"140cc939-2017-4c31-a833-0341300fa3b7","slug":"prepmeal-batch4-19","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"49080fd724f8487878b272a3ec7eb06555b8793aed282f71b3c86b20e602af91","cooking_tips":["椰菜去硬芯並瀝乾，菜塊保持相若大小，才較容易保留口感。","魚露已提供鹹味，不另加鹽；不沾鑊不能靠空鍋極高溫來追求鑊氣。"],"pairing_suggestions":["可配「豆腐雞蛋白菜卷」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"a2eee8c2-0e5f-48fb-bd2c-fc098b7b74ff","slug":"prepmeal-25-19-yum-woon-sen","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"3ee28c2f32daeb8e773fd8b775a0ad3422a0e414e3dca5e3fb06292fda36e026","cooking_tips":["粉絲、蝦與肉碎要先各自煮熟，再與已洗淨的蔬菜拌合，不以酸辣汁代替煮熟。","花生最後才拌，熟材料拌好後盡快食用或冷藏，不能因名為沙律就久放室溫。"],"pairing_suggestions":["這道菜已有乾綠豆粉絲，可配「清炒菜心」；其他主食按整餐份量安排。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}],"served_cold":true},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"94cea914-80cf-4bb7-a6b5-0c3039ce094d","slug":"thai-chicken-vermicelli","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"afa7758bfe7d2eeb1e8cd1907cc11b18bc9591ee1ddb605fbb5a1c3841e6a1fb","cooking_tips":["魚露先分醃雞與炒粉兩部分，不在最後又加入一次全份量。","米粉浸軟瀝乾後提鬆拌炒；雞絲先熟，少量水只用來幫助拌開粉，不煮成湯米。"],"pairing_suggestions":["本餐已包含主食，可配「蒜蓉西蘭花」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[{"step_no":5,"old":"加入餘下魚露及少量清水，炒至米粉吸收調味。","text":"加入餘下魚露及材料表最多15毫升選配清水，炒至米粉吸收調味。"}],"ingredient_changes":[{"old":null,"new":{"id":"4d32e561-50ac-4bb4-be6e-43c12a72e397","name":"水","quantity":15,"unit":"ml","note":"步驟已使用的煮食水；按材料表總量分配，不另計浸洗或倒走的汆水","optional":true}}],"old_recipe":{},"new_recipe":{},"target_steps":[{"text":"米粉用溫水浸軟後瀝乾；雞胸肉、洋蔥及甘筍切絲。","step_no":1},{"text":"雞絲可用材料表魚露的1/3份量拌勻，醃5分鐘；餘下留作炒米粉。","step_no":2},{"text":"鑊中加入食油1茶匙，先炒香洋蔥及甘筍，再加入雞絲炒至熟透。","step_no":3},{"text":"加入米粉，用筷子和鑊鏟一起拌炒，避免結成一團。","step_no":4},{"text":"加入餘下魚露及材料表最多15毫升選配清水，炒至米粉吸收調味。","step_no":5},{"text":"炒至米粉乾爽不黏鑊即可上碟。","step_no":6}]},{"id":"a857763a-b6b6-4df6-9005-81d31a6ea592","slug":"prepmeal-25-14-som-tam","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"1fcfb6f5cbccf78a8b71137e2e4d9bcaa29ff448548d3f2424af4712537eb1ea","cooking_tips":["青木瓜刨絲後才輕壓拌汁，不必把瓜絲壓至爛；棕櫚糖先在汁中調開。","豆角須先用沸水徹底煮熟、降溫再拌，不能把醬汁的酸味當成煮熟處理。"],"pairing_suggestions":["可配「豆腐雞蛋白菜卷」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[{"title":"食物安全中心：未煮熟豆類中的天然毒素","url":"https://www.cfs.gov.hk/tc_chi/multimedia/multimedia_pub/multimedia_pub_fsf_139_04.html"}],"served_cold":true},"changed_steps":[{"step_no":3,"old":"長豆角輕拍切段，車厘茄切半。","text":"豆角洗淨後用沸水徹底煮熟，再用可飲用冷水降溫、瀝乾切段；不可用未煮熟豆角拌沙律。車厘茄洗淨切半。"},{"step_no":4,"old":"大碗中把所有材料拌勻並輕壓，至木瓜絲稍軟；使用已烘花生可免開火。","text":"大碗中把木瓜絲、已煮熟並降溫的豆角、其他材料及醬汁拌勻並輕壓，至木瓜絲稍軟；拌好盡快食用。"}],"ingredient_changes":[],"old_recipe":{"method":"no_cook"},"new_recipe":{"method":"boiled"},"target_steps":[{"text":"青木瓜刨絲，蒜與辣椒切細；熟花生及蝦米粗切。","step_no":1},{"text":"棕櫚糖與魚露、青檸汁拌溶，再拌羅望子醬。","step_no":2},{"text":"豆角洗淨後用沸水徹底煮熟，再用可飲用冷水降溫、瀝乾切段；不可用未煮熟豆角拌沙律。車厘茄洗淨切半。","step_no":3},{"text":"大碗中把木瓜絲、已煮熟並降溫的豆角、其他材料及醬汁拌勻並輕壓，至木瓜絲稍軟；拌好盡快食用。","step_no":4}]},{"id":"ea6243a0-b663-452b-a854-bfd006996086","slug":"thai-pan-fried-fish","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"ec3339967ebefa0f575633b85956bf0bab62a6b20f669e77fefb582e2a7e23aa","cooking_tips":["魚先煎熟盛起，蒜蓉與魚露汁另以小火短煮，避免蒜蓉陪煎魚時間焦苦。","青檸汁留到食前才擠；煎魚的幾分鐘是參考，最厚中心也須熟透。"],"pairing_suggestions":["可配「蒜蓉西蘭花」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"d017d3a4-f0bc-4670-82dd-76becb24bc91","slug":"prepmeal-25-13-larb","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"83b0ec238fd6186f2d6320564f4d721829a87f2f39ab36a5e5d30ee9e3f504c8","cooking_tips":["生米先乾烘、放涼再磨粉，不能把未處理的生米粒直接拌入。","肉碎先煮至全熟才離火拌汁，香草稍降溫後加入，酸汁不是生肉的殺菌步驟。"],"pairing_suggestions":["這道菜已有白米，可配「蒜蓉生菜」；其他主食按整餐份量安排。"],"references":[],"served_cold":true},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"559f8476-da13-4e6f-a729-7743e808c37a","slug":"onion-scrambled-egg","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"4188439bcd3cd55e6dc23d6702eb240f09b43332252b49df2cd94788dcd7ae61","cooking_tips":["洋蔥先炒軟才下蛋，否則容易蛋已熟、洋蔥仍生硬。","蛋液用中小火輕推，煮至完全凝固後即盛起，不為等洋蔥變甜而把蛋久炒。"],"pairing_suggestions":["可配「蒜蓉西蘭花」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"952d14b9-33ff-44c9-84f0-7af3ada9350b","slug":"onion-chicken-steak-stir-fry","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"919cc8722e8d567013f058b2c6582aee8c72fb1103805af5759b0f8105df6f46","cooking_tips":["雞扒先煎香盛起，洋蔥炒軟後回鍋與30毫升水同煮，不能把前段金黃當成已熟。","醃料的生粉已拌在雞肉上，不另加一大份生粉水使洋蔥汁過厚。"],"pairing_suggestions":["可配「蒜蓉生菜」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"7709749a-94ba-44fb-aba1-ca5ca4425d2d","slug":"onion-pork-chop","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"aa925005afe35c663ced6f0ddb7284985383e4ff00a602ce297f816164245121","cooking_tips":["洋蔥在豬扒盛起後才炒軟，豬扒熟透便不必陪洋蔥一直煮。","接觸生豬肉的剩餘醃料必須徹底煮沸煮熟後才能做汁，不能直接淋在熟豬扒上。"],"pairing_suggestions":["可配「蒜蓉西蘭花」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"4b437b93-e3ec-4399-8f76-de6dac058eb7","slug":"kelp-tofu-soup-xhs","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"8e7f8a3cc582e33e6ba81d767ba9bdd0df776bcf69b7d80a6d680c5d6be61178","cooking_tips":["海帶依包裝完成泡發或去鹽，不能把乾品與濕海帶按相同重量直接替換。","豆腐後下並輕推，煮至中心熱透才調味，避免煮碎而令清湯混濁。"],"pairing_suggestions":["可配「蒸水蛋」與「蒜蓉西蘭花」，再按需要配主食；本頁的湯不是另外的飯量。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"9815a71b-e33e-441d-a524-78eb13990ead","slug":"cold-tossed-baby-napa-cabbage","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"3d20a3f91868088f044410a646f42f9b6159551bbfe0ffc1fdd671b680c90b64","cooking_tips":["娃娃菜汆熟後充分瀝水，醬汁才不會被菜水沖淡。","如過冷水，使用可飲用冷水及乾淨器具；拌好即食，不另加未列出的辣油。"],"pairing_suggestions":["可配「豆腐雞蛋白菜卷」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[],"served_cold":true},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"b3d03435-db93-4196-bbdb-b93b73c14587","slug":"cold-black-fungus-xhs","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"eda6dc52b9bdbe4407dd3fd0d57527dd503ae10013ebf35d2bc6d381849d4996","cooking_tips":["120克指已浸發濕木耳的瀝水重，不能用同重乾木耳代替。","木耳先按包裝煮熟，再用可飲用冷水處理並瀝乾；醬汁以材料表總量為準。"],"pairing_suggestions":["可配「孜然香辣烤豆腐」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[],"served_cold":true},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"a9e4a872-b2b5-43b5-a267-538e9a798b62","slug":"cold-seaweed-xhs","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"987f5813f4f1188393aacc2ea10e4f7ac3f57039b61d617981b934721ebb6c4d","cooking_tips":["先確認海帶是已泡發、可烹煮的濕品，按包裝去鹽煮熟，不把汆水留作調味汁。","拌好後即食或盡快冷藏，生抽與醋不因試味而超出材料表總量。"],"pairing_suggestions":["可配「豆腐雞蛋白菜卷」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}],"served_cold":true},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"52f80de1-87df-4e5d-9c12-184449419847","slug":"cold-tomato-xhs","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"dcc28d04f5ba5468701139c95219c6f2f1a4ac478d61edfb3d861b129ec92806","cooking_tips":["番茄切件後只輕拌，保留原來形狀，不用大力壓至出水。","糖鹽拌好後在雪櫃入味，檸檬汁或麻油只在選用時按材料表加入。"],"pairing_suggestions":["可配「孜然香辣烤豆腐」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[],"served_cold":true},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"4bc7a1af-dce3-4ef5-9990-24d55a295d9c","slug":"cold-okra-xhs","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"d31c5dd2a3d7e667d06988eeaf0a4cc97c8fe8dd8c4988ee805272bab999de6b","cooking_tips":["秋葵先整條汆熟再切段，減少切口黏液在煮水中流失。","冷水處理須用可飲用水，充分瀝乾才拌汁，調味不另加超出材料表的生抽。"],"pairing_suggestions":["可配「薑蔥豉油蒸豆腐（簡易版）」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[],"served_cold":true},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"8d7d22fe-8c9b-4511-a29b-19170cf6eb07","slug":"cold-cucumber-salad","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"99882c3397b98a8d4499f1e442b13ea70480a5b9822b29d4c33d69667b0a3a44","cooking_tips":["青瓜拍裂後切成一口大小，凹裂面較易拌到醬汁，不需先敲成碎蓉。","蒜、檸檬汁與生抽先拌勻再加青瓜；冷藏入味，避免在室溫長時間醃放。"],"pairing_suggestions":["可配「孜然香辣烤豆腐」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}],"served_cold":true},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"caa91d0e-b488-49b7-8f24-b453a9b2f5cd","slug":"cucumber-vermicelli-salad","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"517338bdab797f7286c9d8bb97d2e7d81acfc09ef01c5aa1548e15ff5f07438c","cooking_tips":["粉絲不只浸軟，要依包裝煮透再瀝乾，拌冷菜也不能省略煮熟。","青瓜與粉絲瀝水後才拌醬，調味按原定總量，避免試味時不斷補醬。"],"pairing_suggestions":["這道菜已有乾綠豆粉絲，可配「蒜蓉生菜」；其他主食按整餐份量安排。"],"references":[],"served_cold":true},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"99394e7f-ef03-4c1e-8030-278e9653094f","slug":"bitter-melon-beef","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"38aaaeb610866e26da2ecb8ac7175b7ff9f7857ec11896d89180ae459b667ed8","cooking_tips":["涼瓜先去籽切成薄片並汆水，才較容易在快炒時與牛肉一起完成。","前段七成熟的牛肉要回鑊炒至全熟；蠔油後加，不讓牛肉一直久炒變韌。"],"pairing_suggestions":["可配「蒜蓉生菜」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"2182c221-84d0-408d-af8d-370e977c03de","slug":"bitter-melon-omelette","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"bfe802b90fd59fe22bbe7d1e3b3d9e70bda56171565cbaf2e5eac7270fb94191","cooking_tips":["涼瓜切薄並先炒軟，蛋液下鑊前鋪平，避免中間夾生硬厚瓜片。","蛋餅翻面前先等底部定形，另一面煎好後也須確認中心蛋液完全凝固。"],"pairing_suggestions":["可配「清炒椰菜」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"a869d6e3-1079-4dd8-a519-eb601216421c","slug":"stir-fried-bok-choy","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"e0ad7bfbf41114a4065fb7d313a99a61a9a126baa88fbc37dd19cd8ffb70d6da","cooking_tips":["先炒小白菜的梗，再加葉，避免薄葉煮爛而厚梗仍硬。","選配清水按鑊內乾濕分次加，不需要用盡20毫升才算完成。"],"pairing_suggestions":["可配「豆腐雞蛋白菜卷」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"2aaec965-feb8-4b14-a62a-5633ab8ceb19","slug":"stir-fried-cabbage","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"fb9c1eb5780030087b4e9f1dcb9b57d9af71683f1da60ea3a94365ecc53e6dee","cooking_tips":["椰菜粗絲大小盡量一致，洗後瀝乾，入鑊後才不會一下變成一鍋水。","菜本身出水便不用再加全份選配水，炒至熟而仍爽口即可盛起。"],"pairing_suggestions":["可配「蒸水蛋」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"0402a93c-c480-44aa-a328-aa26cb798d7f","slug":"stir-fried-zucchini","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"95308428456c27b71dbe3a7dce97cf47cdd34281b6ba107cb21f2a9c64b82dda","cooking_tips":["節瓜片切得厚薄相若，先炒再用15毫升水加蓋短煮，幫助中心變軟。","開蓋後只需炒勻調味，不為收乾所有瓜汁而久炒至散爛。"],"pairing_suggestions":["可配「薑蔥豉油蒸豆腐（簡易版）」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"19ccf93b-df76-400a-b8a5-9fc4f9ccd25e","slug":"stir-fried-gai-lan-xhs","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"57242ebe963855003e5f48cefbaedabe9d627e22329d4e363c99c4c9aa18a331","cooking_tips":["粗芥蘭莖斜切薄片，梗與葉分段下鑊，較容易同時煮熟。","糖是選配，不為去苦而無限加糖；鹽與水仍按材料表總量。"],"pairing_suggestions":["可配「蒸水蛋」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"b5402590-4c59-41b6-9a2d-69ccabb3b991","slug":"stir-fried-choy-sum","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"01611afe7ff17ae07850ca87dd0364cb0adb742f992538c178d0726188dfd946","cooking_tips":["較粗菜心莖先斜切，再先炒莖後落葉，避免以菜葉顏色代替莖部熟度。","選配水分次加來幫助煮梗，不必一次倒足30毫升把菜炒成浸菜。"],"pairing_suggestions":["可配「薑蔥豉油蒸豆腐（簡易版）」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"66129a6f-9968-4737-b2ae-68c4b0dd3821","slug":"celery-lily-stir-fry","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"3da26e0bde7519604654d2c33839403ecfd062153f5884a350a44e8d66ca071b","cooking_tips":["西芹先短汆並瀝水，百合留在快炒階段加入，減少煮散。","百合每瓣洗淨瀝乾後才入鑊；若用乾百合，須先按包裝處理，不能同重直接代替鮮品。"],"pairing_suggestions":["可配「豆腐雞蛋白菜卷」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[{"old":null,"new":{"id":"4d32e561-50ac-4bb4-be6e-43c12a72e397","name":"水","quantity":15,"unit":"ml","note":"步驟已使用的煮食水；按材料表總量分配，不另計浸洗或倒走的汆水","optional":true}}],"old_recipe":{},"new_recipe":{},"target_steps":[{"text":"西芹切段，百合洗淨瀝乾。","step_no":1},{"text":"煲滾水，放入西芹汆燙 30 秒後瀝乾。","step_no":2},{"text":"鑊中加入食油1茶匙及切碎的蒜頭，中火炒香。","step_no":3},{"text":"加入西芹和百合，大火快速翻炒 1 至 2 分鐘。","step_no":4},{"text":"加入鹽約1/8茶匙調味，如太乾可加 1 湯匙水。","step_no":5},{"text":"炒至百合剛熟仍爽口即可。","step_no":6}]},{"id":"bb681471-3c7b-472d-936a-e834eac6bc1f","slug":"steamed-fish","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"67d401e4cd7e54c9978e46dab8ac61dfbb13c36aedea088fe25a1292ade4d1ba","cooking_tips":["魚柳厚薄不同要調整蒸時，最厚處中心須熟透，不能只見表面變白便取出。","食油如要淋面只用材料表總量，並非另加一份熱油；蔥只在實際選用時加入。"],"pairing_suggestions":["可配「蒜蓉生菜」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"6c26019b-399f-4808-87b7-95af53e00786","slug":"prepmeal-batch3-14","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"8c175714139466461d68f1d83bb8cf4c71eb340edafee42274ff8d7a1df6f254","cooking_tips":["通粉先煮熟瀝乾，再注調好味的熱湯，不把烚粉水全部倒進湯內。","煎蛋與煎蛋油是一組選配，不選煎蛋時兩者都省略，選用時蛋白蛋黃均煮熟。"],"pairing_suggestions":["本餐已包含主食，可配「蒜蓉生菜」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"d4145182-e574-41cb-84da-b5676cdfd334","slug":"prepmeal-batch3-10","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"f870fef22f49b5603a5f3b59d84be5ee6a172e564a94ced6438c1d8bfaf48ac0","cooking_tips":["蝦仁先煎變色只是預處理，回茄汁後仍須煮至中心熟透。","茄汁含糖，汁太快變稠時按步驟少量補水，不把蝦留在焦乾糖汁中久煮。"],"pairing_suggestions":["可配「蒜蓉西蘭花」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"0472b240-170b-4334-9d74-afb67a570ba2","slug":"beef-with-scrambled-egg","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"99d979f512395bd12ef3ce5fffc4a41c38deb1a5bdd0257d42b4d084ae033f74","cooking_tips":["牛肉先盛起是為分段烹調，最後回鑊要煮至全熟，不能停在原先七成熟。","蛋液以小火輕推，完成時全份蛋液凝固；本版不另加鹽，生抽留在牛肉調味中。"],"pairing_suggestions":["可配「蒜蓉西蘭花」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[{"step_no":1,"old":"牛肉片加入生抽約 1 茶匙、生粉少許和 1 茶匙水拌勻，醃 10 分鐘。","text":"牛肉片拌生抽約1茶匙、材料表的生粉及全份15毫升水中的5毫升，放雪櫃醃10分鐘。"},{"step_no":2,"old":"洋蔥切絲，雞蛋打散，蛋液加入少量清水拌勻，不另加鹽。","text":"洋蔥切絲，雞蛋打散，蛋液拌入餘下10毫升水，不另加鹽。"}],"ingredient_changes":[{"old":null,"new":{"id":"4d32e561-50ac-4bb4-be6e-43c12a72e397","name":"水","quantity":15,"unit":"ml","note":"步驟已使用的煮食水；按材料表總量分配，不另計浸洗或倒走的汆水","optional":false}}],"old_recipe":{},"new_recipe":{},"target_steps":[{"text":"牛肉片拌生抽約1茶匙、材料表的生粉及全份15毫升水中的5毫升，放雪櫃醃10分鐘。","step_no":1},{"text":"洋蔥切絲，雞蛋打散，蛋液拌入餘下10毫升水，不另加鹽。","step_no":2},{"text":"平底鑊加少量油，中火炒牛肉至七成熟，先盛起。","step_no":3},{"text":"原鑊炒香洋蔥 1 至 2 分鐘。","step_no":4},{"text":"轉小火倒入蛋液，輕輕推炒至半凝固。","step_no":5},{"text":"放回牛肉拌炒，直至牛肉熟透、蛋液凝固，即可上碟。","step_no":6}]},{"id":"d22592d0-7e14-4893-b1e3-0569636f01e1","slug":"shrimp-egg-tofu-pot","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"baef21d046e895b4b753f388a4dee459289468ed735901cdf9c033a8e19be209","cooking_tips":["45毫升水分成蛋液15毫升與鍋內30毫升，不在兩處各倒一次全份。","蝦轉色後仍要確認中心熟透，蛋液完全凝固、豆腐熱透才盛起。"],"pairing_suggestions":["可配「清炒芥蘭」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"14da0f5a-7fbc-4f76-b887-f1885dae3cd7","slug":"cheesy-meat-sauce-eggplant-bake","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"c83322f2d31f6f4a8d6550d9744e52f1768fb00d3dcfc5992b16bd26994a9f50","cooking_tips":["茄子先煎軟、肉醬先炒熟收濃，再分層焗，不靠表面芝士金黃判斷內層牛肉是否熟。","材料表的油、鹽分配在茄子與肉醬中使用，不因分開煎煮而重複加全份。"],"pairing_suggestions":["可配「清炒椰菜」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"8efd030b-5d41-453f-bdbd-5723803a4f36","slug":"baked-pork-chop-rice","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"c644fd8038aa2b2ab371be1650ba53fe80c9082116f2b7c5a4ddd5c6bc61d53f","cooking_tips":["豬扒先煎至熟透才鋪飯，最後焗的時間主要用來把整份熱透及融芝士。","番茄先炒出汁才拌熟飯，飯底拌勻後鋪平，避免焗皿中心仍有冷飯團。"],"pairing_suggestions":["本餐已包含主食，可配「蒜蓉西蘭花」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"0ebe6067-44f1-4d26-9c59-6fa9375269d9","slug":"baked-layered-eggplant-with-vegetables","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"b736405609e0c2d0b4550a87d5f42c4bdaeb8f81a8cb232c8f67f0b319bdcd7e","cooking_tips":["茄子與櫛瓜厚薄盡量一致，鋪層不要過厚，中心也要焗至蔬菜熟軟。","芝士上色早不代表茄子已熟，可檢查較厚茄片是否容易刺入，再決定是否續焗。"],"pairing_suggestions":["本餐已包含主食，可配「清炒菜心」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"fcea6858-8d5f-4de2-a761-9cd10020bf06","slug":"baked-chicken-rice","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"fdfb34f8ce12a25dcb02e5e5ce4afe36354187abcb9c5ee2a602b7de08c075d3","cooking_tips":["雞扒先煎熟，不能把焗芝士的十分鐘當成所有厚雞扒的熟透保證。","飯底用熟飯拌番茄洋蔥汁，整份焗至中心熱透，芝士剛溶便檢查而非只看顏色。"],"pairing_suggestions":["本餐已包含主食，可配「蒜蓉生菜」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"98324881-2f67-4fea-8c6b-95631c644f86","slug":"pan-fried-salmon","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"512f8e906d8e55411dffc8dc289a3fe54833312dc1887396f799443e5f1b1a3a","cooking_tips":["魚皮印乾再先朝下煎，未定形前少移動，較容易保持魚皮完整。","兩面上色後仍檢查最厚中心熟度；檸檬汁屬選配，按材料表份量淋上。"],"pairing_suggestions":["可配「蒜蓉生菜」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"2eeddb92-86ee-4ab3-9d85-89eb57989e01","slug":"prepmeal-batch3-05","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"d4e1ebd04906ca337ffc68425a2788defc2d944aab4a61d52838e579a5ddd280","cooking_tips":["麵粉先用預留冷水調開，加入前再攪勻，避免把乾粉直接灑入熱湯結團。","薯仔先煮軟，牛奶後加以微滾煮熟麵粉，不用猛烈大滾來催濃。"],"pairing_suggestions":["這道菜已有薯仔，可配「清炒菜心」；其他主食按整餐份量安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"42cacc97-ca27-4bbf-8f30-9b284160e223","slug":"teriyaki-salmon","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"2a5db60190f2094cf7a33f4c2857cdf237e5113c8dc4402e954ddc978afaf9e4","cooking_tips":["照燒汁含糖，魚柳兩面略煎後轉中小火煮汁，避免外面先變焦而中心未熟。","白飯不在這道魚柳材料內，另配須另計；魚肉最厚處也要煮至熟透。"],"pairing_suggestions":["可配「清炒椰菜」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"193c3b41-c1c3-4a26-a069-3285cfbe11a9","slug":"teriyaki-tofu-don","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"51b9ac3431feb320162a8d6de8aa021ab6ee43d62bff8f25c1a7f9625eb2f5f7","cooking_tips":["豆腐吸乾表面水分再煎，底面定形才翻，避免每次翻動都黏碎。","輕推裹上照燒汁便可，白飯已是丼飯的一部分，不在盛碗後再另加飯量。"],"pairing_suggestions":["本餐已包含主食，可配「清炒菜心」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"fb489d22-6358-40d3-ab88-8bb362258d46","slug":"teriyaki-chicken-thigh","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"f4c4bceb242e34fe0fdf6e2922f360c9bfad401261c1f8d3ae15ef19fe7ef3fe","cooking_tips":["雞皮未定形便拉扯，容易黏鑊破皮；待表面定形再輕輕翻面。","照燒汁含糖，適合在雞扒已熟後短時間收汁；不要靠長時間煎醬汁來把厚雞扒煮熟。"],"pairing_suggestions":["可配蒜蓉西蘭花及白飯；白飯另計，不包含在雞扒的一人份材料內。"],"references":[{"title":"Kikkoman：Teriyaki Chicken","url":"https://www.kikkoman.com/en/cookbook/recipe/00000185.html"},{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"},{"title":"食物安全中心：清潔、消毒與衞生","url":"https://www.cfs.gov.hk/tc_chi/consumer_zone/safefood_all/clean_hygiene.html"}]},"changed_steps":[{"step_no":1,"old":"雞扒用廚紙抹乾，如太厚可在厚位輕切幾刀方便熟透。","text":"去骨連皮雞腿肉160克用廚紙印乾；厚位從肉面輕劃開，攤成較平均厚度，拌上材料表的黑胡椒1/4茶匙。"},{"step_no":2,"old":"平底鑊加少量食油，中火放入雞扒，皮面或較平一面先向下。","text":"平底鑊加入1茶匙食油，中火放入雞扒，皮面向下；先不要不停移動。"},{"step_no":3,"old":"每面煎 4 至 5 分鐘，煎至兩面金黃。","text":"皮面定形後翻面，兩面各煎約4至5分鐘；若過快變深色便調低火力。"},{"step_no":4,"old":"加入照燒汁2湯匙和水15毫升，轉中小火。","text":"加入材料表的15毫升水，轉小火加蓋，繼續煮至最厚肉部的中心達75°C並維持至少30秒；時間須按厚度調整，留意鍋內水分。"},{"step_no":5,"old":"一邊煮一邊將醬汁淋上雞扒，煮至醬汁變稠並包裹表面。","text":"雞肉熟透後加入2湯匙照燒汁，中小火把醬汁淋上雞扒；煮至薄薄掛面便關火，避免收得太乾。"},{"step_no":6,"old":"確認雞扒中心熟透後取出，靜置 2 分鐘再切件。","text":"用乾淨夾及砧板取出雞扒，靜置約2分鐘後切件；盛熟雞的器具不要沿用接觸過生雞而未清洗的器具。"}],"ingredient_changes":[{"old":{"id":"4d32e561-50ac-4bb4-be6e-43c12a72e397","name":"水","note":null,"unit":"ml","optional":false,"quantity":15},"new":{"id":"4d32e561-50ac-4bb4-be6e-43c12a72e397","name":"水","note":"起始煮食用水；鍋具蒸發較多時按需要少量補水，不增加油或醬料","unit":"ml","optional":false,"quantity":15}}],"old_recipe":{"description":"雞扒煎香後裹上照燒汁，鹹甜惹味。"},"new_recipe":{"description":"連皮去骨雞腿肉先煎出香味，再用照燒汁收成薄薄一層。雞扒厚位處理得平均，較容易避免表面焦、中心未熟。"},"target_steps":[{"text":"去骨連皮雞腿肉160克用廚紙印乾；厚位從肉面輕劃開，攤成較平均厚度，拌上材料表的黑胡椒1/4茶匙。","step_no":1},{"text":"平底鑊加入1茶匙食油，中火放入雞扒，皮面向下；先不要不停移動。","step_no":2},{"text":"皮面定形後翻面，兩面各煎約4至5分鐘；若過快變深色便調低火力。","step_no":3},{"text":"加入材料表的15毫升水，轉小火加蓋，繼續煮至最厚肉部的中心達75°C並維持至少30秒；時間須按厚度調整，留意鍋內水分。","step_no":4},{"text":"雞肉熟透後加入2湯匙照燒汁，中小火把醬汁淋上雞扒；煮至薄薄掛面便關火，避免收得太乾。","step_no":5},{"text":"用乾淨夾及砧板取出雞扒，靜置約2分鐘後切件；盛熟雞的器具不要沿用接觸過生雞而未清洗的器具。","step_no":6}]},{"id":"083e9e5b-824b-4f63-acd9-7ac2fcdba8e2","slug":"teriyaki-chicken-cubes-xhs","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"d19747a96da197a5caf5c5dfc56c21150965124bd9d80aa8fdfb79d4b9784678","cooking_tips":["雞粒切成大小相若約2厘米，才較容易同時熟，不留一粒特別大的中心未熟。","表面金黃後用中小火煮汁，確認雞粒中心熟透才起鑊，不只看汁已收稠。"],"pairing_suggestions":["可配「蒜蓉西蘭花」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"709f465d-f8db-439f-a76b-1991283aa424","slug":"steamed-egg","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"0d687f8aaff3f8cf69e1835b71552cfc34609ef6aba9c5b56922e5c2ba87b6d1","cooking_tips":["蛋面出現小孔，常與火太猛或蒸得太久有關；先控制蒸氣，不要只靠縮短時間。","深碗或較厚的碗可能需要更久；表面凝固不代表中心已熟，應以中心熟度為準。"],"pairing_suggestions":["可配豉汁蒸排骨及一份蔬菜；想簡單一點，也可配白飯及蔬菜。"],"references":[{"title":"Made With Lau：Steamed Eggs","url":"https://www.madewithlau.com/recipes/steamed-egg"},{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}]},"changed_steps":[{"step_no":1,"old":"雞蛋打入碗中，輕輕打散，避免打入太多空氣。","text":"雞蛋打入碗中，輕輕攪勻蛋黃與蛋白，不要打成大量泡沫。"},{"step_no":2,"old":"加入清水120毫升及材料表所列的鹽，攪拌均勻。","text":"加入水120毫升及鹽1/8茶匙，攪拌均勻；本版不另改蛋水比例。"},{"step_no":3,"old":"將蛋液過篩一次，倒入蒸碗中，表面泡泡可撇走。","text":"蛋液過篩，倒入淺身耐熱碗，撇去表面泡沫。"},{"step_no":4,"old":"用耐熱碟蓋好蒸碗，避免倒汗水滴入蛋面。","text":"用耐熱碟蓋住蒸碗，讓蒸鍋蓋的倒汗水不會直接滴在蛋面。"},{"step_no":5,"old":"水滾後放入淺蒸碗，中小火蒸約10至12分鐘；時間視碗深而定，中心須完全凝固並達75°C、維持30秒。","text":"蒸鍋的水煮滾後放入蒸碗，轉中小火蒸約10至12分鐘；保持有蒸氣，避免水猛烈翻滾。"},{"step_no":6,"old":"取出後，可按材料表選配生抽半茶匙及麻油1/8茶匙。","text":"檢查中心已凝固；用食物溫度計確認中心達75°C並維持至少30秒，未達標便繼續蒸。小心取出，可按材料表加入選配生抽半茶匙及麻油1/8茶匙。"}],"ingredient_changes":[],"old_recipe":{"description":"雞蛋蒸至柔滑細嫩，蛋香溫和，是簡單的家常菜。"},"new_recipe":{"description":"一隻雞蛋配120毫升水，蒸成較柔軟的水蛋。用淺碗、溫和蒸氣及蓋碟，較容易保留平滑蛋面。"},"target_steps":[{"text":"雞蛋打入碗中，輕輕攪勻蛋黃與蛋白，不要打成大量泡沫。","step_no":1},{"text":"加入水120毫升及鹽1/8茶匙，攪拌均勻；本版不另改蛋水比例。","step_no":2},{"text":"蛋液過篩，倒入淺身耐熱碗，撇去表面泡沫。","step_no":3},{"text":"用耐熱碟蓋住蒸碗，讓蒸鍋蓋的倒汗水不會直接滴在蛋面。","step_no":4},{"text":"蒸鍋的水煮滾後放入蒸碗，轉中小火蒸約10至12分鐘；保持有蒸氣，避免水猛烈翻滾。","step_no":5},{"text":"檢查中心已凝固；用食物溫度計確認中心達75°C並維持至少30秒，未達標便繼續蒸。小心取出，可按材料表加入選配生抽半茶匙及麻油1/8茶匙。","step_no":6}]},{"id":"1f18bcb4-3f67-4db7-b7be-2e56501952e4","slug":"steamed-pork-patty","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"e6ca93cb5a1e7a7c534e9a83f9e6fb33d229eadc49b47d6a2188597f7b63413c","cooking_tips":["肉餡沿同一方向拌至有黏性，再攤成約1.5厘米厚，不蒸成厚肉團。","蒸好須檢查肉餅中心，達75°C並維持至少30秒；表面變色或焗一分鐘並非熟度保證。"],"pairing_suggestions":["可配「清炒椰菜」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"4781fcff-e2a6-47ec-9ebc-9287c5b7cf0c","slug":"butter-shrimp","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"99ba2e00dd70d8249cdbe8a5dcc755b0a42812e5b7a611af874ad3b5eab94fe9","cooking_tips":["蝦表面抹乾再落牛油鑊，蒜蓉只炒到出香，避免先煎黑而發苦。","蝦轉紅或捲曲後仍須煮至中心熟透，不把表面轉色當成唯一完成條件。"],"pairing_suggestions":["可配「清炒菜心」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"c6e2c02e-3cdf-41b9-ab07-6c410c88f22d","slug":"prepmeal-batch3-09","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"99080c6f0fede24984034d2f9c8e749b96cf7af52f616af73061f8ead290b061","cooking_tips":["荷蘭豆先去筋、蘑菇切片，讓豆與菇在定量高湯內一起受熱。","蒜蓉後下短炒，避免整段收汁時間中先變焦；湯近乾但豆未熟時按步驟少量補水。"],"pairing_suggestions":["可配「豆腐雞蛋白菜卷」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"83980cab-2499-4388-aaf5-61caf00738b1","slug":"butter-mushroom-pasta","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"14d65a2c28cd4e5cf57f6e6eb4872269420a9b7feaf1ec22fa503bc03d2530c5","cooking_tips":["蘑菇先炒至出水後稍收乾，牛油汁才不會被生菇的水分沖淡。","兩湯匙麵水先留起，拌粉時逐少加至能掛汁，不需要一次用盡。"],"pairing_suggestions":["本餐已包含主食，可配「清炒芥蘭」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"68abae98-7609-4337-ab3b-4e4a6597bd76","slug":"beef-onion-stir-fry","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"93c970f4ee16b9b338965f0b133ff8a7cb05aa5159402e5ee69fa743e1a0783c","cooking_tips":["洋蔥先炒至半透明再炒牛肉，可縮短牛肉留鑊的時間。","按材料表使用生抽、蠔油與黑胡椒；本版不額外加入未列出的蒜蓉或生粉。"],"pairing_suggestions":["可配「蒜蓉生菜」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[{"step_no":1,"old":"牛肉切片，加入生抽約 1 茶匙、生粉少許和黑椒少許拌勻，醃 10 分鐘。","text":"牛肉切薄片，拌入生抽1茶匙及材料表的一部分黑胡椒，冷藏醃10分鐘；本版不加入生粉。"},{"step_no":2,"old":"洋蔥切絲，蒜頭切碎備用。","text":"洋蔥切絲，材料表的食油及餘下生抽、蠔油備用；本版不加入蒜頭。"},{"step_no":3,"old":"鑊中加入少量油，中火炒洋蔥 2 分鐘至半透明。","text":"鑊中加入材料表的食油，中火炒洋蔥約2分鐘至半透明。"},{"step_no":5,"old":"加入生抽約 1 茶匙、蠔油約 1 茶匙和少量水拌勻。","text":"加入餘下生抽1茶匙、蠔油1茶匙及餘下黑胡椒拌勻；火太猛先調低，不另加未列出的醃料。"},{"step_no":6,"old":"炒至牛肉剛熟、醬汁包裹洋蔥後立即上碟，避免牛肉變韌。","text":"繼續翻炒至牛肉完全熟透，中心達75°C並維持至少30秒後盛起；時間按肉片厚度調整。"}],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":[{"text":"牛肉切薄片，拌入生抽1茶匙及材料表的一部分黑胡椒，冷藏醃10分鐘；本版不加入生粉。","step_no":1},{"text":"洋蔥切絲，材料表的食油及餘下生抽、蠔油備用；本版不加入蒜頭。","step_no":2},{"text":"鑊中加入材料表的食油，中火炒洋蔥約2分鐘至半透明。","step_no":3},{"text":"轉大火，加入牛肉快速翻炒至約八成熟。","step_no":4},{"text":"加入餘下生抽1茶匙、蠔油1茶匙及餘下黑胡椒拌勻；火太猛先調低，不另加未列出的醃料。","step_no":5},{"text":"繼續翻炒至牛肉完全熟透，中心達75°C並維持至少30秒後盛起；時間按肉片厚度調整。","step_no":6}]},{"id":"d8bd8db7-974b-47d0-99cd-d1330138a286","slug":"prepmeal-batch2-20","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"f0f40f4e6d4f0fc5ed9dd3f056458e01f299ce9dbf95b4e417ea17a39563262f","cooking_tips":["冰水用乾淨器具及可飲用水製作，浸後瀝乾再入瑞士汁，不把浸水倒入滷汁。","原汁與水是50比25毫升，雞翼仍須煮熟；鍋內醬汁不是另外一碗可全喝的湯。"],"pairing_suggestions":["可配「蒜蓉西蘭花」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"251e1d9d-0ab1-4ce9-beaa-aaaf2a024e4a","slug":"sweet-and-sour-spare-ribs","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"c0213e0102e5aec34960bec95ac4163d8055514763efe7c380e487617ccd6d9f","cooking_tips":["排骨煎至金黃後仍須加蓋煮熟，近骨最厚肉部要達75°C至少30秒。","茄汁與糖留到肉熟後裹汁，汁一旦黏身便留意火力，不靠煎焦糖汁來催熟排骨。"],"pairing_suggestions":["可配「清炒椰菜」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}]},"changed_steps":[{"step_no":1,"old":"排骨沖洗後瀝乾，沾上生粉。","text":"排骨檢查並去除可見骨碎，用廚紙抹乾，再薄沾材料表的生粉；不以流水沖洗生肉。"}],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":[{"text":"排骨檢查並去除可見骨碎，用廚紙抹乾，再薄沾材料表的生粉；不以流水沖洗生肉。","step_no":1},{"text":"平底鑊加入食油，中火煎排骨至表面金黃。","step_no":2},{"text":"轉小火，加蓋煮 6 至 8 分鐘至排骨熟透。","step_no":3},{"text":"加入茄汁、白醋、糖和生抽拌勻。","step_no":4},{"text":"中火煮至醬汁變稠並包住排骨。","step_no":5},{"text":"排骨外層酸甜亮身即可上碟。","step_no":6}]},{"id":"4355baeb-12b9-483b-9d61-696fcdb505ab","slug":"tomato-egg-tofu-pot","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"778778857b6400cc0ad06f8cb758d2d16e78ef48a29991611053d03ca4976c17","cooking_tips":["番茄先煮出汁才放豆腐，豆腐下鍋後用推拌代替大力翻炒。","蛋液以小火加熱至完全凝固再盛起，不能以滑蛋為理由保留流動生蛋液。"],"pairing_suggestions":["可配「清炒椰菜」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}]},"changed_steps":[],"ingredient_changes":[{"old":null,"new":{"id":"4d32e561-50ac-4bb4-be6e-43c12a72e397","name":"水","quantity":30,"unit":"ml","note":"步驟已使用的煮食水；按材料表總量分配，不另計浸洗或倒走的汆水","optional":false}}],"old_recipe":{},"new_recipe":{},"target_steps":[{"text":"番茄切件，豆腐切件，雞蛋打散。","step_no":1},{"text":"鍋中加入少量油，中火炒番茄 2 分鐘至出汁。","step_no":2},{"text":"加入豆腐和 2 湯匙水，輕輕推勻。","step_no":3},{"text":"加入鹽1/8茶匙調味，輕輕拌勻。","step_no":4},{"text":"轉小火倒入蛋液，輕輕推成滑蛋狀。","step_no":5},{"text":"蛋液剛熟即關火，上碟即可。","step_no":6}]},{"id":"aa293f16-97ad-4ecd-bf2d-d4a1f99e75e8","slug":"prepmeal-batch3-20","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"a1226f3425abccfe5a9735bd75a320839a0343507b1cb3b38ff79d37114025a2","cooking_tips":["普通椰菜花先切小朵並汆至開始軟，不直接套用長梗菜花只汆一分鐘的做法。","番茄先炒出汁再放回椰菜花；較厚梗也須熟，不只看表面已沾茄汁。"],"pairing_suggestions":["可配「豆腐雞蛋白菜卷」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"7f2d0f48-bc94-4ac6-bb62-f4d09908bd33","slug":"tomato-pork-mushroom-egg-soup-rice","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"ee63aa8419ed587e87b3969b9d94d188ce0747696dc4d650fd2f62936c50d479","cooking_tips":["熟飯先拌散並全鍋重新煮滾，冷藏飯須妥善保存後徹底翻熱。","蛋液倒入後先讓它凝固再輕推，可保留較大片蛋花；不另加魚露、榨菜或油。"],"pairing_suggestions":["本餐已包含主食，可配「清炒菜心」；飯麵不必重複加一份。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"32d07a6d-ef89-4b13-9f27-ea073b836f77","slug":"tomato-beef-bolognese-pasta","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"338bff9638d507c892f15c55e591b79d129ff9f31b90f28ef64e1f1974127699","cooking_tips":["免治牛肉炒散後仍要在肉醬中煮熟，轉色不是完成終點。","麵水只在拌醬太乾時逐少加入，糖是選配，不因番茄醬酸便隨意增加總量。"],"pairing_suggestions":["本餐已包含主食，可配「清炒菜心」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"20af1f29-2caf-406e-9869-6647ea75eb40","slug":"prepmeal-batch3-24","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"8d722fe8e8f8b5d9f4c370ff0480a639e51bc6d8937a586b8e2ee1871cee7029","cooking_tips":["薯仔與紅蘿蔔按步驟切約1厘米粒，才較容易在同一段煮湯時間內軟熟。","肉碎逐少加入並撥散；水蒸發過多時用熱水補回，不額外加湯粒改調味。"],"pairing_suggestions":["這道菜已有薯仔，可配「蒜蓉生菜」；其他主食按整餐份量安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"0d2911ac-2887-4ec8-a682-c8fa5d2a33f6","slug":"tomato-potato-minced-pork","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"7b2d06c2db7dda7fa945024db713b39b449ba0a8bedd3a86497901ff9181e323","cooking_tips":["薯仔粒切成大小相若，中心可輕易刺穿才算軟熟，不能只見番茄汁濃便停火。","肉碎先炒散，之後仍須跟薯仔同煮至全熟，避免留下外熟內生的大肉團。"],"pairing_suggestions":["這道菜已有薯仔，可配「清炒菜心」；其他主食按整餐份量安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"cac951ef-c704-4527-9477-56d5a09512ec","slug":"tomato-potato-fish-soup","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"e5acc01684a59f7b26d7ba90fa27e090b5cd45522fa0eebb67dc1d8be56f1c92","cooking_tips":["先煮軟薯仔再下魚柳，避免魚肉為等薯仔變腍而散爛。","魚柳後下時輕推散開，煮至最厚中心熟透；薄片的時間不適用較厚魚件。"],"pairing_suggestions":["這道菜已有薯仔，可配「蒜蓉西蘭花」；其他主食按整餐份量安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"03e3a194-18bc-41f3-bd5a-828e14114f09","slug":"tomato-egg-soup-xhs","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"2dbe1656c34f730854006dcee09a84346cb5c1b12572fb2eaa0ece5af5a2e079","cooking_tips":["想見到較完整的蛋花，倒蛋時保持細流，避免大力不停打圈，把剛凝固的蛋打碎。","番茄酸度不同，先試已煮好的湯再決定是否用選配糖，不把糖當成必加。"],"pairing_suggestions":["可配清淡的肉菜及白飯；湯內已有雞蛋，可避免同餐再選蒸水蛋。"],"references":[{"title":"Made With Lau：Egg Drop Soup","url":"https://www.madewithlau.com/recipes/egg-drop-soup"},{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}]},"changed_steps":[{"step_no":1,"old":"番茄切件，雞蛋打散備用。","text":"番茄150克洗淨切小件；雞蛋打散，準備好全份300毫升水。"},{"step_no":2,"old":"鍋中加入少量油，中火炒番茄 1 至 2 分鐘至出汁。","text":"鍋中加入1茶匙食油，中火炒番茄約1至2分鐘，至邊緣軟化並開始出汁。"},{"step_no":3,"old":"加入清水約 300 毫升，煮滾後轉中火。","text":"加入300毫升水，煮滾後轉中火。"},{"step_no":4,"old":"煮 3 至 5 分鐘至番茄變軟出味。","text":"煮約3至5分鐘至番茄軟化，加入鹽1/8茶匙；試味後如需要，可用材料表的選配糖1/4茶匙平衡酸味。"},{"step_no":5,"old":"加入鹽約1/8茶匙調味，慢慢倒入蛋液形成蛋花。","text":"保持湯微滾，把蛋液沿鍋邊慢慢倒成細流，同時用湯勺輕輕攪動，不要一口氣倒成一團。"},{"step_no":6,"old":"蛋花凝固後關火即可。","text":"繼續加熱至蛋液完全凝固、湯滾燙，再關火盛起；本版不加入未列出的生粉或雞粉。"}],"ingredient_changes":[],"old_recipe":{"description":"番茄蛋花湯酸甜清爽，做法簡單，適合作為日常配湯。"},"new_recipe":{"description":"先炒軟番茄再加水，湯味較容易煮出來；蛋液慢慢加入，可形成蛋花而不是整塊蛋。這是一碗不加生粉的清湯。"},"target_steps":[{"text":"番茄150克洗淨切小件；雞蛋打散，準備好全份300毫升水。","step_no":1},{"text":"鍋中加入1茶匙食油，中火炒番茄約1至2分鐘，至邊緣軟化並開始出汁。","step_no":2},{"text":"加入300毫升水，煮滾後轉中火。","step_no":3},{"text":"煮約3至5分鐘至番茄軟化，加入鹽1/8茶匙；試味後如需要，可用材料表的選配糖1/4茶匙平衡酸味。","step_no":4},{"text":"保持湯微滾，把蛋液沿鍋邊慢慢倒成細流，同時用湯勺輕輕攪動，不要一口氣倒成一團。","step_no":5},{"text":"繼續加熱至蛋液完全凝固、湯滾燙，再關火盛起；本版不加入未列出的生粉或雞粉。","step_no":6}]},{"id":"706424ea-b414-44ae-972f-c93d6c39ff4f","slug":"tomato-tofu","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"1736e103cc722893dfaa0747ce6683054f81468d909537c50ca9d8dbe8fde8a4","cooking_tips":["嫩豆腐切件後輕推拌汁，不反覆用鑊鏟翻炒，較容易保留形狀。","番茄先出汁、豆腐後下，汁太乾才按步驟少量補水，不另加生粉濃芡。"],"pairing_suggestions":["可配「蒜蓉西蘭花」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[{"step_no":4,"old":"加入豆腐、生抽1茶匙及糖1茶匙，輕手推勻；如太乾，可逐少加入清水。","text":"加入豆腐、生抽1茶匙及糖1茶匙，輕手推勻；如太乾，可逐少加入材料表最多30毫升選配清水。"}],"ingredient_changes":[{"old":null,"new":{"id":"4d32e561-50ac-4bb4-be6e-43c12a72e397","name":"水","quantity":30,"unit":"ml","note":"步驟已使用的煮食水；按材料表總量分配，不另計浸洗或倒走的汆水","optional":true}}],"old_recipe":{},"new_recipe":{},"target_steps":[{"text":"番茄切件，豆腐切成約 2 厘米方塊，蒜頭切蓉。","step_no":1},{"text":"鑊中加入少量油，中火炒香蒜蓉。","step_no":2},{"text":"加入番茄炒 2 至 3 分鐘，炒至開始出汁。","step_no":3},{"text":"加入豆腐、生抽1茶匙及糖1茶匙，輕手推勻；如太乾，可逐少加入材料表最多30毫升選配清水。","step_no":4},{"text":"轉小火煮 4 至 5 分鐘，期間輕輕推動避免豆腐碎。","step_no":5},{"text":"試味，煮至汁微稠、豆腐熟透即可上碟。","step_no":6}]},{"id":"a0a9d821-8e2b-445f-9c0d-6e4dc7f3090b","slug":"tomato-tofu-rice","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"a61317b18556a8f136d17322f65e07d8e5e646389741ef46aed1779928fb0892","cooking_tips":["嫩豆腐下鑊後只輕推，番茄與洋蔥先炒香，醬汁較容易均勻。","白飯180克已包括在一人份中，豆腐煮至熱透後連汁淋飯，不需再配一碗飯。"],"pairing_suggestions":["本餐已包含主食，可配「蒜蓉西蘭花」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"116a305a-d4ad-48a8-8862-a5a467d0b914","slug":"tomato-fish-fillet-soup-xhs","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"064afc62d40f533c8999055b1e9ff97b00092674c02382cf206f8305ea9bd068","cooking_tips":["全份350毫升水分前段少量炒番茄與後段煮湯使用，不在兩段各加一份。","魚片最後下並輕推散，仍以最厚中心熟透為準，不把一兩分鐘當成所有厚度的保證。"],"pairing_suggestions":["可配「豉汁蒸排骨」與「蒜蓉生菜」，再按需要配主食；本頁的湯不是另外的飯量。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"7d86b770-f8ab-4bde-b3fe-88624931fe84","slug":"white-sauce-seafood-rice","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"cb4f1d0fcd37d5a7e6b9d5fce732a4c53186ed7c6ef53a7c4aa672ca2a11980b","cooking_tips":["麵粉炒到看不到乾粉後才分次加奶，每次拌勻再加下一次，避免白汁起粉團。","海鮮先轉色仍要在白汁內煮熟，整份熱透後才淋上已熟白飯。"],"pairing_suggestions":["本餐已包含主食，可配「清炒椰菜」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"bcb38612-d449-4822-ad8c-0e63a9e8f988","slug":"creamy-mushroom-chicken-pasta","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"915ca21d026a90dff266189c75b3be8855a1dfc70a250704b1fca3322ae11819","cooking_tips":["雞胸先煎熟盛起，蘑菇炒至稍收水後才加忌廉與牛奶，避免白汁被菇水沖淡。","巴馬臣芝士只在選用時加入；麵水逐少調稠度，不為煮乾所有水而久煮雞肉。"],"pairing_suggestions":["本餐已包含主食，可配「蒜蓉西蘭花」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"f596ddf5-3f08-4f87-bda6-c7904a605202","slug":"cream-chicken-pasta","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"eb8ae3f860d1552c4529810abf82edf172089525a8b790c3af9bcc2a5e60853d","cooking_tips":["前段八成熟雞肉回白汁後仍須煮至全熟，不在醬汁剛掛粉時便忽略雞肉中心。","牛油分兩段用，煮粉水與最後調味的鹽都受材料表總量限制，不重複加鹽。"],"pairing_suggestions":["本餐已包含主食，可配「蒜蓉西蘭花」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"0084b56c-e61d-46fb-9e5d-5482b3ca56e6","slug":"poached-shrimp","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"c913be636961dbe3407de9f308cb57270389af6c950a5f05d8d1441bf81de175","cooking_tips":["蝦放入滾水後仍要煮至中心熟透，轉紅或捲曲不單獨作為安全終點。","若選冰水降溫，使用可飲用水及乾淨器具；另配豉油蘸汁不屬基本材料與營養。"],"pairing_suggestions":["可配「清炒菜心」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"98bb1cd9-f558-4c8c-8d53-db68fb90be59","slug":"prepmeal-batch4-07","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"daf67b40a3b0d3a5c255418d294e24439a8f6e7158046171d3c3cce8d3129444","cooking_tips":["75毫升炆煮水與15毫升芡水先分好，避免最後才發現已用盡總水量。","現成魚片頭按包裝煮熟熱透，粉絲按包裝煮透，不把兩者都當成即食材料。"],"pairing_suggestions":["這道菜已有乾綠豆粉絲，可配「蒜蓉西蘭花」；其他主食按整餐份量安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"173c40bd-9160-4f28-a0bd-fce17bdb1058","slug":"white-radish-beef-soup-xhs","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"4755b99921db6ee65d8f2224fc05088b78cb729a79a64757d996a13d975eb6e7","cooking_tips":["蘿蔔先煮軟才加入薄牛肉，減少牛肉為等蘿蔔熟而久煮變韌。","肉片逐片撥散煮熟，不以一兩分鐘保證厚肉或黏成團的肉也已熟。"],"pairing_suggestions":["可配「照燒雞扒」與「清炒芥蘭」，再按需要配主食；本頁的湯不是另外的飯量。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"a8c1c77b-b47e-4908-9908-c9ecb04ce1f0","slug":"fuzzy-melon-pork-soup","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"cee80cc81f6f6c6613f40ad3789a2b4d1e7046f95200adc3311573d7aec2c02f","cooking_tips":["節瓜去皮切成相若厚度，湯味煮出後再按材料表的鹽量試味。","豬肉若先汆水，該段並不代表已熟；仍須在湯中煮至肉片完全熟透。"],"pairing_suggestions":["可配「豉汁蒸排骨」與「清炒椰菜」，再按需要配主食；本頁的湯不是另外的飯量。"],"references":[]},"changed_steps":[{"step_no":1,"old":"節瓜去皮切件，豬肉片沖洗後瀝乾，薑切片。","text":"節瓜去皮切件，豬肉切成相若薄片，薑切片；處理生肉與已洗蔬菜的器具分開，避免流水沖洗生肉造成水花污染。"}],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":[{"text":"節瓜去皮切件，豬肉切成相若薄片，薑切片；處理生肉與已洗蔬菜的器具分開，避免流水沖洗生肉造成水花污染。","step_no":1},{"text":"如想湯更清，可將豬肉片快速汆水 30 秒後撈起。","step_no":2},{"text":"湯鍋加入清水850毫升，放入節瓜、豬肉片和薑片。","step_no":3},{"text":"大火煮滾後轉中小火煮約 30 分鐘。","step_no":4},{"text":"煮至節瓜軟身、湯味變甜。","step_no":5},{"text":"最後按材料表所列的鹽分次調味，試味後上碗。","step_no":6}]},{"id":"7986fa4d-f3eb-4450-9e35-1f9a8ede379f","slug":"fuzzy-melon-salted-egg-soup-xhs","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"386a29b5675732f79c9c06ff28472529b4a1615cb0b8d13d099b1ae020b71ea3","cooking_tips":["先確認鹹蛋是生鹹蛋還是熟鹹蛋，按包裝處理，生品須把蛋黃蛋白都煮熟。","鹹蛋本身有鹹味，煮好試味才決定是否用材料表的鹽，不一開始便加足。"],"pairing_suggestions":["可配「肉碎豆腐」與「清炒椰菜」，再按需要配主食；本頁的湯不是另外的飯量。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"00049f07-c924-4c47-9a48-ff373b6c445b","slug":"corn-fish-fillet-sauce","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"de074db1909875a7e77c8bb4a72c924e7d9b1a17f025f48baba0201fd6f73aaa","cooking_tips":["魚柳煎好後先確認中心熟透，粟米蛋花汁只作淋面，不能代替把厚魚塊煮熟。","蛋液細流加入粟米汁並煮熟，生粉水先調勻，避免最後把乾粉直接灑進熱汁。"],"pairing_suggestions":["可配「清炒菜心」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[{"step_no":1,"old":"魚柳抹乾，加入鹽和白胡椒拌勻。","text":"先從全份120毫升水中取15毫升冷水，拌勻1茶匙生粉留用；魚柳抹乾，拌入材料表的鹽和白胡椒。"},{"step_no":2,"old":"平底鑊加入食油，中火將魚柳煎至兩面金黃，先盛起。","text":"平底鑊加入全份食油，中火把魚柳煎至熟透，確認最厚中心達75°C並維持至少30秒後盛起，不只看外面金黃。"},{"step_no":3,"old":"小鍋加入粟米粒和水，中火煮 3 分鐘。","text":"小鍋加入粟米粒及餘下105毫升水，中火煮約3分鐘至粟米熱透。"},{"step_no":5,"old":"加入生粉水煮至汁微稠。","text":"把預留生粉水再攪勻，慢慢倒入粟米蛋花汁並攪勻，煮滾至薄芡，確認蛋液完全凝固。"}],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":[{"text":"先從全份120毫升水中取15毫升冷水，拌勻1茶匙生粉留用；魚柳抹乾，拌入材料表的鹽和白胡椒。","step_no":1},{"text":"平底鑊加入全份食油，中火把魚柳煎至熟透，確認最厚中心達75°C並維持至少30秒後盛起，不只看外面金黃。","step_no":2},{"text":"小鍋加入粟米粒及餘下105毫升水，中火煮約3分鐘至粟米熱透。","step_no":3},{"text":"慢慢倒入蛋液，同時輕輕攪拌成蛋花粟米汁。","step_no":4},{"text":"把預留生粉水再攪勻，慢慢倒入粟米蛋花汁並攪勻，煮滾至薄芡，確認蛋液完全凝固。","step_no":5},{"text":"將粟米汁淋在魚柳上即可。","step_no":6}]},{"id":"7eba5374-0d0a-4ef0-ae15-8dd54ef38018","slug":"prepmeal-batch2-25","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"e024aa993f1bb398bcdb6ebb41b84028e7735b4734c59f47c0516b018c36bf65","cooking_tips":["189克粟米指熟、瀝乾後重量，罐頭須確認即食，乾生粟米不能同重代替。","小餅攤至約0.8至1厘米厚，底面定形才翻；中心蛋糊也須全熟，不另加泡打粉。"],"pairing_suggestions":["可配「蒜蓉西蘭花」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"550f3386-8db4-418e-8608-c169717675b8","slug":"corn-carrot-pork-bone-soup","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"67740e4bcbd2e200f9a948be49e66027f7b4da6ffc5afdcfdfffbf07e938cfc7","cooking_tips":["粟米100克含芯、紅蘿蔔80克不含皮，秤量方式不同，不能都按去皮去芯重量代入。","湯料煮熟後把湯量調到400毫升；粟米芯與骨不吃，可食湯渣已包括在本餐估算內。"],"pairing_suggestions":["可配「肉碎豆腐」與「清炒椰菜」，再按需要配主食；本頁的湯不是另外的飯量。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"6eeaa50a-da2c-40d6-9545-103c274eba63","slug":"corn-minced-pork","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"c82a91d1f7dd8e2606a040998e5a0c5afe4b3c8f5e8d7d1eb040ffb65d5e430b","cooking_tips":["豬肉碎先炒散，再與粟米煮至全熟，不能只看表面轉色便直接勾芡起鑊。","生粉水加入前再攪勻，先從材料表的總水量預留調粉水，不重複添加一份水量。"],"pairing_suggestions":["可配「蒜蓉生菜」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[{"step_no":1,"old":"豬肉碎加入生抽半份和糖拌勻；蒜頭切蓉。","text":"從全份120毫升水中先預留15毫升冷水拌勻1茶匙生粉。肉碎拌入一半生抽與糖，蒜頭切蓉。"},{"step_no":4,"old":"加入粟米、餘下生抽、蠔油和水，拌勻後煮滾。","text":"加入粟米、餘下生抽、蠔油及餘下105毫升水，拌勻後煮滾。"},{"step_no":6,"old":"加入生粉水煮至汁微稠，即可上碟。","text":"生粉水再攪勻後慢慢加入，煮滾至薄芡並確認肉碎熟透、全鍋中心達75°C並維持至少30秒後上碟。"}],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":[{"text":"從全份120毫升水中先預留15毫升冷水拌勻1茶匙生粉。肉碎拌入一半生抽與糖，蒜頭切蓉。","step_no":1},{"text":"鑊中加入食油，中火爆香蒜蓉。","step_no":2},{"text":"加入豬肉碎炒散，炒至完全轉色。","step_no":3},{"text":"加入粟米、餘下生抽、蠔油及餘下105毫升水，拌勻後煮滾。","step_no":4},{"text":"轉中小火煮 4 至 5 分鐘，讓粟米甜味煮出來。","step_no":5},{"text":"生粉水再攪勻後慢慢加入，煮滾至薄芡並確認肉碎熟透、全鍋中心達75°C並維持至少30秒後上碟。","step_no":6}]},{"id":"37560d69-a723-4bb3-91b4-0ded9a53eaac","slug":"corn-egg-drop-soup-xhs","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"031989b245d368e34c5632dd8913bd08d0553ed90fc04111a18aa08f01aae4a7","cooking_tips":["粟米先煮出味，蛋液才以細流倒入並輕攪，避免湯中留一大塊未散的蛋。","蛋花須煮至完全凝固才關火，蔥花只是收尾，不能用下蔥的時機代替判熟。"],"pairing_suggestions":["可配「孜然香辣烤豆腐」與「清炒菜心」，再按需要配主食；本頁的湯不是另外的飯量。"],"references":[]},"changed_steps":[{"step_no":6,"old":"灑上蔥花，關火即可。","text":"繼續煮至蛋花完全凝固、湯滾燙，再灑蔥花並關火盛起；不保留流動生蛋液。"}],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":[{"text":"粟米粒備用，雞蛋打散，蔥切粒。","step_no":1},{"text":"鍋中加入清水約 300 毫升，加入粟米粒。","step_no":2},{"text":"中火煮 5 分鐘，讓粟米甜味煮出來。","step_no":3},{"text":"加入鹽約1/8茶匙調味。","step_no":4},{"text":"轉小火，慢慢倒入蛋液，同時輕輕攪拌成蛋花。","step_no":5},{"text":"繼續煮至蛋花完全凝固、湯滾燙，再灑蔥花並關火盛起；不保留流動生蛋液。","step_no":6}]},{"id":"63a5ab23-6828-44fc-9084-22a07b2d45d6","slug":"corn-fish-rice","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"6546eb2b3bc497eb7b1d65b9031b7511528edc4482af9df7d67f61cf6d359151","cooking_tips":["生粉已用在魚柳裹粉，不為想要更厚粟米汁再加未列出的生粉。","魚柳先煎熟，再回粟米汁短拌；180克白飯已在材料中，不另外重複配飯。"],"pairing_suggestions":["本餐已包含主食，可配「清炒菜心」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"9d4a5d2a-f872-4dfb-acc4-39c55a7ce11f","slug":"thai-red-curry-chicken","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"fe8139e2f0c6315725ea59fafcfb126d9ebd25b8d3116718b308ceb1e8cb3172","cooking_tips":["紅咖哩醬先短炒出香，不以大火把醬炒乾變焦才加雞件。","雞件轉色後仍須在椰奶汁中煮熟，最厚中心熟透才收火，不只看汁已濃。"],"pairing_suggestions":["可配「蒜蓉生菜」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"bb378af9-9522-4588-b776-4bd3a9f246cc","slug":"seaweed-egg-drop-soup-xhs","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"adcb0503602b80008c3d7b5aafeb4697104393e66cba7426ed42915d4264a577","cooking_tips":["紫菜按包裝需要沖洗或浸軟，煮湯的300毫升水與清洗用水分開。","蛋液在小火下慢慢倒入，全部凝固後才停火，不把生蛋液留到餘溫自行處理。"],"pairing_suggestions":["可配「孜然香辣烤豆腐」與「清炒芥蘭」，再按需要配主食；本頁的湯不是另外的飯量。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}]},"changed_steps":[{"step_no":6,"old":"灑上蔥花，關火即可。","text":"繼續煮至蛋花完全凝固、湯滾燙，再灑蔥花並關火盛起；不保留流動生蛋液。"}],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":[{"text":"紫菜用清水快速沖洗或浸軟，雞蛋打散。","step_no":1},{"text":"鍋中加入清水約 300 毫升，煮滾。","step_no":2},{"text":"加入紫菜煮 1 分鐘。","step_no":3},{"text":"轉小火，慢慢倒入蛋液，同時用筷子輕輕攪拌形成蛋花。","step_no":4},{"text":"加入鹽約1/8茶匙調味。","step_no":5},{"text":"繼續煮至蛋花完全凝固、湯滾燙，再灑蔥花並關火盛起；不保留流動生蛋液。","step_no":6}]},{"id":"74ac8b53-880d-4136-a955-64dcc803e9ec","slug":"basil-tomato-chicken-risotto","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"a39d26666e273d38e7e46a9c4c11d4d82fa30a284e2820f4163c807672710084","cooking_tips":["意大利燴飯米直接炒香後分次加熱湯，不先當普通白飯煮熟再加汁。","雞肉前段只是轉色，回鍋後仍須煮熟；羅勒及選配芝士在熄火後拌入。"],"pairing_suggestions":["本餐已包含主食，可配「蒜蓉生菜」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"52043e65-9e24-44a7-9434-dbc66ce36c02","slug":"borscht-style-beef-vegetable-soup","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"d3888a0aa49cf63179b1ab0504c99acae7816742182f515aab6d136df9aa7cbf","cooking_tips":["牛肉與根菜切成相若小件，蔬菜軟後仍檢查牛肉是否熟透，不能只按三十分鐘停火。","月桂葉煮出味後食用前取走，不當成可直接吃的菜葉。"],"pairing_suggestions":["這道菜已有薯仔，可配「蒜蓉西蘭花」；其他主食按整餐份量安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"b4622561-3d51-482e-8529-c33ce6873eab","slug":"zucchini-mushroom-chicken-stir-fry","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"46ce866e8e63f2cb8ed965eee155821ff7448bb42a31ed2c0cc4983dadbdf737","cooking_tips":["半茶匙油炒雞、另半茶匙炒菜，分段煮不代表每次都可再加一整份油。","盛未全熟雞柳的碟只在雞柳回鍋前使用，完成後用乾淨碟上菜，最厚中心須達75°C至少30秒。"],"pairing_suggestions":["可配「蒜蓉西蘭花」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"27e0797a-77f1-4687-91ba-9221cf8b3b8f","slug":"minced-pork-steamed-egg","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"a9077c5b1eb7bfec7dc9c9d7e6d02ba8f04d67be0eca52e63045a6048fc6da4b","cooking_tips":["肉碎鋪底時盡量攤薄並撥散，不能只見蛋面凝固便假定底部豬肉已熟。","檢查最厚肉蛋交界處中心達75°C至少30秒，蓋碟蒸及關火焗不能代替熟度量度。"],"pairing_suggestions":["可配「蒜蓉生菜」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}]},"changed_steps":[{"step_no":5,"old":"蛋面凝固後關火焗 2 分鐘。","text":"蛋面凝固後檢查中心及底部肉碎，未熟須繼續蒸，不單靠蛋面狀態決定關火。"},{"step_no":6,"old":"確認中心沒有流動蛋液即可。","text":"以食物溫度計確認最厚肉蛋交界處中心達75°C並維持至少30秒，蛋液完全凝固、肉碎熟透後才取出。"}],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":[{"text":"豬肉碎加入生抽和麻油拌勻。","step_no":1},{"text":"雞蛋打散，加入水和鹽拌勻。","step_no":2},{"text":"將肉碎鋪在碗底，再倒入蛋液。","step_no":3},{"text":"蓋上碟，水滾後中小火蒸 12 分鐘。","step_no":4},{"text":"蛋面凝固後檢查中心及底部肉碎，未熟須繼續蒸，不單靠蛋面狀態決定關火。","step_no":5},{"text":"以食物溫度計確認最厚肉蛋交界處中心達75°C並維持至少30秒，蛋液完全凝固、肉碎熟透後才取出。","step_no":6}]},{"id":"558fef74-be29-4855-bccb-93acc122c593","slug":"minced-pork-vermicelli-pot","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"663f2740edb5940411c966397c34cf0f61eeb1cc3606624594faa16fe6d9e2e3","cooking_tips":["粉絲浸軟後仍要在肉汁內煮透，吸到汁便開始留意鍋底，避免一下收乾黏底。","肉碎先炒散並繼續煮熟；粉絲保持濕潤便可，不用追求完全乾身。"],"pairing_suggestions":["這道菜已有乾綠豆粉絲，可配「蒜蓉西蘭花」；其他主食按整餐份量安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"555a6ea5-b18f-4ba4-8caf-1945b0808304","slug":"prepmeal-batch3-23","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"2390376b262696b87bac746f36cb0d9421aa4775cc5eb310e17b65b10f11b80f","cooking_tips":["豬肉碎先炒熟並稍降溫才拌蛋，不能把生肉混進厚蛋餅只煎表面。","兩小塊合共一人份，餅中心的蛋與芽菜也要熟透，煎油按全份量分批用。"],"pairing_suggestions":["可配「清炒椰菜」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"5ada5229-ef1e-4931-841b-436db62c8943","slug":"minced-pork-tofu","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"00f007515e6c118b5d04b7b66d9e6dae92c4870a672dc843c6b557529e58ddfa","cooking_tips":["生粉沉底很快，倒入前再攪一次，可避免先倒清水、最後才掉下一團粉。","豆腐下鑊後用推動代替大力翻炒；醬汁只需薄薄掛面，不必收至乾身。"],"pairing_suggestions":["可配蠔油生菜及白飯；這道菜已有豬肉和豆腐，可按整餐需要決定是否另加肉菜。"],"references":[{"title":"Christine Ho：魚香豆腐","url":"https://www.christinesrecipes.com/2017/03/tofu-and-pork-in-chilli-bean-sauce.html?m=0"},{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}]},"changed_steps":[{"step_no":1,"old":"豬肉碎加入生抽半份和糖拌勻；豆腐切件，蒜頭切蓉。","text":"從材料表的100毫升水中，先取15毫升冷水拌勻1茶匙生粉，餘下85毫升留作炆煮。豬肉碎拌入半份生抽及糖；豆腐切件，蒜頭切蓉。"},{"step_no":2,"old":"鑊中加入 1 茶匙食油，中火爆香蒜蓉。","text":"鑊中加入1茶匙食油，中火炒香蒜蓉；聞到香味便加入豬肉碎，避免蒜蓉炒黑。"},{"step_no":3,"old":"加入豬肉碎炒散，炒至完全轉色。","text":"用鑊鏟把肉碎壓散，炒至沒有大塊結團；表面轉色後仍須在其後步驟繼續煮熟。"},{"step_no":4,"old":"加入豆腐、餘下生抽、蠔油和 100 毫升水，輕輕推勻。","text":"加入豆腐、餘下生抽、蠔油及預留的85毫升水，從鑊邊輕推拌勻。"},{"step_no":5,"old":"加蓋中小火煮 4 至 5 分鐘，讓豆腐入味。","text":"煮滾後轉中小火，加蓋煮約4至5分鐘，讓豆腐熱透；確認肉碎熟透，不以表面轉色作唯一判斷。"},{"step_no":6,"old":"從材料表所列的100毫升水中預留少量，拌勻生粉1茶匙後加入；煮至汁微稠、肉碎熟透即可。","text":"重新攪勻生粉水，沿鑊邊慢慢加入並輕推；煮滾至醬汁均勻、沒有生粉感，食物中心達75°C並維持至少30秒後盛起。"}],"ingredient_changes":[],"old_recipe":{"description":"肉碎與豆腐同煮，鹹鮮柔滑，是簡單的家常菜。"},"new_recipe":{"description":"肉碎先炒散，再與豆腐短時間炆煮，最後用薄芡把醬汁掛在豆腐上。豆腐下鑊後少翻動，較容易保持完整。"},"target_steps":[{"text":"從材料表的100毫升水中，先取15毫升冷水拌勻1茶匙生粉，餘下85毫升留作炆煮。豬肉碎拌入半份生抽及糖；豆腐切件，蒜頭切蓉。","step_no":1},{"text":"鑊中加入1茶匙食油，中火炒香蒜蓉；聞到香味便加入豬肉碎，避免蒜蓉炒黑。","step_no":2},{"text":"用鑊鏟把肉碎壓散，炒至沒有大塊結團；表面轉色後仍須在其後步驟繼續煮熟。","step_no":3},{"text":"加入豆腐、餘下生抽、蠔油及預留的85毫升水，從鑊邊輕推拌勻。","step_no":4},{"text":"煮滾後轉中小火，加蓋煮約4至5分鐘，讓豆腐熱透；確認肉碎熟透，不以表面轉色作唯一判斷。","step_no":5},{"text":"重新攪勻生粉水，沿鑊邊慢慢加入並輕推；煮滾至醬汁均勻、沒有生粉感，食物中心達75°C並維持至少30秒後盛起。","step_no":6}]},{"id":"64191215-0bce-47fb-9c68-aca58a01a1c9","slug":"crispy-potato-pancake","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"522c38e030c897808d6e0d5091ee788c53a8e3e99275917e887bbc161f478a99","cooking_tips":["薯絲沖去表面澱粉後須徹底擠乾，才不會令蛋餅糊太濕而難定形。","薄薄壓平後等底面定形才翻，薯絲與中心蛋液都要煮熟，不能只靠兩面香脆判斷。"],"pairing_suggestions":["這道菜已有薯仔，可配「清炒菜心」；其他主食按整餐份量安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"4991fb9e-d625-4fd2-b245-b091ce8d4054","slug":"fermented-beancurd-water-spinach","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"9fef59c35d2ab8af74f09bb23cc132a78fbf775301dfa79a689e1871d5dcd034","cooking_tips":["腐乳先壓碎並用材料表的水調開，避免菜上留一大粒過鹹腐乳。","通菜瀝乾後快炒，腐乳汁已提供鹹味，不另加未列的鹽或生抽。"],"pairing_suggestions":["可配「豆腐雞蛋白菜卷」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"3e812e48-fc4e-440d-8c80-7dc58377c16c","slug":"prepmeal-batch4-14","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"57720be6108078d09f52694bf0331f1cd041304008e975dac229ba4d257ad07f","cooking_tips":["四季豆須煮至內外全熟，粗豆要延長，不把保持爽脆當成可以生硬的理由。","瀝乾後才拌一湯匙現成醬，不另加生抽糖鹽，並核對所用醬汁的致敏原。"],"pairing_suggestions":["可配「孜然香辣烤豆腐」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[{"title":"食物安全中心：未煮熟豆類中的天然毒素","url":"https://www.cfs.gov.hk/tc_chi/multimedia/multimedia_pub/multimedia_pub_fsf_139_04.html"}],"served_cold":true},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"ff2d0784-7319-443f-b455-15768b76df4d","slug":"tomato-braised-fish-fillet","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"d48051e7743255ef55c5c38e27a346b8ad61e21d5a117a09d91151127d952f40","cooking_tips":["番茄先炒出汁再放魚，魚柳切成相若厚度，避免薄片散爛而厚件仍生。","魚柳入汁後輕推並煮至中心熟透，不因茄汁變濃就提早關火。"],"pairing_suggestions":["可配「清炒菜心」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[{"old":null,"new":{"id":"4d32e561-50ac-4bb4-be6e-43c12a72e397","name":"水","quantity":30,"unit":"ml","note":"步驟已使用的煮食水；按材料表總量分配，不另計浸洗或倒走的汆水","optional":false}}],"old_recipe":{},"new_recipe":{},"target_steps":[{"text":"魚柳切件並抹乾，番茄切件，洋蔥切絲。","step_no":1},{"text":"平底鑊加入 1 茶匙油，中火炒香洋蔥。","step_no":2},{"text":"加入番茄炒 2 至 3 分鐘至出汁。","step_no":3},{"text":"加入番茄醬約 1 湯匙、糖少許和 2 湯匙水拌勻。","step_no":4},{"text":"放入魚柳，轉中小火煮 5 至 6 分鐘。","step_no":5},{"text":"魚柳熟透、醬汁微稠後即可上碟。","step_no":6}]},{"id":"9e94813f-2564-4ab3-a156-813c369c211f","slug":"dried-vegetable-pork-bone-soup","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"7603a37277a0a8e6cdf02412fb939a809375626a823fe434597bd4a7697d91c5","cooking_tips":["10克白菜乾先浸軟逐葉洗沙，浸洗水與材料表600毫升煲湯水分開。","最後量湯至400毫升再連湯料享用，排骨只吃肉不吃骨，不能把湯渣當成未計材料。"],"pairing_suggestions":["可配「肉碎豆腐」與「清炒椰菜」，再按需要配主食；本頁的湯不是另外的飯量。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"b5cc0d1a-9c67-4f55-bed2-861b1d631d01","slug":"preserved-radish-omelette","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"09a5636e7124c6194413e89f15854918e0f178f6fc839a2e46f5f0f58e6c3598","cooking_tips":["菜脯沖洗切碎後瀝乾才拌蛋，避免洗菜水把蛋液稀釋。","菜脯已有鹹味，本版不另加鹽；翻面後確認中心蛋液全熟才上碟。"],"pairing_suggestions":["可配「蒜蓉生菜」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"427befd5-7838-44b3-8868-00fb40b7aad6","slug":"spinach-oat-shrimp-cakes","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"70de527cb416b69167100a2913e3816ad4fbd4843abae880b777a9628e9e727f","cooking_tips":["80克菠菜指焯水前重量，擠乾切碎後全部拌入，不再補至80克熟菠菜。","四件薄餅合共一人份，厚約0.8厘米，中心須達75°C至少30秒，不另加未列醬汁。"],"pairing_suggestions":["可配「清炒芥蘭」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"c5ba657e-15c2-4d48-9d33-bfc70ead04e9","slug":"spinach-tofu-soup-xhs","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"4b8c9ff1f45d3cd427b9bab30204e227a25bfd7d7c50c831dccf29a02e975473","cooking_tips":["豆腐先熱透才下菠菜，葉菜軟化便檢查，避免豆腐和菠菜一起長時間煮爛。","菠菜輕壓入熱湯而不大力攪，既讓葉片均勻受熱，也較不會弄碎豆腐。"],"pairing_suggestions":["可配「蒸水蛋」與「蒜蓉西蘭花」，再按需要配主食；本頁的湯不是另外的飯量。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"93468176-c808-4456-99e0-8893c7dc609c","slug":"prepmeal-25-22-chicken-adobo","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"740fc1180a85577bd89a37d0c07f763b7c9f23a5f5618020a7cd2ae1c7374a42","cooking_tips":["雞皮先向下煎香再加醋汁炆，醬汁滾後仍要把最厚近骨肉部煮熟。","月桂葉出味後取走；醋只是調味，不能代替雞肉的加熱處理。"],"pairing_suggestions":["可配「清炒菜心」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"6f243da5-911a-4704-b0bd-860a4cd0a89a","slug":"prepmeal-batch4-09","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"7b24fe9d90d960b1a98bc14b838b5d8f45bea6bb9dc574ba1c6263a1b3c44a60","cooking_tips":["梅頭肉逐片放進滾水撥散，避免一大堆肉同時下鍋令水溫急跌。","蒜蔥汁用已煮沸飲用水調，熟肉盛在乾淨碟，烚肉水不當成另加的一碗湯。"],"pairing_suggestions":["可配「蒜蓉西蘭花」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"753c1993-6d5c-4804-ad85-051ef57f2ccf","slug":"garlic-beef-cubes-slices","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"1621732dbf9911f684dfd88439f5e747cce80ef0d8aecec4670ffd302949321f","cooking_tips":["蒜片先以中小火煎香盛起，等牛肉接近完成才回鍋，不陪全程高溫煎焦。","牛肉粒大小不同，逐面煎一分鐘只是參考；最厚中心須熟透，不只看外層焦香。"],"pairing_suggestions":["可配「清炒菜心」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[{"step_no":6,"old":"牛肉中心仍嫩、表面有香味即可上碟。","text":"確認最厚牛肉粒中心達75°C並維持至少30秒，按大小調整時間後上碟；不能只用每面數十秒或外皮焦香判斷已熟。"}],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":[{"text":"牛肉切粒，用生抽、蠔油、生粉和黑胡椒拌勻，醃 10 分鐘。","step_no":1},{"text":"蒜頭切片，平底鑊加入食油，中小火煎蒜片至金黃，先盛起。","step_no":2},{"text":"原鑊轉中大火，放入牛肉粒。","step_no":3},{"text":"每面煎約 1 分鐘，煎至表面焦香。","step_no":4},{"text":"放回蒜片，快速拌炒 30 秒。","step_no":5},{"text":"確認最厚牛肉粒中心達75°C並維持至少30秒，按大小調整時間後上碟；不能只用每面數十秒或外皮焦香判斷已熟。","step_no":6}]},{"id":"13a6c777-fce5-4f8a-93d0-1dca46eb9caa","slug":"garlic-napa-xhs","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"e45fd246298c88a1a0a0889a6c3462b0aa7c6f9e92b30b556911778dd7ba3d81","cooking_tips":["娃娃菜切成相若厚度，厚菜梗也接觸到15毫升煮水，蒸氣才較易把梗煮軟。","開蓋後略收汁便可，蒜蓉不要一開始炒至深啡，避免整碟菜帶苦味。"],"pairing_suggestions":["可配「蒸水蛋」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"884c47af-bb79-435c-a4ec-21151721833a","slug":"garlic-romaine-lettuce","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"de3de3ae067024a0eb33d33ab48b5ac34c7123c93a35cdfc3c289dfd2ff7f9d7","cooking_tips":["油麥菜洗淨瀝乾、切成相若長度，入鑊後用大火短炒，不在菜已軟後久炒。","選配水只在鑊乾時少量加入，菜已出水便不再倒足20毫升。"],"pairing_suggestions":["可配「薑蔥豉油蒸豆腐（簡易版）」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"da2b2dba-09df-4bae-9b0c-0be8938be3e8","slug":"steamed-garlic-pumpkin","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"8cd29b350ee61c89fef99a374131ab0c712b526fcd49b28b12c8463710520e20","cooking_tips":["南瓜厚約2厘米且單層鋪放，厚薄不一或重疊會令蒸熟時間差很多。","先用筷子檢查較厚中心可輕易插入，生抽只在選用時按總量淋上，不另加一份熱油。"],"pairing_suggestions":["可配「豆腐雞蛋白菜卷」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"90d23ff8-7a4b-403b-b82b-35541302db7c","slug":"garlic-steamed-shrimp","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"410e042b691e72dac7b46423addf5e11d34e16cf5fa41f21416456ada3c73200","cooking_tips":["蝦開背後排開不重疊，蒜蓉調味鋪勻，按蝦的大小延長至中心熟透。","拌蒜及最後淋面的油合共仍是材料表總量，不在兩處各用一全份油。"],"pairing_suggestions":["可配「清炒菜心」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"201affc0-a59d-4012-9656-346d4a1d5fff","slug":"garlic-lettuce","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"82273dc676af15a3d9c9907ad7c4d7c85153b6e45983a61763384f5e60651d66","cooking_tips":["生菜先瀝乾再短炒，葉片熟軟便盛起，避免一直留鑊變成一碟菜水。","最多20毫升是選配水上限，不是每次必加；鹽按材料表調味，不再加生抽。"],"pairing_suggestions":["可配「蒸水蛋」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"1d8364f5-5068-4bfc-992b-81abbfe7810a","slug":"prepmeal-batch2-22","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"801e1a01a9fe0077368c0ba6750f59a59545dc980f4aaec092cc9732aee841f5","cooking_tips":["粉絲浸軟並瀝乾才鋪底，帶子完全解凍後排開，不能只因表面變白就當中心已熟。","本版不炸蒜、不淋熱油；收尾的醬汁與蒜蓉依材料表總量分配，不另加一份油。"],"pairing_suggestions":["這道菜已有乾綠豆粉絲，可配「清炒椰菜」；其他主食按整餐份量安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"abe99804-e55c-4db9-a2bf-a1c2eb78bc61","slug":"garlic-spinach","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"b3e0f722f4b7a8b4aef8143116b54671c963e52594b5ad7e4afa804a057a5e5e","cooking_tips":["菠菜葉柄位置容易夾泥沙，洗淨瀝水後再下鑊，避免把洗菜水當煮水。","葉片軟化便檢查菜梗熟度，選配水按需要加，不為收乾所有水而久炒。"],"pairing_suggestions":["可配「蒸水蛋」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"1007e867-9dc6-44ab-868e-46b297f4710b","slug":"garlic-broccoli","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"159f4d3284f45bf897cf1c134df5a52146697d8af51d5299e60facd8df44f740","cooking_tips":["不要只看花朵顏色判斷口感，可試一片較厚的莖，確認沒有生硬感。","汆過水後立即瀝乾再炒；本版不另加冰水浸泡、鹽水或額外油。"],"pairing_suggestions":["可配照燒雞扒及白飯；也可與肉碎豆腐配成一餐。"],"references":[{"title":"Made With Lau：Broccoli Stir Fry","url":"https://www.madewithlau.com/recipes/broccoli-stir-fry"}]},"changed_steps":[{"step_no":1,"old":"西蘭花切小朵，洗淨瀝乾；蒜頭切碎。","text":"西蘭花180克洗淨，切成大小相若的小朵；較粗的莖去掉硬皮後切薄片，蒜頭切碎。"},{"step_no":2,"old":"煲滾一鍋清水（汆水用，不計入成品），將西蘭花汆水1分鐘後瀝乾；不用另加鹽。","text":"煲滾汆水用清水，較粗的莖片先下，再放花朵，汆約1分鐘；汆水不加鹽或油，不計入成品用水。"},{"step_no":3,"old":"鑊中加入 1 茶匙食油，中火爆香蒜蓉。","text":"撈起西蘭花並充分瀝水，避免把大量汆水一併倒進炒鑊。"},{"step_no":4,"old":"加入西蘭花大火翻炒。","text":"鑊中加入1茶匙食油，中火炒香蒜蓉；蒜蓉未變深啡前加入西蘭花，轉大火翻炒。"},{"step_no":5,"old":"如鑊太乾，可按需要加入最多30毫升選配清水；加入鹽1/8茶匙，炒至熟透。","text":"按需要加入材料表的選配水，最多30毫升，加入鹽1/8茶匙拌勻；煮至較厚莖部熟透，仍保留少許咬口。"},{"step_no":6,"old":"試味後即可上碟。","text":"趁熱盛起；如鑊內已有水分，無須為用盡材料表的選配水而全部加入。"}],"ingredient_changes":[],"old_recipe":{"description":"西蘭花以蒜蓉炒香，菜味清甜，適合作家常配菜。"},"new_recipe":{"description":"西蘭花先短時間汆水，再與蒜蓉快炒。把花朵切得大小相若，並瀝乾後才下鑊，較容易保留口感。"},"target_steps":[{"text":"西蘭花180克洗淨，切成大小相若的小朵；較粗的莖去掉硬皮後切薄片，蒜頭切碎。","step_no":1},{"text":"煲滾汆水用清水，較粗的莖片先下，再放花朵，汆約1分鐘；汆水不加鹽或油，不計入成品用水。","step_no":2},{"text":"撈起西蘭花並充分瀝水，避免把大量汆水一併倒進炒鑊。","step_no":3},{"text":"鑊中加入1茶匙食油，中火炒香蒜蓉；蒜蓉未變深啡前加入西蘭花，轉大火翻炒。","step_no":4},{"text":"按需要加入材料表的選配水，最多30毫升，加入鹽1/8茶匙拌勻；煮至較厚莖部熟透，仍保留少許咬口。","step_no":5},{"text":"趁熱盛起；如鑊內已有水分，無須為用盡材料表的選配水而全部加入。","step_no":6}]},{"id":"68f1c838-ef2e-4b0b-8232-5df00bf84b81","slug":"garlic-pea-shoots-xhs","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"980a7a5c3e233252e923c83270541699727c2e976437c2734d007628d985b054","cooking_tips":["豆苗先瀝乾，蒜蓉未炒深色便下菜，避免焦蒜蓋過豆苗味。","定量15毫升水協助受熱，菜一軟熟便盛起，不能為收乾汁而一直翻炒。"],"pairing_suggestions":["可配「薑蔥豉油蒸豆腐（簡易版）」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"b438cf0e-17af-4a83-9dc9-d3708c347135","slug":"garlic-water-spinach","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"6258592f28141c14846f8a86f3880bd86b6619f25e1790eaa3b13f5f9f642d38","cooking_tips":["通菜洗後瀝水、粗莖與嫩葉分清，粗莖可先下，避免薄葉已爛而莖仍生硬。","材料表的水用來幫助均勻受熱，熟軟後快盛起，不追求把菜汁煮至全乾。"],"pairing_suggestions":["可配「薑蔥豉油蒸豆腐（簡易版）」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"34eabb40-e270-4f05-b2d1-2a045f4cd948","slug":"garlic-enoki-xhs","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"c264898282ffa6438588baccac4df4934011446116ebf3126aa965623c178ce1","cooking_tips":["金針菇根部切去並拆散，不能把整束厚根直接下鑊只煮軟表面。","金針菇須徹底煮熟，生抽用材料表的總量，不因試味而反覆額外補醬。"],"pairing_suggestions":["可配「薑蔥豉油蒸豆腐（簡易版）」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"5d62b852-95c0-443c-a7af-9c2144428ca9","slug":"prepmeal-batch4-05","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"56a62aef279ec7ce7c15c70f8476a8e4a82f72321cd42c6bea96ba39cd0f4ab0","cooking_tips":["魚滑平鋪約5至8毫米厚，勝瓜厚約1.5厘米，避免做成中間難熟的厚魚滑團。","已調味魚滑的外觀變白不等於中心熟，檢查中心熟透、瓜件軟身才取出。"],"pairing_suggestions":["可配「清炒菜心」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"fd63e73a-9b5e-4087-a7ba-399f4c7042c1","slug":"prepmeal-batch4-25","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"3748e2e10ba93076f56905b774a58e95d296f4cd9edcfd0c52b2026a9cb8be83","cooking_tips":["南瓜按步驟切約7毫米厚，先煮至接近熟才盛起，蝦不用陪南瓜全程煮。","南瓜回鍋用輕翻保持形狀，蝦仁最厚中心須熟透，不另添頭抽或生粉濃芡。"],"pairing_suggestions":["可配「清炒菜心」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"3ecc09f9-949a-460e-af41-88474be6fbab","slug":"prepmeal-batch2-13","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"60733713c14ecbfacb288f0f3f8cc0cea2e3bf88241a68857878417c9f95c0b6","cooking_tips":["意粉煮水不加鹽，瀝起前只留15毫升來拌汁，鹽留在材料表的調味份量內。","吞拿魚瀝乾、蒜蓉短炒，檸檬汁拌勻便可，不為收汁把罐頭魚久炒至乾。"],"pairing_suggestions":["本餐已包含主食，可配「蒜蓉生菜」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"2efb4c55-8fd2-466a-9135-eadd27af16b7","slug":"braised-eggplant","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"bac286fead9e112a3ce6f78630ad356322285f3b5246189600d9bed2900cab72","cooking_tips":["茄子先炒略軟再下蒜，避免蒜蓉跟整段炆煮一起先炒焦。","選配糖與最多40毫升清水按需要用，茄子軟後略收汁，不額外淋油去追求油亮。"],"pairing_suggestions":["可配「豆腐雞蛋白菜卷」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"52757240-8030-4ae0-b705-66e074c8b162","slug":"herb-baked-salmon-with-potatoes","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"93bf30b1542a313d02be0feb8ce5db483b414e3b8bec754d3b35d469b327a198","cooking_tips":["薯仔先焗至開始軟身再放魚，不能把魚與生薯仔同一時間下盤便沿用短魚時間。","橄欖油與鹽胡椒各分兩段用，不在魚和薯仔上各抹全份；西蘭花只在選用時加入。"],"pairing_suggestions":["本餐已包含主食，可配「清炒菜心」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"3698b763-2da4-4413-a25b-39b3fbc1a3d9","slug":"garlic-butter-shrimp-pasta","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"0d07e007263fa60e99601ee68ed51e61fa4013c92f5445a3e00517cb649e4e57","cooking_tips":["蝦兩面轉色後先盛起，最後回鍋仍要煮至中心熟透，不止拌到表面熱。","牛油前後分配使用，麵水逐少調汁；車厘茄屬選配，不選便不另找其他餡料補入。"],"pairing_suggestions":["本餐已包含主食，可配「清炒芥蘭」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[{"step_no":6,"old":"最後把蝦回鍋翻勻，試味後即可上碟。","text":"蝦回鍋後繼續翻拌煮至中心全熟、整份意粉熱透，再按材料表總量試味，不把前段蝦轉色當成已熟。"}],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":[{"text":"意粉煮熟並保留 2 湯匙煮麵水；蝦仁抹乾後以鹽少許和黑胡椒少許調味。","step_no":1},{"text":"蒜頭切蓉；如選用車厘茄，洗淨切半。","step_no":2},{"text":"平底鑊加入橄欖油和一半牛油，放入蝦仁煎至兩面轉色後先盛起。","step_no":3},{"text":"原鍋加入蒜蓉炒香；如選用車厘茄，加入略炒1分鐘。","step_no":4},{"text":"加入意粉、剩餘牛油和少量煮麵水，拌至醬汁包裹意粉。","step_no":5},{"text":"蝦回鍋後繼續翻拌煮至中心全熟、整份意粉熱透，再按材料表總量試味，不把前段蝦轉色當成已熟。","step_no":6}]},{"id":"0679c8a0-b244-4426-967c-e61fb25fa6bd","slug":"garlic-beef-cubes","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"a52b9ecd8dba7407269618466314a3c5db7d95f71f87150b905092ded167c4d8","cooking_tips":["牛油前後分段用，蒜片後下，避免從一開始就陪牛肉高溫煎至發苦。","每面三四十秒不能保證厚牛柳粒熟透，應檢查最厚中心，不以微嫩作唯一完成標準。"],"pairing_suggestions":["可配「清炒菜心」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[{"step_no":6,"old":"牛肉中心仍微嫩時即可上碟，避免煎過熟。","text":"確認最厚牛肉粒中心達75°C並維持至少30秒，按大小調整時間後上碟；不能只用每面數十秒或外皮焦香判斷已熟。"}],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":[{"text":"牛肉粒用廚紙抹乾，加入鹽少許和黑椒少許拌勻。","step_no":1},{"text":"蒜頭切片，牛油準備好。","step_no":2},{"text":"平底鑊加入一半牛油，中火加熱後放入牛肉粒。","step_no":3},{"text":"每面煎約 30 至 45 秒，煎至表面焦香。","step_no":4},{"text":"加入餘下牛油和蒜片，拌炒至蒜片出香味。","step_no":5},{"text":"確認最厚牛肉粒中心達75°C並維持至少30秒，按大小調整時間後上碟；不能只用每面數十秒或外皮焦香判斷已熟。","step_no":6}]},{"id":"a2308bb5-667b-4221-b25d-a64f7c1069af","slug":"garlic-eggplant","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"484f11c9211914bb75a9d3f151c205a86d0b82b26cd717e1487056969117f0f0","cooking_tips":["茄子先炒略軟再加45毫升水加蓋炆，讓中心熟軟而非只煎香外皮。","生抽、蠔油與糖用原定份量，開蓋略收汁便可，不另加油把茄子泡油。"],"pairing_suggestions":["可配「豆腐雞蛋白菜卷」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"f7415cac-3de3-4217-8754-9fa36bfbb4ff","slug":"garlic-shrimp-xhs","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"c44e03ec935dcb333f8b724dd0041d7f4570c35c196d37075df0b7dbf2013a20","cooking_tips":["蝦仁抹乾才落鑊，蒜蓉炒到香便加蝦，不先把蒜炒黑。","一分鐘一面只作參考，蝦仁中心須熟透才起鑊，不能以轉色代替檢查。"],"pairing_suggestions":["可配「蒜蓉生菜」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"ee392489-1257-4b80-8b6a-3ca4891ffb78","slug":"garlic-pork-cubes","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"1b54ffc4bbc2cc387677b251f4d502e197ce409e35b03c426a33e0fcf895147d","cooking_tips":["豬扒切成相若約2厘米粒，厚粒要按中心熟度續煮，不以外面金黃判熟。","蒜蓉後下短炒，調味用材料表總量，不因試味而另添一份生抽。"],"pairing_suggestions":["可配「清炒菜心」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"af939a33-ebe9-4b4a-ae2d-07c46ba2331d","slug":"garlic-chicken-wings","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"07edc04ff9e047b9853ef14d6dc2a40c2048cb923bb73334f9e4d5787f5d177d","cooking_tips":["蒜蓉黏在雞翼上容易先焦，表面太快變深色便減火，不靠大火催熟近骨肉。","150克是生雞翼連骨重量，探針避開骨頭量最厚肉位至75°C至少30秒才完成。"],"pairing_suggestions":["可配「清炒椰菜」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"e383cfeb-cba5-46c0-a82d-4d9960433ad7","slug":"garlic-chicken-pasta","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"8cd6df878f0a143072bd406170804611402e727b6ee8e55b778eb9272eb990ba","cooking_tips":["雞胸先煎熟盛起，蒜片用原鑊餘下油以小火炒香，不陪雞肉全程大火煎。","煮粉水預留兩湯匙按需要調汁，所有鹽與黑胡椒按全份量分配，不在每段重複加。"],"pairing_suggestions":["本餐已包含主食，可配「清炒菜心」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"feb53292-415f-4e28-ae83-2f21d6fcbddb","slug":"garlic-chicken-xhs","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"57ba89948add752d29a57bef2cc42be9025aaf661b03a462da6cd7fdb104951a","cooking_tips":["雞胸切成相若厚度，蒜蓉醃在肉上容易先焦，表面上色太快便調低火力。","每面兩三分鐘只供參考，最厚雞片須熟透；生抽與生粉不再於煎好後加一次。"],"pairing_suggestions":["可配「清炒椰菜」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"f6620034-a8ac-4cde-a116-c1ccfd3bfd15","slug":"scallion-omelette-xhs","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"7ae952a49b0fc3a246798533a45bb304482b07e1ed2eff8c79a7833001c53cb2","cooking_tips":["蔥花拌入蛋液後攤成均勻薄層，等底面定形才翻，避免把蛋餅扯散。","兩面金黃後也要確認中心蛋液全熟，生抽與鹽按材料表全份總量分配。"],"pairing_suggestions":["可配「清炒椰菜」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"91132717-231d-4916-81ee-5e886b5ffd16","slug":"tomato-scrambled-egg","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"bcd9010c34771544576655c178feca024c95f2f29d591739c4c5143b4e6a4c76","cooking_tips":["蛋先盛起，等蕃茄軟化才回鑊，可避免雞蛋一直留在鑊中變韌。","想多一點天然蕃茄汁，可選成熟蕃茄並保留切出的汁液；本版不另加茄汁或生粉。"],"pairing_suggestions":["可配蒜蓉西蘭花及白飯；蛋已在這道菜內，不必為湊菜數再加一道蛋菜。"],"references":[{"title":"Made With Lau：Tomato & Eggs","url":"https://www.madewithlau.com/recipes/tomato-and-eggs"},{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}]},"changed_steps":[{"step_no":1,"old":"蕃茄切件，雞蛋打散，蛋液加入鹽少許。","text":"蕃茄洗淨切成大小相若的小件，保留汁液；兩隻雞蛋打散，拌入材料表的鹽1/8茶匙。"},{"step_no":2,"old":"鑊中加入 1 茶匙食油，中火倒入蛋液。","text":"易潔鑊加入全份1茶匙食油，中火燒熱後倒入蛋液，以鑊鏟由邊緣往中央輕推。"},{"step_no":3,"old":"蛋液半凝固時輕輕推開，炒至八成熟後盛起。","text":"蛋液大部分凝固、蛋塊仍柔軟時，先盛到乾淨碟上，稍後回鑊繼續煮。"},{"step_no":4,"old":"原鑊加入蕃茄，炒 2 至 3 分鐘至出汁。","text":"原鑊加入蕃茄，利用餘下的油炒約2至3分鐘；煮至邊緣軟化、開始出汁，可輕壓部分蕃茄。"},{"step_no":5,"old":"按需要加入選配糖，拌勻後試味。","text":"試味；如需要平衡酸味，可加入材料表的選配糖，最多半茶匙。"},{"step_no":6,"old":"放回炒蛋，快速拌勻後即上碟。","text":"雞蛋回鑊，轉中小火拌勻並繼續煮至雞蛋完全凝固、沒有流動蛋液，趁熱上碟。"}],"ingredient_changes":[],"old_recipe":{"description":"港式家常蕃茄炒蛋，酸甜開胃，送飯一流。"},"new_recipe":{"description":"先炒蛋、再煮蕃茄，最後拌合，讓蛋塊保留口感，蕃茄汁則可拌飯。糖屬選配，可按蕃茄本身的酸甜決定。"},"target_steps":[{"text":"蕃茄洗淨切成大小相若的小件，保留汁液；兩隻雞蛋打散，拌入材料表的鹽1/8茶匙。","step_no":1},{"text":"易潔鑊加入全份1茶匙食油，中火燒熱後倒入蛋液，以鑊鏟由邊緣往中央輕推。","step_no":2},{"text":"蛋液大部分凝固、蛋塊仍柔軟時，先盛到乾淨碟上，稍後回鑊繼續煮。","step_no":3},{"text":"原鑊加入蕃茄，利用餘下的油炒約2至3分鐘；煮至邊緣軟化、開始出汁，可輕壓部分蕃茄。","step_no":4},{"text":"試味；如需要平衡酸味，可加入材料表的選配糖，最多半茶匙。","step_no":5},{"text":"雞蛋回鑊，轉中小火拌勻並繼續煮至雞蛋完全凝固、沒有流動蛋液，趁熱上碟。","step_no":6}]},{"id":"57fb6db3-8712-4af9-b365-c0ac16b9b944","slug":"prepmeal-batch3-18","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"7792ca82ab391b83661958d035527720aa9b3fd7c42edaab83650f4ae54f5c12","cooking_tips":["醃雞與醬汁各用不同份量的生粉，先分好，避免把兩份都用在雞肉上。","醬汁入鑊前重新攪勻，蔥綠最後加入，雞片最厚中心熟透才起鑊。"],"pairing_suggestions":["可配「清炒椰菜」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"7975d3e4-6b85-428a-b7f0-8a9468d4302a","slug":"prepmeal-batch3-16","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"d8344f8b86b700e2492b3dcc8bf00c199ffe97a67b92e68fb05bbcd16b1decd3","cooking_tips":["豆腐切約1厘米片後排深碟蒸熱，薑蔥汁另鍋煮，避免先淋汁再把汁蒸得過稀。","蒸出的多餘水先小心倒走，再淋煮熱的薑蔥汁，避免淋面調味被沖淡。"],"pairing_suggestions":["可配「蒜蓉西蘭花」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"5a0bc693-4e74-404a-9203-7c6889470219","slug":"ginger-scallion-fish-napa-rice-vermicelli-soup","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"7d4fab6ff151c08670b78c17dace9c4e3bcef3610336872a3a7591c2f1e9e707","cooking_tips":["米粉按包裝先煮熟，白菜軟後才落魚，避免魚片為等米粉而久煮散爛。","魚片厚約1厘米並逐件放入，最厚中心須達75°C至少30秒，生抽及鹽按預留上限加。"],"pairing_suggestions":["本餐已包含主食，可配「蒜蓉西蘭花」；飯麵不必重複加一份。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"e678f804-19ee-4aad-a3c5-d69dcae9827d","slug":"potato-braised-chicken-wings","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"27c3bfa33a02df4ec2549a9aac309a05d5980e294a40730daa617ad1edf3490a","cooking_tips":["薯仔切成相若大小，雞翼先煎香後仍須跟水炆熟，不能只看外皮金黃。","雞翼不用流水沖洗；探針避骨檢查最厚肉部，薯仔也須軟熟才收汁。"],"pairing_suggestions":["這道菜已有薯仔，可配「蒜蓉生菜」；其他主食按整餐份量安排。"],"references":[]},"changed_steps":[{"step_no":1,"old":"雞中翼洗淨抹乾；薯仔去皮切件；蒜頭切蓉。","text":"雞中翼完全解凍後用廚紙抹乾，不用流水沖洗；薯仔去皮切件，蒜頭切蓉。處理生雞後清潔雙手及器具。"}],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":[{"text":"雞中翼完全解凍後用廚紙抹乾，不用流水沖洗；薯仔去皮切件，蒜頭切蓉。處理生雞後清潔雙手及器具。","step_no":1},{"text":"雞翼加入生抽、老抽、蠔油和糖拌勻，醃 10 分鐘。","step_no":2},{"text":"鑊中加入 1 茶匙食油，中火煎雞翼至兩面微金黃。","step_no":3},{"text":"加入蒜蓉和薯仔略炒 1 分鐘。","step_no":4},{"text":"加入 180 毫升水，煮滾後轉中小火加蓋炆 15 分鐘。","step_no":5},{"text":"開蓋收汁，薯仔軟身、雞翼熟透即可。","step_no":6}]},{"id":"789c4dc7-e011-4813-8385-0da404e939e4","slug":"minced-pork-potato","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"77bac2d6ea13b561cd0c66804420107f31afb56969a861b505b5f8919d81c839","cooking_tips":["薯仔先加40毫升水煮到接近軟熟，再加入肉碎，避免等生薯仔時把肉炒乾。","一茶匙半油分兩段用，豬肉碎炒散至全熟才加蔥，不另添醃料或鹽。"],"pairing_suggestions":["這道菜已有薯仔，可配「清炒菜心」；其他主食按整餐份量安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"dca04e7d-d817-4d7d-8c1b-c63aa7b1a0d8","slug":"creamy-mushroom-pasta","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"b48ae528baa589b7182e3588798a1d02139667755286d5dbe8d9d63c5fd3203e","cooking_tips":["蘑菇炒軟出香後才加奶與忌廉，避免把生菇水分全留在奶汁內。","芝士以小火拌至均勻，兩湯匙麵水按需要調稠度，不靠大滾把奶汁收乾。"],"pairing_suggestions":["本餐已包含主食，可配「蒜蓉西蘭花」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"37e2e10f-0ab4-4b81-982d-67f7500177b2","slug":"egg-fried-rice","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"66c934c9b06619a4a4477a5a5e50da0184258e3b9d99b085b7517ec1819bc68a","cooking_tips":["白飯先撥鬆，冷藏飯須妥善保存，炒至全份中心熱透而不是只見飯粒乾爽。","雞蛋先半熟後仍要與飯炒至完全凝固；生抽及蔥只在選用時加入。"],"pairing_suggestions":["本餐已包含主食，可配「蒜蓉生菜」；飯麵不必重複加一份。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}]},"changed_steps":[{"step_no":6,"old":"炒至飯粒乾爽不結塊即可。","text":"炒至蛋液完全凝固、飯粒散開，並確認全份飯中心達75°C並維持至少30秒後即食。"}],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":[{"text":"雞蛋打散，白飯預先撥鬆；如選用蔥，切粒備用。","step_no":1},{"text":"鑊中加入半湯匙食油，中火倒入蛋液炒至半熟。","step_no":2},{"text":"加入白飯，轉大火快速翻炒，把飯粒炒散。","step_no":3},{"text":"加入鹽1/8茶匙；如選用生抽，加入半茶匙調味。","step_no":4},{"text":"如選用蔥粒，加入炒勻。","step_no":5},{"text":"炒至蛋液完全凝固、飯粒散開，並確認全份飯中心達75°C並維持至少30秒後即食。","step_no":6}]},{"id":"113306c5-0ff0-4bc1-b363-e55487851d48","slug":"prepmeal-batch2-08","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"43ed9cc12678773ed88af7eb784fa168cb65e57008d3b274540b717c51351689","cooking_tips":["先用部分雞湯把沙律醬與生粉調開，入熱鍋時邊攪邊煮，避免結成粉團。","雞柳煎香後回醬汁仍須煮至中心75°C至少30秒，不因醬已濃便提早盛起。"],"pairing_suggestions":["可配「清炒菜心」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"2ff3f98b-58c0-46bf-8ff5-141d3addca04","slug":"prepmeal-batch3-08","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"bfd3a79a8b468aab5d03d5f2a50e99d5e7b5967999a0b35c94577e1ca73c64e8","cooking_tips":["蜜糖蒜汁另在中細火煮，豬扒前段煎香後仍須回汁煮至中心熟透。","骨邊或較厚肉處要分別檢查，含糖醬汁容易先變深色，不能以汁色判斷熟度。"],"pairing_suggestions":["可配「清炒芥蘭」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"147d483b-7b07-4f47-8fa8-5312423a27da","slug":"honey-chicken-wings","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"e57a34c4ce7bd74a83dda17c86dcbbd42cf6d9c77aaab203d461250d74b49023","cooking_tips":["雞翼顏色深不代表中心已熟，尤其生抽和蜜糖很容易先令表面上色。","蜜糖入鑊後保持小火並留意鍋底；醬汁已能掛在雞翼上便可停火。"],"pairing_suggestions":["可配蠔油生菜及白飯；雞翼醬汁已有甜味，不必再配另一道蜜汁菜。"],"references":[{"title":"李錦記香港：蜜糖雞中翼","url":"https://hk.lkk.com/zh-hk/recipes/honey-chicken-wing"},{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"},{"title":"食物安全中心：清潔、消毒與衞生","url":"https://www.cfs.gov.hk/tc_chi/consumer_zone/safefood_all/clean_hygiene.html"}]},"changed_steps":[{"step_no":1,"old":"雞中翼洗淨，用廚紙徹底抹乾。","text":"已完全解凍的雞中翼3隻，用廚紙印乾；不要放在流水下沖洗，以免生雞汁液濺到四周。處理後清潔雙手及器具。"},{"step_no":2,"old":"蒜頭切碎，加入豉油拌勻，放入雞翼醃 15 分鐘。","text":"蒜頭切碎，與1湯匙生抽拌入雞翼，放雪櫃醃約15分鐘。"},{"step_no":3,"old":"平底鑊加入 1 茶匙食油，中火放入雞翼，每面煎 3 至 4 分鐘。","text":"平底鑊加入1茶匙食油，中火煎雞翼，每面約3至4分鐘；先把黏在雞翼上的大粒蒜蓉留在醃料碗內，稍後同煮，避免煎焦。"},{"step_no":4,"old":"加入 30 毫升水，加蓋煮 5 分鐘，確保雞翼熟透。","text":"加入剩餘醃料、蒜蓉及30毫升水，煮滾後轉中小火，加蓋煮約5分鐘；時間只作參考，留意避免燒乾。"},{"step_no":5,"old":"加入 1 湯匙蜜糖，轉小火拌炒至雞翼表面有光澤。","text":"用食物溫度計量度最厚肉部，避開骨頭，中心達75°C並維持至少30秒。未熟便繼續加蓋煮；如水分不足，須補少量水並記錄實際用量，不能乾燒或只看表面顏色。"},{"step_no":6,"old":"收汁後關火，上碟即可。","text":"雞翼熟透後才加入1湯匙蜜糖，轉小火翻拌至表面均勻掛汁便關火，不必把蜜糖煮至深啡或乾硬。"}],"ingredient_changes":[{"old":{"id":"4d32e561-50ac-4bb4-be6e-43c12a72e397","name":"水","note":null,"unit":"ml","optional":false,"quantity":30},"new":{"id":"4d32e561-50ac-4bb4-be6e-43c12a72e397","name":"水","note":"起始煮食用水；鍋具蒸發較多時按需要少量補水，不增加油或醬料","unit":"ml","optional":false,"quantity":30}}],"old_recipe":{"description":"雞中翼以蒜蓉及生抽醃製，煎香後加水焗熟，再拌入蜜糖收汁。"},"new_recipe":{"description":"雞翼先煎香、再加蓋煮熟，最後才拌入蜜糖。把蜜糖留到收尾，較容易控制醬汁，不致一開始便煎焦。"},"target_steps":[{"text":"已完全解凍的雞中翼3隻，用廚紙印乾；不要放在流水下沖洗，以免生雞汁液濺到四周。處理後清潔雙手及器具。","step_no":1},{"text":"蒜頭切碎，與1湯匙生抽拌入雞翼，放雪櫃醃約15分鐘。","step_no":2},{"text":"平底鑊加入1茶匙食油，中火煎雞翼，每面約3至4分鐘；先把黏在雞翼上的大粒蒜蓉留在醃料碗內，稍後同煮，避免煎焦。","step_no":3},{"text":"加入剩餘醃料、蒜蓉及30毫升水，煮滾後轉中小火，加蓋煮約5分鐘；時間只作參考，留意避免燒乾。","step_no":4},{"text":"用食物溫度計量度最厚肉部，避開骨頭，中心達75°C並維持至少30秒。未熟便繼續加蓋煮；如水分不足，須補少量水並記錄實際用量，不能乾燒或只看表面顏色。","step_no":5},{"text":"雞翼熟透後才加入1湯匙蜜糖，轉小火翻拌至表面均勻掛汁便關火，不必把蜜糖煮至深啡或乾硬。","step_no":6}]},{"id":"1b704d61-0ed8-4944-9588-07f0eccf8dfb","slug":"shrimp-scrambled-eggs","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"1aea57372b429f2d4007ced788c624c10a92abc1d68f860377b11b2768bc44d2","cooking_tips":["蝦仁前段只炒到轉色，最後回蛋液時仍須把蝦中心與蛋液都煮熟。","鹽在醃蝦與蛋液之間分配，兩處合共不超過材料表總量，不各加一份。"],"pairing_suggestions":["可配「清炒椰菜」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"baba54c6-bfe8-4d29-ad94-a6140bc6e912","slug":"yangzhou-fried-rice","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"73a6a48bb43f94b28b02a932d13fc1b468ccf0072226f0a76dc871b234dcbbfb","cooking_tips":["蝦前段轉色不代表已熟，最後須煮至蝦全熟、蛋凝固、飯中心75°C至少30秒。","冷飯先撥鬆並確認妥善冷藏；蔥與生抽是選配，沒有選用便不用補進其他調味。"],"pairing_suggestions":["本餐已包含主食，可配「清炒菜心」；飯麵不必重複加一份。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"8edb64a0-ed7b-4292-9e34-38bc64bb6a20","slug":"shrimp-tofu-steamed-egg","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"d0f78f15f8ef84115a9dc713fe58afc956808104dd503abfb9b76e66a7551698","cooking_tips":["豆腐鋪底、蝦放面會令厚度不同，須檢查肉蛋交界的中心，不只看蛋面凝固。","蓋碗優先用耐熱碟；如用包覆材料，必須確認標示可蒸煮，不用一般保鮮紙接觸熱食。"],"pairing_suggestions":["可配「蒜蓉西蘭花」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[{"step_no":4,"old":"放上蝦仁，蓋上碟或保鮮紙。","text":"放上蝦仁，以耐熱碟蓋住蒸碗；如使用其他包覆材料，必須標示適合蒸煮，並按產品指示使用。"},{"step_no":6,"old":"蛋液凝固、蝦仁轉色熟透後即可。","text":"檢查最厚中心蛋液、蝦及配料均熟透；中心達75°C並維持至少30秒，未熟便繼續蒸，不能只看蛋面凝固。"}],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":[{"text":"豆腐切粒鋪在碗底，蝦仁洗淨抹乾。","step_no":1},{"text":"雞蛋打散，加入清水60毫升和鹽1/8茶匙，拌勻。","step_no":2},{"text":"將蛋液過篩倒入碗中，口感會更滑。","step_no":3},{"text":"放上蝦仁，以耐熱碟蓋住蒸碗；如使用其他包覆材料，必須標示適合蒸煮，並按產品指示使用。","step_no":4},{"text":"水滾後中小火蒸 10 至 12 分鐘。","step_no":5},{"text":"檢查最厚中心蛋液、蝦及配料均熟透；中心達75°C並維持至少30秒，未熟便繼續蒸，不能只看蛋面凝固。","step_no":6}]},{"id":"b8db6f3f-c794-4dee-8015-5b4b02175bc5","slug":"dried-shrimp-vermicelli-napa","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"5ac81142879fe2ed44947b4cb6048cab0849f452cc68ab7d3e81d4130ec89795","cooking_tips":["蝦米與粉絲分別浸軟後瀝乾，紹菜先炒至開始軟才加入粉絲吸汁。","粉絲按包裝煮透，吸到汁後保持濕潤便可，避免一直炆到鍋底乾焦。"],"pairing_suggestions":["這道菜已有乾綠豆粉絲，可配「蒜蓉生菜」；其他主食按整餐份量安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"4f78c647-2ea3-4ef2-a788-3c0773bcd603","slug":"crab-stick-egg-tofu","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"10f98ab27406fbb97cc602e3af0d53476174a85807fcda664a9453969405ffcf","cooking_tips":["蟹柳依包裝加熱要求處理，不因名稱有熟食印象就省略熱透。","豆腐下鍋後輕推，蛋液須完全凝固；蟹柳與生抽已有鹹味，鹽先試味再決定。"],"pairing_suggestions":["可配「清炒芥蘭」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"34e01988-7217-4251-b6ad-167648188e66","slug":"mushroom-in-oyster-sauce","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"08510f9c31888368a117a1530911eb7d6b36e781f9da00f1d5839dc3714db2c2","cooking_tips":["120克指鮮冬菇去硬蒂後重量，不把同重乾冬菇浸發後當同一份。","蠔油汁用60毫升水炆煮至菇熟透，生抽與糖只是選配，略收汁便可。"],"pairing_suggestions":["可配「蒸水蛋」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"ebadc314-8c21-4d4d-8af6-967cbe8b2275","slug":"prepmeal-batch4-03","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"5e238ee9cf4470da8a209274417261db63ee224af427bce8f7ff5f92a08fb51b","cooking_tips":["豆腐抹乾後先煎定形盛起，待椰菜與鮮菇熟軟才回鍋，避免反覆翻碎。","生粉醬汁入鑊前再攪勻，輕推至煮滾成薄芡，不在最後另淋未列的油。"],"pairing_suggestions":["可配「清炒芥蘭」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"86dd6cd9-46c7-431e-a671-5516b0558286","slug":"oyster-lettuce-xhs","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"6ffe004fe3ab8edb6faa8a2b2c131c10b1f44b6189a068f024e59bfe940e9415","cooking_tips":["蠔油先與定量水拌勻，較容易快速分布，避免一部分菜太鹹、另一部分未拌到汁。","生菜本身會出水，洗後盡量瀝乾；不要另加一大勺水把快炒變成炆煮。"],"pairing_suggestions":["可配豉汁蒸排骨或肉碎豆腐，再按需要配白飯。"],"references":[{"title":"李錦記台灣：蠔油的家常用法","url":"https://tw.lkk.com/zh-hk/cooking-stories/oyster-sauce-usage"}]},"changed_steps":[{"step_no":1,"old":"生菜逐片洗淨，瀝乾水份。","text":"生菜150克逐片洗淨，充分瀝水；較大的葉片撕成容易入口的大小。"},{"step_no":2,"old":"蒜頭切碎，準備蠔油1茶匙半。","text":"蒜頭切碎；蠔油1茶匙半與15毫升水先拌勻，放在爐邊備用。"},{"step_no":3,"old":"鑊中加入食油2茶匙，中火爆香蒜蓉。","text":"鑊中加入2茶匙食油，中火炒香蒜蓉，不要炒至深啡色。"},{"step_no":4,"old":"加入生菜大火快炒 30 秒至開始變軟。","text":"加入生菜，轉大火快速翻炒約30秒，讓葉片開始軟化。"},{"step_no":5,"old":"加入蠔油和 15毫升水，快速拌勻。","text":"加入已拌好的蠔油汁，快速拌勻並煮滾。"},{"step_no":6,"old":"生菜剛軟身即上碟，避免炒太久出水。","text":"菜葉熟透而較厚部分仍有少許爽口便盛起；不必留在鑊中等所有汁液收乾。"}],"ingredient_changes":[],"old_recipe":{"description":"蠔油生菜做法快速，鹹香清爽，是常見家常配菜。"},"new_recipe":{"description":"生菜以蒜蓉快炒，再拌少量蠔油汁，重點是葉片剛軟便盛起。洗後瀝乾，比長時間收汁更能避免一碟水。"},"target_steps":[{"text":"生菜150克逐片洗淨，充分瀝水；較大的葉片撕成容易入口的大小。","step_no":1},{"text":"蒜頭切碎；蠔油1茶匙半與15毫升水先拌勻，放在爐邊備用。","step_no":2},{"text":"鑊中加入2茶匙食油，中火炒香蒜蓉，不要炒至深啡色。","step_no":3},{"text":"加入生菜，轉大火快速翻炒約30秒，讓葉片開始軟化。","step_no":4},{"text":"加入已拌好的蠔油汁，快速拌勻並煮滾。","step_no":5},{"text":"菜葉熟透而較厚部分仍有少許爽口便盛起；不必留在鑊中等所有汁液收乾。","step_no":6}]},{"id":"46b73cec-0c16-4479-ba99-77780d7fe299","slug":"oyster-broccoli","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"fc88ce324d983e167a4f172a9338c8ea71fc1f2e9cfc667e7dd6b859b1f75a10","cooking_tips":["西蘭花汆後瀝乾才淋汁，較厚莖部須煮熟，不能只看顏色翠綠。","汆水不另加未分配的油鹽，煮汁與汆菜合共的油仍受材料表總量限制。"],"pairing_suggestions":["可配「孜然香辣烤豆腐」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[]},"changed_steps":[{"step_no":2,"old":"煲滾水，加入少量鹽和幾滴油，放入西蘭花汆水 1 至 2 分鐘。","text":"煲滾汆水用清水，放入西蘭花汆約1至2分鐘並按莖厚延長至熟；不另加未列的鹽或額外油。"},{"step_no":4,"old":"小鍋加入蠔油約 1 湯匙、清水15毫升和少量食油。","text":"小鍋加入材料表全份蠔油、清水15毫升及全份食油，小火拌勻。"}],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":[{"text":"西蘭花切小朵，沖洗乾淨後瀝乾。","step_no":1},{"text":"煲滾汆水用清水，放入西蘭花汆約1至2分鐘並按莖厚延長至熟；不另加未列的鹽或額外油。","step_no":2},{"text":"西蘭花變翠綠後撈起瀝乾，放上碟。","step_no":3},{"text":"小鍋加入材料表全份蠔油、清水15毫升及全份食油，小火拌勻。","step_no":4},{"text":"小火煮至醬汁微微冒泡並拌勻。","step_no":5},{"text":"將蠔油汁淋在西蘭花上即可。","step_no":6}]},{"id":"0b80929f-a8de-40cb-a7d0-135db34344a7","slug":"prepmeal-batch3-21","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"328a9b9b0683bb27b3958d0127984ec62fdf46c54a365ad16f86b7b2fad22bc1","cooking_tips":["豬肉先攤散煮熟，再加青椒與芽菜，不能把未熟肉與即將起鑊的芽菜一起拌。","芽菜須全熟，不為保留爽口只略翻幾下；生抽與蠔油後加拌勻，不額外加鹽。"],"pairing_suggestions":["可配「清炒芥蘭」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"cff160c9-1e99-4c9e-bbb6-d6143ec25e52","slug":"french-toast-scrambled-egg","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"49a2c7f162368c456a19453cb38211857e106d54e35d7029b3cb7383510c471e","cooking_tips":["麵包只短時間沾蛋液，不把整片浸至散開；兩面的蛋液與中心也要煎熟。","餘下蛋液另炒至完全凝固，前後共用材料表的兩隻蛋與全份牛油，不再加一份蛋。"],"pairing_suggestions":["本餐已包含主食，可配「清炒芥蘭」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[{"step_no":4,"old":"放入方包，每面煎 2 分鐘至金黃色，盛起。","text":"放入方包，兩面各先煎約2分鐘至金黃，再按厚度續煎至麵包表面及中心沾附的蛋液均熟透，盛起。"},{"step_no":6,"old":"用小火慢慢推炒蛋液，煮至剛凝固仍然濕潤即可。","text":"用小火慢慢推炒餘下蛋液，煮至完全凝固、沒有流動生蛋液後盛起。"}],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":[{"text":"將 2 隻雞蛋打入碗中，加入 30 毫升牛奶和少量鹽拌勻。","step_no":1},{"text":"將方包兩面沾上蛋液，每面約 5 秒，不要浸太久。","step_no":2},{"text":"平底鑊加入一半牛油，小火煮溶。","step_no":3},{"text":"放入方包，兩面各先煎約2分鐘至金黃，再按厚度續煎至麵包表面及中心沾附的蛋液均熟透，盛起。","step_no":4},{"text":"同一個鑊加入餘下牛油，倒入剩餘蛋液。","step_no":5},{"text":"用小火慢慢推炒餘下蛋液，煮至完全凝固、沒有流動生蛋液後盛起。","step_no":6},{"text":"將西多士和炒蛋一同上碟即可。","step_no":7}]},{"id":"d4089cde-3615-47b0-a1a6-a71b92211509","slug":"watercress-preserved-duck-gizzard-soup","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"096e30ae521da3df59af2292d162e07c19fe079a60760558baa0c75e31cd077b","cooking_tips":["鮮鴨腎去內膜後秤50克，不能用鹽醃陳腎按同重替代，鹹度與材料性質不同。","湯最後調到400毫升再連全部可食湯料享用；排骨骨頭不吃，菜與鴨腎也須熟透。"],"pairing_suggestions":["可配「肉碎豆腐」與「清炒椰菜」，再按需要配主食；本頁的湯不是另外的飯量。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"e3345160-5e9a-45ab-b6aa-41926d5a36d0","slug":"prepmeal-batch2-17","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"d139bb9dc676981a632d413ff2d2ba49549bc2fc69a4581acf85529c6589aa70","cooking_tips":["筍須用已煮熟可即用產品，不能把未處理生竹筍切丁直接代入快湯。","太白粉用8毫升冷水另調，蛋白細流加入後煮至凝固，不把整碗一口氣倒成蛋塊。"],"pairing_suggestions":["可配「照燒雞扒」與「蒜蓉西蘭花」，再按需要配主食；本頁的湯不是另外的飯量。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"1ca7b32b-2375-4436-9b26-59db03a06801","slug":"prepmeal-25-25-spinach-chickpeas","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"003e381fb94da82dbbddccde671f95fdb7fa0cb450b27dab8026b0aa274cf86e","cooking_tips":["熟鷹嘴豆沖淨瀝乾，乾豆不能同重直接替代；菠菜後下才不會陪豆炒太久。","煙燻紅椒粉與蒜短炒出香，雪莉醋離火才拌，不讓粉在油中先焦黑。"],"pairing_suggestions":["可配「薑蔥豉油蒸豆腐（簡易版）」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"d4e1d9ef-3604-47fa-8d58-9d9e407cc802","slug":"prepmeal-batch2-06","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"d942ba6ef3d5bb345f01d5633f5abd4b817aae8e3c135dccb6be0611c019221c","cooking_tips":["薯仔與洋蔥先煮軟才拌蛋，蛋餅不靠外面金黃來保證內部生薯仔也熟。","用平碟翻面時托穩並小心熱油，回鑊後中心蛋液仍須完全凝固。"],"pairing_suggestions":["這道菜已有薯仔，可配「蒜蓉西蘭花」；其他主食按整餐份量安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"8a2e7e8e-095e-40db-89ba-d3619461c541","slug":"prepmeal-batch4-13","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"ea92f3f638ddc355df6122a67c76cf0241d1f9ab9873f3cf6169827836f9c37f","cooking_tips":["魷魚短汆捲起只是前段處理，回鍋仍須煮至全熟，但不為收乾汁一直久炒。","西芹斜切薄、彩椒先煮至熟，再回魷魚，避免海鮮為等厚菜片而變韌。"],"pairing_suggestions":["可配「蒜蓉生菜」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"afcc4ab8-edbb-4229-9790-a6d4b1a201d9","slug":"prepmeal-batch2-11","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"a2e4a10c94aa84e4fc1e5eb96172dcd17b0c826f2c12991cad8c43ac2522b403","cooking_tips":["蝦轉色後先盛起，回鍋仍要煮至中心全熟；芡水入鑊前再攪勻。","腰果最後才拌入，保持乾爽口感，不陪西芹及湯汁整段炆煮。"],"pairing_suggestions":["可配「蒜蓉西蘭花」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"ca6d6562-82db-4db9-b437-b9c0f2b22dca","slug":"broccoli-shrimp-steamed-egg","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"b227de092adf926f2de98e9b4742b0bbf5bae301ba34c478e3372f3ca07a31f9","cooking_tips":["西蘭花先短汆並瀝乾才放蒸碗，避免汆水沖淡定量蛋液。","以耐熱碟蓋碗，檢查中心蛋液與蝦均全熟；若用包覆材料須標示適合蒸煮。"],"pairing_suggestions":["可配「清炒芥蘭」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[{"step_no":5,"old":"蓋上碟或保鮮紙，水滾後中小火蒸 10 至 12 分鐘。","text":"以耐熱碟蓋碗，水滾後中小火蒸約10至12分鐘；其他包覆材料必須標示適合蒸煮，並按產品指示使用。"},{"step_no":6,"old":"蛋液凝固、蝦仁熟透後即可。","text":"檢查最厚中心蛋液、蝦及配料均熟透；中心達75°C並維持至少30秒，未熟便繼續蒸，不能只看蛋面凝固。"}],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":[{"text":"西蘭花切小朵，蝦仁洗淨抹乾，雞蛋打散。","step_no":1},{"text":"西蘭花用滾水汆燙 1 分鐘，瀝乾後放入蒸碗。","step_no":2},{"text":"蛋液加入清水60毫升和鹽1/8茶匙，拌勻後過篩。","step_no":3},{"text":"將蛋液倒入碗中，放上蝦仁。","step_no":4},{"text":"以耐熱碟蓋碗，水滾後中小火蒸約10至12分鐘；其他包覆材料必須標示適合蒸煮，並按產品指示使用。","step_no":5},{"text":"檢查最厚中心蛋液、蝦及配料均熟透；中心達75°C並維持至少30秒，未熟便繼續蒸，不能只看蛋面凝固。","step_no":6}]},{"id":"e45784b5-3593-4509-acc3-a2e02d3089b6","slug":"tofu-egg-pancake","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"17fdd2642e9e32370b1c4283bef3ba2da9a317d2427f0f97483fd330769e39a1","cooking_tips":["豆腐先吸走多餘水分再拌蛋，不用未列出的生粉補救過濕蛋糊。","蛋餅鋪薄，底面定形才翻；兩面金黃後仍檢查中心蛋液已熟透。"],"pairing_suggestions":["可配「清炒菜心」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[{"step_no":6,"old":"小心翻面再煎 2 至 3 分鐘，兩面金黃即可。","text":"小心翻面再煎約2至3分鐘，按厚度延長至中心蛋液全熟；食物中心達75°C並維持至少30秒後上碟。"}],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":[{"text":"豆腐用廚紙吸乾水份後壓碎，雞蛋打散，蔥切粒。","step_no":1},{"text":"將豆腐、蛋液、蔥花和鹽少許放入碗中拌勻。","step_no":2},{"text":"如材料太濕，先把豆腐多餘水分瀝去，再與蛋液拌勻；不另加未列入材料表的生粉。","step_no":3},{"text":"平底鑊加入少量油，中小火加熱。","step_no":4},{"text":"倒入材料後鋪平，煎 3 至 4 分鐘至底部定型。","step_no":5},{"text":"小心翻面再煎約2至3分鐘，按厚度延長至中心蛋液全熟；食物中心達75°C並維持至少30秒後上碟。","step_no":6}]},{"id":"78974fcd-ba79-402e-b6aa-2e0572c708e8","slug":"tofu-egg-napa-cabbage-rolls","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"e37a28ed2f0fd50f1b0ef028ea4ad1bb9a9e2701876f060c797e94072a6ed060","cooking_tips":["炒熟的豆腐蛋餡先略放涼再包，白菜厚梗削薄，避免硬梗把卷口頂開。","四至六卷合共一人份，收口朝下排，最厚卷心須達75°C至少30秒，薄汁另煮熟。"],"pairing_suggestions":["可配「清炒菜心」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"047b77a1-6e33-44c0-8a74-c773b2463412","slug":"minced-pork-with-green-beans","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"35ef9720468a4399d38effe4fabeb4e042967ebfb80c4671b2734f521212739c","cooking_tips":["四季豆先煮至全熟盛起，肉碎另炒熟才合拌，不以表面起皺代替內外熟透。","88克肉碎與一茶匙半油都是全份量，分段炒時把油分開用，不額外加鹽醃肉。"],"pairing_suggestions":["可配「清炒椰菜」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[{"title":"食物安全中心：未煮熟豆類中的天然毒素","url":"https://www.cfs.gov.hk/tc_chi/multimedia/multimedia_pub/multimedia_pub_fsf_139_04.html"}]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"d42a4d9c-317d-4dd1-9f7b-6169db0a5fc8","slug":"long-bean-scrambled-egg","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"dda60ceb795a3fcd52a6053c7946b09065c9e6d9538f1bd368ea56b98bf39445","cooking_tips":["豆角粒仍須煮至內外熟透才倒蛋，三四分鐘不適用所有粗幼或品種。","雞蛋拌入後也要完全凝固，不能為豆角保留生硬爽脆而提早起鑊。"],"pairing_suggestions":["可配「蒜蓉生菜」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[{"title":"食物安全中心：未煮熟豆類中的天然毒素","url":"https://www.cfs.gov.hk/tc_chi/multimedia/multimedia_pub/multimedia_pub_fsf_139_04.html"}]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"5f8c5b9f-a044-4919-b954-c4bcd49e12de","slug":"prepmeal-batch4-04","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"5369ba0e4988d3e385cb991f2316c7fa17e375e9386a2175732bf8f12a719e1d","cooking_tips":["涼瓜鋪底、排骨單層鋪面，排骨不疊厚堆，讓熱力較均勻到達近骨肉。","蒸約二十分鐘及焗五分鐘只是參考，最厚肉部仍須達75°C至少30秒。"],"pairing_suggestions":["可配「清炒菜心」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"060b93b5-2fa9-449a-8c7d-724ef1daddb8","slug":"dace-lettuce-stir-fry","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"210e673e5f4fe3ac277b20a3032f8fe86da50a5b059e9fe1ede021875935fa0f","cooking_tips":["50克是去豆豉並瀝走罐油後的魚肉重量，不把罐油全倒入炒鑊。","油麥菜瀝水快炒，罐頭魚拆開熱透便可，生抽按定量用，不另加豆豉或鹽。"],"pairing_suggestions":["可配「清炒芥蘭」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"3ef3f87b-8dbb-40b5-b97d-95e23426d426","slug":"black-bean-clams","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"ab32a3dd363f492a92c79c0a60617ff96761970a3d5f1d59feb7bada2ce55dca","cooking_tips":["蜆須煮至徹底熟透，開殼不是唯一終點，不能一見全部開口便立即上碟。","煮後仍不開殼的蜆棄掉；生抽與豆豉已有鹹味，吐沙鹽水要倒走。"],"pairing_suggestions":["可配「清炒椰菜」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}]},"changed_steps":[{"step_no":5,"old":"加入生抽、糖和水，加蓋煮 2 至 3 分鐘。","text":"加入生抽、糖及材料表的水，加蓋煮至湯汁重新沸騰，再保持滾煮至少5分鐘，確認蜆肉熟透；留意鍋內水量，避免燒乾。"},{"step_no":6,"old":"蜆全部開口後即可上碟，未開口的蜆不要吃。","text":"蜆肉徹底煮熟後才上碟，不能一見開殼便停火；煮後仍不開殼的蜆棄掉。"}],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":[{"text":"蜆用鹽水浸 20 分鐘吐沙，再沖洗乾淨。","step_no":1},{"text":"豆豉壓碎，蒜頭切蓉，青椒切件。","step_no":2},{"text":"鑊中加入食油，中火爆香蒜蓉和豆豉。","step_no":3},{"text":"加入蜆和青椒，大火快炒。","step_no":4},{"text":"加入生抽、糖及材料表的水，加蓋煮至湯汁重新沸騰，再保持滾煮至少5分鐘，確認蜆肉熟透；留意鍋內水量，避免燒乾。","step_no":5},{"text":"蜆肉徹底煮熟後才上碟，不能一見開殼便停火；煮後仍不開殼的蜆棄掉。","step_no":6}]},{"id":"abca2600-75a8-42a0-bf3c-579f01ed80c0","slug":"prepmeal-batch4-15","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"b76ea8515f2ea6df8780af4f9081edbc1382132e7bdc93f3e5386fbe22c93e27","cooking_tips":["雞球前段兩面轉色未必已熟，回鍋後檢查最厚中心，不在暫盛時即食。","現成豆豉醬按指定份量用，甜椒及洋蔥先炒軟再回雞，不用多添一份醬。"],"pairing_suggestions":["可配「清炒椰菜」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"68c07822-4ff1-41fb-a225-735dea948702","slug":"black-bean-steamed-pork-ribs","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"6749fcea78d5374ded7b6b5baa00b92244246943ea2bbe4229b2e8ce5f22ef3a","cooking_tips":["排骨疊起來會令受熱不均；增加份量時，先用較大的蒸碟保持單層。","豆豉本身有鹹味，本版不另加鹽；試味應在排骨及醬汁煮熟後進行。"],"pairing_suggestions":["可配蒜蓉西蘭花及白飯；配菜選清淡做法，較容易與豉汁味道配合。"],"references":[{"title":"Made With Lau：Steamed Spare Ribs","url":"https://www.madewithlau.com/recipes/steamed-spare-ribs"},{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"},{"title":"食物安全中心：清潔、消毒與衞生","url":"https://www.cfs.gov.hk/tc_chi/consumer_zone/safefood_all/clean_hygiene.html"}]},"changed_steps":[{"step_no":1,"old":"排骨沖洗後瀝乾，放入碗中。","text":"排骨180克為連骨生重；請店舖斬成大小相若的小件，檢查並去除可見骨碎，用廚紙印乾表面。"},{"step_no":2,"old":"加入豆豉、蒜蓉、生抽、糖、生粉和食油拌勻。","text":"豆豉按材料備註略沖後瀝乾並壓碎；蒜頭切蓉，與生抽、糖、生粉及食油拌入排骨。"},{"step_no":3,"old":"醃 15 分鐘，讓排骨入味。","text":"放入雪櫃醃約15分鐘，準備蒸鍋及耐熱碟。"},{"step_no":4,"old":"將排骨平鋪在碟上，不要疊太厚。","text":"排骨平鋪成一層，不要堆疊；醃料一併放入碟內。"},{"step_no":5,"old":"水滾後放入蒸鍋，中大火蒸 18 至 20 分鐘。","text":"水滾後放入蒸碟，中大火蒸約18至20分鐘；蒸煮期間留意鍋內水量，避免燒乾。"},{"step_no":6,"old":"排骨完全熟透、肉邊無血色即可上碟。","text":"用食物溫度計量度最厚肉部的中心，避開骨頭及碟面，達75°C並維持至少30秒；大件或未達溫度的排骨須繼續蒸，不能只看肉色判熟。"}],"ingredient_changes":[],"old_recipe":{"description":"排骨以豉汁蒸至入味，肉香配豆豉鹹香，適合配飯。"},"new_recipe":{"description":"豆豉與蒜蓉拌入排骨後，平鋪蒸熟，豉汁可拌飯。排骨斬件大小及是否重疊，會影響蒸熟所需時間。"},"target_steps":[{"text":"排骨180克為連骨生重；請店舖斬成大小相若的小件，檢查並去除可見骨碎，用廚紙印乾表面。","step_no":1},{"text":"豆豉按材料備註略沖後瀝乾並壓碎；蒜頭切蓉，與生抽、糖、生粉及食油拌入排骨。","step_no":2},{"text":"放入雪櫃醃約15分鐘，準備蒸鍋及耐熱碟。","step_no":3},{"text":"排骨平鋪成一層，不要堆疊；醃料一併放入碟內。","step_no":4},{"text":"水滾後放入蒸碟，中大火蒸約18至20分鐘；蒸煮期間留意鍋內水量，避免燒乾。","step_no":5},{"text":"用食物溫度計量度最厚肉部的中心，避開骨頭及碟面，達75°C並維持至少30秒；大件或未達溫度的排骨須繼續蒸，不能只看肉色判熟。","step_no":6}]},{"id":"221c4285-a059-4efe-b606-1604101236e2","slug":"black-bean-steamed-fish-fillet","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"cfa4799689fd5fb71b424c620abe2a3ad3f5220502e06f258a20be898c2e466e","cooking_tips":["豆豉略沖瀝乾後拍碎並鋪勻，避免魚上有一粒集中過鹹的豆豉。","蒸魚時間受厚度影響，最厚中心須熟透，不只看表面變白或容易分開。"],"pairing_suggestions":["可配「清炒菜心」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"6aee29f1-6829-4d7a-a2c0-d43c5abc5fb8","slug":"prepmeal-batch4-08","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"29a14d2d101db8a2a85cbcfa6e7e82233a86936b1b5f1a44b71a34f8989d35b5","cooking_tips":["免醃版直接炒薄牛肉，不另外補入生粉或未列醃料。","番茄炒至略軟時仍檢查牛肉全熟，清酒經短炒不保證已完全無酒精。"],"pairing_suggestions":["可配「清炒椰菜」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"2144aa30-8efd-4f60-8228-cff67b5556b6","slug":"soybean-sprout-stir-fry","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"9e478b95417cbce2d5bce612aea34889c5e9270a42f1ac7d4a050f0417a92aeb","cooking_tips":["芽菜瀝乾才下鑊，蒜蓉只先短炒出香，避免大火把蒜煎黑。","芽菜須徹底煮熟才吃，不為保留爽脆而只拌熱表面。"],"pairing_suggestions":["可配「豆腐雞蛋白菜卷」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"a390d711-a5af-48a4-9a74-1f18c94ac3c0","slug":"soy-sauce-fried-noodles","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"578009100a16172c8b606923aa82e2943c0c379f8c52dd94260cd0bbd1e1bb80","cooking_tips":["180克是已煮熟、瀝乾後的麵重，不用同重乾麵直接代入。","芽菜先炒後仍要隨麵炒至全熟，生抽老抽與15毫升水先拌勻，不再另加一份醬。"],"pairing_suggestions":["本餐已包含主食，可配「清炒椰菜」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"8719bd8b-6d94-46c1-ac4b-a072b7153382","slug":"pork-cabbage-stir-fry","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"e1f68bd1f7b980c81425d550798e4bf8081b264546aa1c2a89966399f33acce3","cooking_tips":["豬肉先攤散，再與椰菜煮至全熟，不能只見菜軟便略過肉片熟度。","本版以材料表的生抽與蠔油調味，不額外加入未列出的生粉醃肉。"],"pairing_suggestions":["可配「清炒芥蘭」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[{"step_no":1,"old":"豬肉切片，加入生抽約 1 茶匙和生粉少許拌勻，醃 10 分鐘。","text":"豬肉切薄片，加入材料表生抽的一半拌勻，放雪櫃醃10分鐘；本版不加入生粉。"},{"step_no":5,"old":"加入生抽約 1 茶匙、蠔油約 1 茶匙和少量水。","text":"加入餘下生抽及材料表的蠔油拌勻，調整火力避免燒焦，不再加入另一份調味料。"},{"step_no":6,"old":"炒至椰菜軟身但仍有口感即可上碟。","text":"炒至椰菜熟軟而仍有口感，並確認豬肉中心達75°C並維持至少30秒後上碟。"}],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":[{"text":"豬肉切薄片，加入材料表生抽的一半拌勻，放雪櫃醃10分鐘；本版不加入生粉。","step_no":1},{"text":"椰菜洗淨切粗絲，蒜頭切片。","step_no":2},{"text":"鑊中加少量油，中火炒香蒜片和豬肉至豬肉轉色。","step_no":3},{"text":"加入椰菜，轉大火快炒 2 至 3 分鐘。","step_no":4},{"text":"加入餘下生抽及材料表的蠔油拌勻，調整火力避免燒焦，不再加入另一份調味料。","step_no":5},{"text":"炒至椰菜熟軟而仍有口感，並確認豬肉中心達75°C並維持至少30秒後上碟。","step_no":6}]},{"id":"a3ad014f-a834-438b-8b6b-d8483f0e6441","slug":"prepmeal-batch2-10","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"7525c4c52f7b4e08530011414d19d2b1122a9f57587da981fd241611a8835f55","cooking_tips":["焦糖到琥珀色便留意火力，變黑會帶苦味，加入液體時小心蒸氣與濺油。","魚段連骨，翻動要輕並注意細骨，炆至最厚肉處熟透，不以糖色判熟。"],"pairing_suggestions":["可配「清炒菜心」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"5d018a6a-749a-4fa9-abf1-d8b793a0e2a1","slug":"prepmeal-25-18-lemongrass-pork","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"4e82ad8fc8be8effd03fb11c0c5c563c386354f3118e7d469c0221530b9d49e3","cooking_tips":["香茅、葉片與乾蔥切極幼再醃，避免煎好後留下難咬的大段香料。","豬扒拍至約1厘米厚，六分鐘只作參考，最厚中心須熟透，不只看表面焦香。"],"pairing_suggestions":["可配「清炒椰菜」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"48416608-d870-4b65-9f3f-4349ae800f89","slug":"lemon-spicy-pan-fried-chicken","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"8c1f031c4f75a44de566062994f1a7316fcf89d28ac22a4eb2b6c3193fcc2139","cooking_tips":["先確認雞肉熟透才倒入檸檬醬，醬汁只短時間翻拌，不靠酸汁代替煮熟。","雞肉按材料表的去皮去骨用量備料，檸檬片只在選用時加入，不把帶皮雞扒直接代入。"],"pairing_suggestions":["可配「清炒菜心」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"c09336c5-4868-4d6a-88e4-32313529d11d","slug":"vinegar-potato-xhs","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"0f64379c095904cbec40241097ca9ca5694b38e9d2b393794eaba08c34394bd4","cooking_tips":["薯絲切得粗細相若，浸後瀝乾再炒，才不會有幾條仍生硬。","爽脆不代表可吃生薯絲，須把薯絲煮熟後才加醋收尾，不只按兩分鐘停火。"],"pairing_suggestions":["這道菜已有薯仔，可配「清炒椰菜」；其他主食按整餐份量安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"9b0f088d-e8b1-4829-95f0-4b71f6d83a32","slug":"steamed-skinless-chicken-thigh-enoki","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"5b8400e71c6566a7506be402ea7397b2abe4950b70dbd865e79d344974b2fa26","cooking_tips":["金菇拆散鋪底，雞肉連醃料盡量單層排，避免蒸出內部難熟的厚團。","雞肉中心須達75°C至少30秒；這道菜沒有主食，不能把整碟雞與菇直接當成完整飯餐。"],"pairing_suggestions":["可配「蒜蓉西蘭花」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"b30cbb08-e3b0-4f1f-8474-d16487b945ac","slug":"prepmeal-batch2-16","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"c9f65e65e25ab59f0e2c25840c893c636f15548069db0c9cac00c0643ddc0c17","cooking_tips":["金菇分成小束才捲肉，收口先向下煎定形，不做成又粗又厚的肉卷。","肥牛外面上色後仍要煮熟卷心及金菇，鍋乾時按步驟少量加水加蓋。"],"pairing_suggestions":["可配「蒜蓉生菜」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"fb5189f8-1561-402d-8fd6-edf8d828a94b","slug":"enoki-tofu-pot","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"0ed7aea240d7db304a2ca50796c30c0a70c1bacab9f08b2aabc65140afb21b2e","cooking_tips":["金針菇去根拆散，先炒軟再加30毫升水煮至全熟，不把整束厚根略煮便吃。","豆腐加入後輕推拌汁，中心熱透便略收汁，不大力翻炒至豆腐全碎。"],"pairing_suggestions":["可配「清炒菜心」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"8024a51f-d8a6-4458-9ac0-2f162e528f3e","slug":"prepmeal-batch4-01","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"e42bf4ec05909976afd8be39182d473fe4042dfaeb4e89fc3aab333423512759","cooking_tips":["生鹹蛋先分蛋黃與蛋白，蛋黃較早下，蛋白最後攪散後仍須完全煮熟。","本版用清水而非高湯，鹹蛋已有鹹味，不再補鹽或雞粉。"],"pairing_suggestions":["可配「蒸水蛋」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"944d3601-a283-4522-a4df-af284132058d","slug":"prepmeal-batch4-21","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"db89cc3556d07ad0e6a56b5d27a99c07c09c5e9f3629fdfee81978d4b3f61ec2","cooking_tips":["雞柳粗約5毫米，前段炒兩分鐘只是初步受熱，之後仍要跟蔬菜煮至全熟。","辣豆瓣醬已調味，不另加鹽；芽菜、甜豆及粟米筍都要煮熟，不只把菜拌熱。"],"pairing_suggestions":["可配「清炒菜心」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"50b7a0f7-2951-4fbf-aac1-c43114fb8b28","slug":"mushroom-tofu-choy-sum-udon-soup","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"e05fe84200a11824e4e2f8907df766c4cf20cc77d31a68be16a19e862050edb9","cooking_tips":["菜心梗與豆腐先煮熱，再放菜葉，粗梗需要延長而不是一直煮爛薄葉。","烏冬另按包裝煮透瀝乾，湯底600毫升不與烚麵水相加，調味只用預留上限。"],"pairing_suggestions":["本餐已包含主食，可配「蒜蓉西蘭花」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"8ee3207f-a816-40e9-8180-6eaef318e17e","slug":"vegetable-udon","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"6a6663ca8e63ca69ef98c97daa5913002fd94ed9a70b551ced34c937768fbf0a","cooking_tips":["烏冬按實購包裝加熱鬆開，不能把需要煮熟的產品只沖散便當即食。","甘筍與洋蔥先炒，菇菜熟後再拌麵與定量醬汁，避免麵先黏底而菜仍生。"],"pairing_suggestions":["本餐已包含主食，可配「清炒椰菜」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"b333f252-424a-40a3-a160-23c287de07f4","slug":"vegetable-egg-fried-rice","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"e650606894bd13d7533d77804a126fac0347e7e5fc8564bf512df1cad404774d","cooking_tips":["甘筍切細粒並先炒軟才下飯，避免飯已炒好但甘筍仍硬。","蛋液與白飯都要徹底煮熟熱透，生抽與鹽仍按全份量，不以乾爽作唯一完成標準。"],"pairing_suggestions":["本餐已包含主食，可配「蒜蓉西蘭花」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[{"step_no":6,"old":"炒至飯粒乾爽即可。","text":"炒至雞蛋完全凝固、甘筍及其他菜熟透、飯中心達75°C並維持至少30秒後即食。"}],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":[{"text":"洋蔥和甘筍切粒，雞蛋打散，白飯預先撥鬆。","step_no":1},{"text":"鑊中加入食油2茶匙，中火炒香洋蔥和甘筍。","step_no":2},{"text":"加入粟米粒炒勻，再倒入蛋液炒散。","step_no":3},{"text":"加入白飯，大火炒至飯粒分開。","step_no":4},{"text":"加入生抽1湯匙和材料表所列的鹽，拌勻調味。","step_no":5},{"text":"炒至雞蛋完全凝固、甘筍及其他菜熟透、飯中心達75°C並維持至少30秒後即食。","step_no":6}]},{"id":"d1d32280-ebf7-4525-a777-81734e9a08ba","slug":"chicken-rice-plate","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"c64f76f07c3f04048bdee9eaacd45da17f4e93c7db18b4736586ac076761b1c0","cooking_tips":["雞扒厚位先攤平，表面煎金黃後仍檢查中心熟度，不能只多蓋兩分鐘便視為保證。","180克白飯已列入本餐，雞扒靜置後切件，使用乾淨砧板及夾子盛熟食。"],"pairing_suggestions":["本餐已包含主食，可配「蒜蓉西蘭花」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"a3571df6-9864-4d74-b140-70f0c52bcd6a","slug":"salt-baked-chicken-wings","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"58b1ee46963a74fc65790d8dc2bfe0a7d58b72fafe343885ec9b316a667233e8","cooking_tips":["雞粉與全份油已拌在三件雞翼上，焗盤或焗架不用再塗多一份油。","雞翼分開排、途中翻面，最厚肉部避骨達75°C至少30秒，不靠外面金黃判熟。"],"pairing_suggestions":["可配「清炒椰菜」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"a8d4792f-c55f-4b96-a4b8-3d7ad91dc085","slug":"chicken-congee","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"3191412003fc33ab1d313e25394357c19df795d6690d372b170917767f86f538","cooking_tips":["白米在湯中煮至開花再落雞絲，雞肉不用陪米從頭煲到尾。","雞絲撥散後仍須全熟，粥滾時攪至鍋底避免黏焦，小心熱粥飛濺。"],"pairing_suggestions":["這道菜已有白米，可配「清炒芥蘭」；其他主食按整餐份量安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"d3a86877-a40b-4fc0-8166-ad66bbad89c2","slug":"shredded-chicken-rice-vermicelli","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"2d61e15e5b91debe73da3c08f87a643b3c52abe6aaa10c788b5bd4678cc749b0","cooking_tips":["雞絲醃料只用全份生抽的三分之一，餘下才炒米粉，不在最後再加一全份。","米粉按包裝浸煮至熟，雞絲轉色後仍須煮熟，不能只把粉炒乾爽便起鑊。"],"pairing_suggestions":["本餐已包含主食，可配「清炒椰菜」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[{"step_no":5,"old":"加入米粉、餘下生抽及少量清水，炒至米粉熱透。","text":"加入米粉、餘下生抽及材料表最多15毫升選配清水，炒至米粉熱透。"}],"ingredient_changes":[{"old":null,"new":{"id":"4d32e561-50ac-4bb4-be6e-43c12a72e397","name":"水","quantity":15,"unit":"ml","note":"步驟已使用的煮食水；按材料表總量分配，不另計浸洗或倒走的汆水","optional":true}}],"old_recipe":{},"new_recipe":{},"target_steps":[{"text":"米粉用溫水浸軟後瀝乾；雞胸肉、洋蔥和甘筍切絲。","step_no":1},{"text":"雞絲加入材料表生抽的1/3份量拌勻，醃5分鐘；餘下留作炒米粉。","step_no":2},{"text":"鑊中加入 1 茶匙食油，中火炒雞絲至轉色。","step_no":3},{"text":"加入洋蔥和甘筍炒 1 至 2 分鐘。","step_no":4},{"text":"加入米粉、餘下生抽及材料表最多15毫升選配清水，炒至米粉熱透。","step_no":5},{"text":"炒至雞絲全熟、米粉乾爽即可。","step_no":6}]},{"id":"054d6c0a-3c09-4f83-8efe-b3292db846c8","slug":"chicken-salad","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"5a5ae18df5bc8250980e98cdbb735649ac01b9621c1b173c372f02bced7e391d","cooking_tips":["雞胸先煮熟，再用乾淨砧板切片，不讓生雞器具接觸洗好的即食菜。","沙律菜充分瀝乾，食前才加醬；熟雞稍降溫不代表可把整碗長放室溫。"],"pairing_suggestions":["本餐已包含主食，可配「清炒芥蘭」；飯麵不必重複加一份。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}],"served_cold":true},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"0285dc52-d7f1-4b68-9332-b433130df09e","slug":"chicken-tofu-egg-pancake","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"5131d950cefded3f50496e75974a1891ebbbdc6296a6d8802cb4d9c47bdff019","cooking_tips":["豆腐先瀝乾再拌碎雞胸與蛋，餅糊較容易定形，不隨意加粉補救。","兩三小餅合共一人份，壓至相若厚度，最厚中心須達75°C至少30秒。"],"pairing_suggestions":["可配「蒜蓉西蘭花」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"aed121cd-4a81-4c2f-aa2e-e04fab6b0ee4","slug":"prepmeal-batch2-03","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"41e546d5f6c47e89aac093599db5913859d0fec9cd99ef72fccf71fd895b4f77","cooking_tips":["先確認電飯煲可煮75克米，按機器要求調水，不因機器最低量高而自行增加材料。","煮飯鍵跳起不保證大雞腿中心已熟，近骨最厚肉部須達75°C至少30秒，未熟另加熱。"],"pairing_suggestions":["本餐已包含主食，可配「蒜蓉西蘭花」；飯麵不必重複加一份。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"00cb4a29-ed39-4f18-9df6-e8ce2fb32dfd","slug":"thai-green-curry-chicken","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"0c10003e190db3da63b144e0613da27e138a175db4892c8da813162e65322beb","cooking_tips":["青咖哩醬先短炒出香，雞肉轉色後仍要在椰奶中煮熟。","茄子熟軟、最厚雞件也全熟才完成，不因醬汁已濃便停火。"],"pairing_suggestions":["可配「蒜蓉西蘭花」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"b52a24e0-573a-4158-9297-bf4f09a74b73","slug":"green-pepper-scrambled-egg","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"19d48335cce18f67cb9a7cc16d30d1d44d7c0bb25ed440b40b75c72ff225304e","cooking_tips":["雞蛋先半熟盛起，青椒炒軟後回鑊煮至蛋完全凝固，不保留生蛋液。","一半油炒蛋、另一半炒椒，兩段合共原定總量，不每次再倒一份。"],"pairing_suggestions":["可配「清炒椰菜」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"0c392024-c491-45d9-bac5-393f9095f160","slug":"kung-pao-chicken","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"0963660a2fdb6279b11a45eb3b81554d015c3bfbe9a4179a759fb504571d92d2","cooking_tips":["20毫升水分成醃雞5毫升與炒菜15毫升，不在兩段各加20毫升。","雞丁攤開炒，最厚中心75°C至少30秒才完成，青椒微軟不是雞肉熟度判斷。"],"pairing_suggestions":["可配「清炒椰菜」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"0aeb44cd-f33f-4b3a-bc87-8a7581c026a6","slug":"green-pepper-beef","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"702179e157186d6e0c40747e9246884de65e2ad38dcc9103944d0ae41414be42","cooking_tips":["20毫升水先分醃牛5毫升及回鍋15毫升，油也分兩段，不重複用全份。","牛肉前段轉色後仍須回鑊煮熟，鹽是選配，不在已有蠔油汁外再無限加鹽。"],"pairing_suggestions":["可配「清炒椰菜」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"e803d48f-061d-414f-8376-5fab42bf1f4d","slug":"cucumber-scrambled-egg","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"737a74fc7db0b2a2775dc0e6698559603b71ef20940b5940ce99815265c6f2eb","cooking_tips":["青瓜切成相若薄片，炒蛋先盛起，瓜只短炒便回蛋，避免青瓜久炒出大量水。","蛋回鑊後仍須煮至完全凝固，爽口只用來描述已熟青瓜，不代表雞蛋可半生。"],"pairing_suggestions":["可配「清炒菜心」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"7c45d020-507b-4f8b-888b-167f2d8e68de","slug":"cucumber-shredded-chicken-soba","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"75964d77171f26ee81679de3cd6f2b75e0d095ee2078f23b5ee39ff0462bc3ae","cooking_tips":["熟麵沖涼須用飲用水或凍滾水，雞肉、菜及熟麵使用分開的乾淨器具。","雞肉先煮至75°C至少30秒再撕絲，拌好即食或及時冷藏，不把醋汁當成保鮮步驟。"],"pairing_suggestions":["本餐已包含主食，可配「蒜蓉西蘭花」；飯麵不必重複加一份。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}],"served_cold":true},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"0dde3fb7-ae93-4abe-a2da-8553582c0ec1","slug":"pesto-vegetable-pasta","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"bed83d7909b5e34373db05258c204f73a432147f4ebe29a25fd87f4b94cb2a92","cooking_tips":["櫛瓜與蘑菇先煮熟，車厘茄後下短炒，避免所有菜一起久煮出水。","青醬與芝士拌勻掛粉即可，預留麵水逐少調整，不再倒入未列出的高湯。"],"pairing_suggestions":["本餐已包含主食，可配「清炒菜心」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"77a0840e-85af-4529-8719-4adfb9947821","slug":"prepmeal-batch3-19","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"73de26845d8792f8c7d56130d17dfa47c10e0d5e4a5157f06803ca01433fb47a","cooking_tips":["三個飯糰合共一人份，不把每個當成獨立一份再多包三倍。","熟飯須安全保存及徹底翻熱，拌吞拿魚醬後即食或及時冷藏，不為口感在室溫久放。"],"pairing_suggestions":["本餐已包含主食，可配「清炒椰菜」；飯麵不必重複加一份。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"f80ecbf2-ce52-4c35-a264-79eb0206422b","slug":"prepmeal-25-06-bibimbap","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"27112c72176acf0add1b1e1b57d906a1c4040c4f5b99dfb9e1f6714516c7da2e","cooking_tips":["牛肉用糖與拌飯醬用糖分開量好，炒菜油在各種配料之間分配，不能每鍋用全份。","牛肉、蛋與芽菜分別煮熟才鋪飯，雞蛋不採半熟；紫菜只在選用時加。"],"pairing_suggestions":["本餐已包含主食，可配「清炒椰菜」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"33ce56c8-d05c-49a9-b8e2-eb6499bcbdd8","slug":"prepmeal-25-07-japchae","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"a6118fe1e707c16e6f21041c42794220ea40413ec8ca700ee9ef5e1bf78d139f","cooking_tips":["乾番薯粉絲按包裝煮透再剪短，不用同重已泡粉絲或綠豆粉絲直接替代。","肉類屬選配，選用時先另煮熟再拌；菠菜擠乾後才與粉絲合炒，避免水太多。"],"pairing_suggestions":["本餐已包含主食，可配「蒜蓉生菜」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"10fdbf67-c387-49b9-8b48-ee775454eff5","slug":"kimchi-egg-tofu","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"b8b237c68b3c71516541b70e0ac5c6a6c686df7a8f3ad0a9528be074ab3bcf38","cooking_tips":["豆腐先煮熱再倒蛋，加入後輕推，避免為炒散雞蛋而把豆腐全部打碎。","蛋液須完全凝固才盛起，泡菜與生抽已有鹹味，不再補未列出的鹽。"],"pairing_suggestions":["可配「清炒椰菜」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"8f07d643-e558-47d0-b5e1-9ecabe16e68f","slug":"kimchi-fried-rice","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"33fb9396674bf50651c6d21104908f77fb29872917804df473b45b21b9a7fc98","cooking_tips":["泡菜先切細炒香，白飯預先撥鬆，才較容易均勻拌入酸辣味。","蛋液半凝固後仍須與飯炒至全熟，整份飯熱透才吃，不只看飯粒乾爽。"],"pairing_suggestions":["本餐已包含主食，可配「蒜蓉生菜」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[{"step_no":6,"old":"炒至飯粒乾爽入味即可。","text":"繼續炒至蛋液完全凝固、飯中心達75°C並維持至少30秒，整份熱透後即食，不只看飯粒乾爽。"}],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":[{"text":"泡菜切細，白飯預先撥鬆，雞蛋打散。","step_no":1},{"text":"鑊中加入 1 茶匙食油，中火炒香泡菜 1 分鐘。","step_no":2},{"text":"加入白飯，大火炒散至飯粒分開。","step_no":3},{"text":"將飯推到一邊，倒入蛋液炒至半凝固。","step_no":4},{"text":"將蛋和飯炒勻，加入生抽1茶匙調味。","step_no":5},{"text":"繼續炒至蛋液完全凝固、飯中心達75°C並維持至少30秒，整份熱透後即食，不只看飯粒乾爽。","step_no":6}]},{"id":"3ba9d74a-4d7a-460f-bb7b-3811b72f87a1","slug":"prepmeal-25-11-kimchi-pancake","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"c5674aac3a8992587dbd3ce801d724a429a8235f3226b936952810c54937aa06","cooking_tips":["泡菜汁與水都按材料表加入，不因麵糊太稠先無限加泡菜汁改鹹度。","餅糊攤薄後等底面定形才翻，翻面補的油是餘下半份，中心麵糊要煎熟。"],"pairing_suggestions":["可配「豆腐雞蛋白菜卷」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"5b4f8238-1df2-4521-878f-bb9ed73b19fa","slug":"kimchi-tofu-soup-xhs","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"1e9c0973278d27aa04bfbe0ac6be7be4ab1b91b9bf905958a2c48ec7b83d57e4","cooking_tips":["300毫升總水量分前段煮泡菜及後段湯底使用，不在兩段各倒一份。","豆腐煮至中心熱透才試味，泡菜本身鹹度不一，鹽按材料表上限分次加。"],"pairing_suggestions":["可配「蒸水蛋」與「蒜蓉西蘭花」，再按需要配主食；本頁的湯不是另外的飯量。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"dca619a0-d617-487b-a86a-27078b798e13","slug":"prepmeal-25-10-haemul-pajeon","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"b0fdaf3858b655c992c35b5e9d1ce1c0aa6f95f9fe67d8381a5fc4ca1bf58eeb","cooking_tips":["水與高湯是替代方案，選高湯便取代全部89毫升水，不把兩者累加。","蔥餅中心的海鮮、蛋與麵糊都須熟透，翻面用寬鏟托穩，不能只煎兩面金黃。"],"pairing_suggestions":["可配「蒜蓉生菜」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"ddc92d24-dbf7-4b11-8152-9fc0b7f61944","slug":"prepmeal-batch2-15","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"825763cb7b90608d8324a466d62bd6211c6e05b5e8596ab6721aaad03e25f88a","cooking_tips":["芽菜須煮至全熟再用可飲用冷水降溫，短汆時間按份量延長，不保留生硬中心。","瀝乾輕擠才拌麻油與魚露，拌好保持冷藏，不能因名為涼拌便使用生芽菜。"],"pairing_suggestions":["可配「豆腐雞蛋白菜卷」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}],"served_cold":true},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"c89ac925-09a7-4dea-8c05-ebac60b8d310","slug":"prepmeal-batch3-03","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"4e4f587166e20ab6dadf79ed05d022210b87c7b0d5cedd859a218dda6137dda4","cooking_tips":["翠玉瓜切成約5毫米半月片，讓瓜片在短炒時間內熟軟，不把厚片直接沿用相同時間。","麻油、芝麻與蔥留到收尾拌入，瓜熟而有口感便起鑊，不煮到完全出水散開。"],"pairing_suggestions":["可配「豆腐雞蛋白菜卷」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"05c72cc2-74c5-45af-87b2-6fb8c999581b","slug":"prepmeal-batch4-06","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"d71732d40b54bfe0032a6423d749e097fd61e443939dd1fff019d89ecc3e6d13","cooking_tips":["25克全蛋拌餡，餘下25克全蛋與約9克蛋黃作外層，兩份蛋液不要一開始全倒入肉餡。","六至八塊薄餅合共一人份，油分批用；碰過生肉的蛋液不能直接淋在熟餅上。"],"pairing_suggestions":["可配「清炒椰菜」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"4edc9c30-d4bb-4f0a-b5e2-5cf72b4c02d7","slug":"korean-spicy-chicken","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"fe270c8342c3fcb5e240217d19ecfcaf7e39f50dd5c68d16d5a55ab4791d179f","cooking_tips":["雞肉醃料含糖與辣醬，表面太快變深色便降火，不用大火一直把醬炒乾。","雞肉前段轉色後仍須煮至最厚中心熟透，洋蔥先炒香可減少雞肉久留鑊。"],"pairing_suggestions":["可配「清炒菜心」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"446124e6-ac8b-462d-8a3b-1ed34173379b","slug":"prepmeal-25-20-spicy-squid","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"f96adb22fd74b482d8afd205da3a5079c8605545bc1d2be9bc4f13c22f6d57b3","cooking_tips":["魷魚150克按已清理可食重量量取，不能用同重帶內臟整隻魷魚直接代入。","蔬菜先炒，再下魷魚與醬，煮至海鮮全熟便收尾，避免為收汁一直炒韌。"],"pairing_suggestions":["可配「蒜蓉生菜」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"be9dfc90-1ab4-4504-9507-c370e5d11197","slug":"prepmeal-25-08-gochujang-pork","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"7bc4213f9bcef9e1be5dee818f5b5208e9fe13d30cd15eab61923d1f59d1e8d6","cooking_tips":["豬肩肉切薄並攤散分批炒，不把一大碗醃肉堆滿鑊令中心難熟。","醃料有蜜糖與糖，火太猛容易先焦黑；熟透後汁略掛面便停火，不追求燶邊。"],"pairing_suggestions":["可配「清炒椰菜」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"4198438f-c136-4c39-a5fc-cd2b1e850b7e","slug":"prepmeal-25-09-gamja-jorim","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"0d9533506c10b118746d6248b68daa72c300fcf2a55e53ec3399f7e31758bb9f","cooking_tips":["薯仔與紅蘿蔔大小相若，先煮到接近軟熟才下洋蔥與甜椒，避免配菜先煮爛。","肉類只是選配，選用時先另煮熟才合拌，不能在最後收汁時加生肉。"],"pairing_suggestions":["這道菜已有薯仔，可配「蒜蓉生菜」；其他主食按整餐份量安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"b6d8af51-cd40-4cc5-a5cb-8e4da0967b28","slug":"luncheon-meat-egg-instant-noodles","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"56ebc682b01393b73d38733d88b3432a1816b83d678e257905c3aee0514c3043","cooking_tips":["雞蛋蛋白與蛋黃均須煮熟，打蛋後一兩分鐘不能保證所有蛋都已全熟。","麵餅與調味包按實購包裝分開處理，營養是否包括粉包要依本頁材料備註，不再加未列醬料。"],"pairing_suggestions":["本餐已包含主食，可配「蒜蓉西蘭花」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[{"step_no":4,"old":"打入雞蛋，轉中火煮 1 至 2 分鐘。","text":"打入雞蛋，轉中火煮至蛋白及蛋黃完全凝固、午餐肉熱透；原來一兩分鐘只作參考，未熟便繼續煮。"}],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":[{"text":"午餐肉切片，蔥切粒。","step_no":1},{"text":"煲中加入水，煮滾後放入公仔麵。","step_no":2},{"text":"煮 2 分鐘後加入午餐肉。","step_no":3},{"text":"打入雞蛋，轉中火煮至蛋白及蛋黃完全凝固、午餐肉熱透；原來一兩分鐘只作參考，未熟便繼續煮。","step_no":4},{"text":"如所用公仔麵附有調味包，可按包裝建議及口味分次加入；沒有附調味包則不另加未列出的調味料。","step_no":5},{"text":"灑上蔥粒即可上碗。","step_no":6}]},{"id":"67b6aef3-9215-41ce-afcf-fdd2d66e4907","slug":"pan-fried-scallops","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"2ed8a4e924e877a8151f7526d76abc8958a6e7ca7d69c9a006fae78dd1496d90","cooking_tips":["帶子先完全解凍並印乾，未定形前少移動，才較容易保持完整。","外面金黃不代表厚帶子中心已熟，按厚度續煎至全熟，牛油後加入避免先焦黑。"],"pairing_suggestions":["可配「清炒菜心」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"eb7fb246-3225-4947-9710-a7f4cc47271d","slug":"pan-fried-king-oyster-xhs","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"2b6e6fdc832c2b9d80523a7f6b0952cd1f1f492d0605c53c2464eff6dfe93194","cooking_tips":["菇片切成約0.5厘米厚並排開，先等一面定形才翻，避免一直翻動炒出大量水。","生抽在小火下拌入，按材料表總量用，不因試味再另加一份。"],"pairing_suggestions":["可配「蒸水蛋」及白飯，把這道菜作蔬菜配搭；各道份量另按餐單安排。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"66990dbc-a04f-4603-a738-a1ded916f07c","slug":"pan-seared-pork-chop-with-apple-onion-sauce","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"a01d999adc3259eaa409866c2834892325c3f619aeae53b4cb11b0317e6cb4e8","cooking_tips":["豬扒先煎至中心熟透盛起，蘋果與洋蔥另炒軟，不讓豬扒陪整段做汁時間。","糖是選配，蘋果本身有甜味，先試熟汁再決定是否用半茶匙。"],"pairing_suggestions":["可配「蒜蓉西蘭花」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"6570b737-3fbc-4670-956f-d0e52559fe11","slug":"pan-fried-chicken-breast-xhs","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"5ce4d9b422597b999c5380ad0e1af5f5c6ab0990f7911c597675226b4de8b2e8","cooking_tips":["雞胸先拍至厚度平均，避免厚端未熟而薄端已煎乾。","加蓋一兩分鐘仍只是參考，最厚中心須達75°C至少30秒，靜置後以乾淨器具切片。"],"pairing_suggestions":["可配「清炒椰菜」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"a8e0f8cb-4272-4f4d-984a-b4acbfb355da","slug":"garlic-chicken-with-vegetables","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"3bcc65072c6465d4a6773c0dd959750a2251a7972eb9ef506c0b338c29448abe","cooking_tips":["雞胸先煮熟盛起，西蘭花與甘筍切小，較厚菜梗也須熟透，不只炒到表面上色。","橄欖油在雞肉與炒菜之間分配，鹽胡椒也按全份總量，不每一鍋重複加全份。"],"pairing_suggestions":["可配「清炒菜心」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"1dca6ca8-fefb-4f10-a615-0eb92c222139","slug":"pan-fried-sea-bream-fillet","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"06b02001639c4f0ed17490672862ea76ec7ade5c2f1093567be8c557a0459bbc","cooking_tips":["魚柳抹乾再煎，未定形前不要反覆搬動，減少魚肉散開。","每面三四分鐘按厚度調整，最厚中心熟透才盛起，選配檸檬汁按一茶匙用量。"],"pairing_suggestions":["可配「清炒菜心」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"b91ad24d-b706-4eb1-b3a8-d247b8c0f1a7","slug":"herb-pan-fried-cod","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"b394da0cd9c990ac2cf16b21880c2b616d1d7a3d10ee465ffeda183ed362f028","cooking_tips":["鱈魚肉較易散，先讓一面定形才翻，不不停用鑊鏟撥弄。","魚柳不要為回溫而長放室溫；最厚中心須熟透，表面變白只作輔助觀察。"],"pairing_suggestions":["可配「清炒芥蘭」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"6fa12fd1-ac3b-4d8b-a2d3-ac8b6459c35e","slug":"sesame-oil-mushroom-chicken-rice","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"90cab1e83d678602a4825f99bc94bb1e97e68a6c641866bdbc5dcbcbc1596f33","cooking_tips":["75克是生白米，鮮冬菇40克不用當成乾冬菇先浸大份量；本版不加米酒或其他菇。","煮飯程序完成仍要量雞肉中心75°C至少30秒，米與雞都熟透才拌鬆。"],"pairing_suggestions":["本餐已包含主食，可配「蒜蓉生菜」；飯麵不必重複加一份。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"68623080-6a5f-4a3c-b109-49c0c270b7e9","slug":"prepmeal-batch4-10","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"8c8d6f8e6f92d82330b12970dcb1b45e6935bec6f67f1efc70a300531d0489c6","cooking_tips":["乾長通粉在定量水與番茄茸中煮，依包裝所需時間攪到底，避免底層黏焦而上層仍硬。","吞拿魚80克是瀝乾重量，麵熟後才加入熱透；預留水不足時依步驟逐次補熱水。"],"pairing_suggestions":["本餐已包含主食，可配「蒜蓉生菜」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"be32a7bc-91be-4945-a15f-8c0d36fbeeab","slug":"tomato-pork-chop-rice","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"ebabcdb93a45c0fa76c31570b8fb1be47e88d2b375fb03e8dd770b74d142127f","cooking_tips":["豬扒先煎熟才回鮮茄汁略煮，不靠酸甜茄汁或最後一分鐘把厚生肉煮熟。","糖、生粉與生抽分配在醃肉與做汁之間，仍按材料表總量，不在每一步另加一份。"],"pairing_suggestions":["本餐已包含主食，可配「蒜蓉生菜」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[{"step_no":4,"old":"加入番茄醬約 1 湯匙、少量水和糖少許，煮成醬汁。","text":"加入番茄醬約 1 湯匙、材料表最多15毫升選配水和糖少許，煮成醬汁。"}],"ingredient_changes":[{"old":null,"new":{"id":"4d32e561-50ac-4bb4-be6e-43c12a72e397","name":"水","quantity":15,"unit":"ml","note":"步驟已使用的煮食水；按材料表總量分配，不另計浸洗或倒走的汆水","optional":true}}],"old_recipe":{},"new_recipe":{},"target_steps":[{"text":"豬扒拍鬆，加入生抽 1 茶匙、糖少許和生粉少許拌勻，醃 10 分鐘。","step_no":1},{"text":"平底鑊加 1 茶匙油，中火將豬扒兩面煎至金黃熟透，取出切件。","step_no":2},{"text":"原鑊加入洋蔥炒香，再加入蕃茄炒 2 至 3 分鐘至出汁。","step_no":3},{"text":"加入番茄醬約 1 湯匙、材料表最多15毫升選配水和糖少許，煮成醬汁。","step_no":4},{"text":"放回豬扒略煮 1 分鐘，讓醬汁包住豬扒。","step_no":5},{"text":"將白飯放入碟中，鋪上豬扒和鮮茄醬汁即可。","step_no":6}]},{"id":"26e8f9ed-c5d9-4b24-930e-fc6045a11f5b","slug":"salted-fish-steamed-pork-patty","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"edaa0732ccb8179795c966ced28449d29aa48d995b61b4d164fe1805f169a00d","cooking_tips":["肉餡攪至有黏性後攤薄，鹹魚碎拌勻分布，避免一小口過鹹。","鹹魚與豬肉都須煮熟，肉餅中心達75°C至少30秒；蒸十二分鐘不適用厚肉團。"],"pairing_suggestions":["可配「清炒椰菜」及白飯；如要加湯，可選「海帶豆腐湯」，各道份量分開計。"],"references":[{"title":"食物安全中心：烹煮及翻熱","url":"https://www.cfs.gov.hk/tc_chi/trade_zone/safe_kitchen/Cooking_and_reheating.html"}]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"24a17129-1fb6-4168-9f0a-4239b45a1dcb","slug":"mapo-tofu","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"7b7f2f1c3d0ba8999a71a087507b7275e14c79108ab60f8bca9f938478ade1e5","cooking_tips":["豆腐下鑊後用輕推代替大力炒，肉碎先炒散並在醬汁中繼續煮熟。","豆瓣醬已有鹹味，調味依材料表總量；生粉先用預留水調開，不直接灑乾粉入熱汁。"],"pairing_suggestions":["可配「蒜蓉西蘭花」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[{"step_no":1,"old":"豆腐切成約 2 厘米方塊，蒜頭切蓉。","text":"從全份75毫升煮食水中先取15毫升冷水拌勻1茶匙生粉；豆腐切約2厘米方塊，蒜頭切蓉。"},{"step_no":2,"old":"煲滾水，加入少量鹽，放入豆腐汆水 1 分鐘後瀝乾，這樣較不易碎。","text":"另煲汆水用清水，不另加鹽，將豆腐汆約1分鐘後瀝乾；汆水倒去，不算入75毫升煮食水。"},{"step_no":4,"old":"加入豆瓣醬1湯匙，炒出香味。","text":"加入豆瓣醬1湯匙及材料表的糖半茶匙，炒勻出香，避免燒焦。"},{"step_no":5,"old":"加入豆腐和少量水，輕輕推勻，不要大力翻炒。","text":"加入豆腐、餘下60毫升水及材料表的生抽1茶匙，輕推拌勻，不大力翻碎。"},{"step_no":6,"old":"煮 4 至 5 分鐘至豆腐入味，如不夠鹹可加少量生抽調整。","text":"煮約4至5分鐘至豆腐熱透、肉碎全熟；不再為試味另加超出材料表的生抽。"},{"step_no":7,"old":"最後可用少量生粉水收汁，煮至醬汁掛在豆腐上即可。","text":"預留生粉水再攪勻後慢慢加入，煮滾至薄芡，確認全鍋中心達75°C並維持至少30秒後上碟。"}],"ingredient_changes":[{"old":null,"new":{"id":"4d32e561-50ac-4bb4-be6e-43c12a72e397","name":"水","quantity":75,"unit":"ml","note":"煮食用水總量；15毫升開生粉水，60毫升煮豆腐，不含倒走的汆水","optional":false}}],"old_recipe":{},"new_recipe":{},"target_steps":[{"text":"從全份75毫升煮食水中先取15毫升冷水拌勻1茶匙生粉；豆腐切約2厘米方塊，蒜頭切蓉。","step_no":1},{"text":"另煲汆水用清水，不另加鹽，將豆腐汆約1分鐘後瀝乾；汆水倒去，不算入75毫升煮食水。","step_no":2},{"text":"鑊中加少量油，中火炒香蒜蓉和肉碎，炒至肉碎轉色。","step_no":3},{"text":"加入豆瓣醬1湯匙及材料表的糖半茶匙，炒勻出香，避免燒焦。","step_no":4},{"text":"加入豆腐、餘下60毫升水及材料表的生抽1茶匙，輕推拌勻，不大力翻碎。","step_no":5},{"text":"煮約4至5分鐘至豆腐熱透、肉碎全熟；不再為試味另加超出材料表的生抽。","step_no":6},{"text":"預留生粉水再攪勻後慢慢加入，煮滾至薄芡，確認全鍋中心達75°C並維持至少30秒後上碟。","step_no":7}]},{"id":"0ce59d40-dca2-4637-94a6-e482978c9228","slug":"black-pepper-beef-with-mashed-potatoes","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"27b9f875aa2498475d389ea094c3a851c73814a95c21a1d7e465f5e10775f9ed","cooking_tips":["薯仔先煮軟並瀝水再壓蓉，牛奶逐少拌入，避免一次倒多令薯蓉變稀。","牛柳粒每面三四十秒只作參考，最厚中心須熟透；薯蓉已在本餐，不必另配一碗飯。"],"pairing_suggestions":["本餐已包含主食，可配「清炒椰菜」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[{"step_no":6,"old":"起鍋前再補黑胡椒，與薯蓉一同上碟。","text":"確認最厚牛肉粒中心達75°C並維持至少30秒，按大小調整時間後上碟；不能只用每面數十秒或外皮焦香判斷已熟。"}],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":[{"text":"薯仔去皮切塊，放入冷水中煮 12 至 15 分鐘至熟軟。","step_no":1},{"text":"牛肉切粒，用鹽少許和大量黑胡椒調味。","step_no":2},{"text":"薯仔瀝乾後壓成蓉，加入牛油、牛奶和鹽少許拌勻，保持溫熱。","step_no":3},{"text":"平底鑊大火加熱，加入橄欖油後放入牛柳粒。","step_no":4},{"text":"牛柳粒每面煎約 30 至 45 秒，煎至表面焦香。","step_no":5},{"text":"確認最厚牛肉粒中心達75°C並維持至少30秒，按大小調整時間後上碟；不能只用每面數十秒或外皮焦香判斷已熟。","step_no":6}]},{"id":"6d9a3e2d-31d9-4621-aef0-856038c1373b","slug":"black-pepper-beef-xhs","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"957d7964306624c75f6d4917c789dcd7bdf851a6daf983f13a6b322bf1ce8538","cooking_tips":["生抽、生粉與黑胡椒先分出醃肉部分，餘下才在炒肉時加，不重複用全份。","薄肉片攤開炒至全熟，太乾時按步驟少量補水，不為收乾所有汁而一直炒韌。"],"pairing_suggestions":["可配「清炒菜心」及白飯；如要加湯，可選「菠菜豆腐湯」，各道份量分開計。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"a78f5d98-d9a6-4c9d-907c-1269ae8f4c88","slug":"prepmeal-batch4-17","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"9606b8c45d647ac29a8b5ae024c93545e2a5afa5bf4548e2efa42473a85dda33","cooking_tips":["30毫升雞湯是調醬用，烚烏冬水另計並瀝走，不能混作同一份湯底。","牛肉前段轉色後仍須回鍋煮熟，粉水醬汁入鑊前再攪勻，不用未列調味補醬。"],"pairing_suggestions":["本餐已包含主食，可配「蒜蓉生菜」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null},{"id":"e57873c3-9d2f-4b5e-9da2-c3d42d52cf33","slug":"prepmeal-25-24-chicken-fajitas","guidance":{"version":1,"reviewed_on":"2026-11-13","review_method":"desk_review_not_test_cooked","source_fingerprint":"c95fb4a85223ea773cd6b82b32449731eaf9e5b8c0598cd0b8f3808b1e8c9687","cooking_tips":["雞肉先切薄炒熟，再與已炒軟的洋蔥彩椒合拌，薄餅另依包裝加熱。","牛肉或蝦是替代雞肉的選項，不是三種蛋白全部同加；薄餅已是本餐主食。"],"pairing_suggestions":["本餐已包含主食，可配「清炒椰菜」；飯麵不必重複加一份。"],"references":[]},"changed_steps":[],"ingredient_changes":[],"old_recipe":{},"new_recipe":{},"target_steps":null}]$editorial_payload$::jsonb);
DO $rollback$
DECLARE rec record; item jsonb; rid uuid; current_steps jsonb; n integer;
BEGIN
 PERFORM id FROM public.recipes WHERE id IN(SELECT (p->>'id')::uuid FROM editorial_rollback) ORDER BY id FOR UPDATE;
 PERFORM id FROM public.recipe_steps WHERE recipe_id IN(SELECT (p->>'id')::uuid FROM editorial_rollback) FOR UPDATE;
 PERFORM id FROM public.recipe_ingredients WHERE recipe_id IN(SELECT (p->>'id')::uuid FROM editorial_rollback) FOR UPDATE;
 FOR rec IN SELECT p FROM editorial_rollback LOOP
  rid:=(rec.p->>'id')::uuid;
  IF NOT EXISTS(SELECT 1 FROM public.recipes WHERE id=rid AND source_data->'editorial_guidance'=rec.p->'guidance') THEN RAISE EXCEPTION 'Rollback metadata precondition changed'; END IF;
  IF rec.p->'target_steps'<>'null'::jsonb THEN
   SELECT jsonb_agg(jsonb_build_object('step_no',step_no,'text',text) ORDER BY step_no) INTO current_steps FROM public.recipe_steps WHERE recipe_id=rid;
   IF current_steps IS DISTINCT FROM rec.p->'target_steps' THEN RAISE EXCEPTION 'Rollback step precondition changed'; END IF;
  END IF;
  IF EXISTS(SELECT 1 FROM jsonb_each_text(rec.p->'new_recipe') e JOIN public.recipes r ON r.id=rid WHERE to_jsonb(r)->>e.key IS DISTINCT FROM e.value) THEN RAISE EXCEPTION 'Rollback recipe precondition changed'; END IF;
 END LOOP;
 FOR rec IN SELECT p FROM editorial_rollback LOOP
  rid:=(rec.p->>'id')::uuid;
  FOR item IN SELECT value FROM jsonb_array_elements(rec.p->'changed_steps') LOOP
   UPDATE public.recipe_steps SET text=item->>'old' WHERE recipe_id=rid AND step_no=(item->>'step_no')::integer AND text=item->>'text';
  END LOOP;
  FOR item IN SELECT value FROM jsonb_array_elements(rec.p->'ingredient_changes') LOOP
   IF NOT EXISTS(SELECT 1 FROM public.recipe_ingredients ri JOIN public.units u ON u.id=ri.unit_id WHERE ri.recipe_id=rid
       AND ri.ingredient_id=(item->'new'->>'id')::uuid AND ri.quantity=(item->'new'->>'quantity')::numeric
       AND ri.is_optional=(item->'new'->>'optional')::boolean AND ri.prep_note IS NOT DISTINCT FROM item->'new'->>'note' AND u.code='ml') THEN
     RAISE EXCEPTION 'Rollback water precondition changed';
   END IF;
   IF item->'old'='null'::jsonb THEN
    DELETE FROM public.recipe_ingredients WHERE recipe_id=rid AND ingredient_id=(item->'new'->>'id')::uuid;
   ELSE
    UPDATE public.recipe_ingredients SET prep_note=item->'old'->>'note' WHERE recipe_id=rid AND ingredient_id=(item->'old'->>'id')::uuid;
   END IF;
  END LOOP;
  UPDATE public.recipes SET source_data=source_data-'editorial_guidance',
    description=CASE WHEN rec.p->'old_recipe' ? 'description' THEN rec.p->'old_recipe'->>'description' ELSE description END,
    method=CASE WHEN rec.p->'old_recipe' ? 'method' THEN rec.p->'old_recipe'->>'method' ELSE method END WHERE id=rid;
 END LOOP;
END $rollback$;
COMMIT;
